export interface Point2 {
  x: number;
  y: number;
}

export interface TwoBoneIKResult {
  upperWorldAngle: number;
  lowerRelativeAngle: number;
  lowerWorldAngle: number;
  projectedTip: Point2;
  requestedDistance: number;
  solvedDistance: number;
  clamped: boolean;
}

const EPSILON = 1e-8;

/** Keep a descending foot/ankle target inside the horizontal slice of a rigid
 * two-link reach circle. This preserves the requested height and shortens only
 * the over-committed forward/backward placement, avoiding the diagonal IK
 * projection that otherwise leaves a heel visibly hovering above the floor. */
export function clampTargetXToReach(
  root: Point2,
  requestedTip: Point2,
  upperLength: number,
  lowerLength: number,
  reachMargin = 0.004,
): Point2 {
  const maximumReach = Math.max(EPSILON,
    upperLength + lowerLength - Math.max(0, reachMargin));
  const verticalDistance = requestedTip.y - root.y;
  const horizontalReach = Math.sqrt(Math.max(0,
    maximumReach * maximumReach - verticalDistance * verticalDistance));
  return {
    x: Math.max(root.x - horizontalReach,
      Math.min(root.x + horizontalReach, requestedTip.x)),
    y: requestedTip.y,
  };
}

/** Analytic planar two-bone IK for limbs whose zero angle points downward.
 * Positive world angles point toward +x; a negative lower-relative angle is
 * the anatomical knee bend used by the Ironbound rig. Unreachable targets are
 * projected onto the chain's annulus instead of stretching either rigid body. */
export function solveTwoBoneIK(
  root: Point2,
  requestedTip: Point2,
  upperLength: number,
  lowerLength: number,
  bendDirection: -1 | 1 = -1,
  reachMargin = 0.004,
): TwoBoneIKResult {
  if (!(upperLength > 0) || !(lowerLength > 0)) {
    throw new Error('Two-bone IK lengths must be positive');
  }

  const dx = requestedTip.x - root.x;
  const dy = requestedTip.y - root.y;
  const requestedDistance = Math.hypot(dx, dy);
  const minimumReach = Math.min(
    upperLength + lowerLength - EPSILON,
    Math.abs(upperLength - lowerLength) + Math.max(0, reachMargin),
  );
  const maximumReach = Math.max(
    minimumReach,
    upperLength + lowerLength - Math.max(0, reachMargin),
  );
  const solvedDistance = Math.max(minimumReach, Math.min(maximumReach, requestedDistance));
  const directionX = requestedDistance > EPSILON ? dx / requestedDistance : 0;
  const directionY = requestedDistance > EPSILON ? dy / requestedDistance : -1;
  const projectedTip = {
    x: root.x + directionX * solvedDistance,
    y: root.y + directionY * solvedDistance,
  };

  const downX = projectedTip.x - root.x;
  const downY = root.y - projectedTip.y;
  const cosine = Math.max(-1, Math.min(1,
    (solvedDistance * solvedDistance - upperLength * upperLength - lowerLength * lowerLength) /
    (2 * upperLength * lowerLength),
  ));
  const triangleAngle = Math.acos(cosine);
  const lowerRelativeAngle = bendDirection * triangleAngle;
  // Standard link-space angle is measured from +x in a y-down plane. Convert
  // it to the rig's zero-down, positive-toward-+x convention afterwards.
  const standardLowerDelta = -lowerRelativeAngle;
  const standardUpper = Math.atan2(downY, downX) - Math.atan2(
    lowerLength * Math.sin(standardLowerDelta),
    upperLength + lowerLength * Math.cos(standardLowerDelta),
  );
  const upperWorldAngle = Math.PI / 2 - standardUpper;
  const lowerWorldAngle = upperWorldAngle + lowerRelativeAngle;

  return {
    upperWorldAngle,
    lowerRelativeAngle,
    lowerWorldAngle,
    projectedTip,
    requestedDistance,
    solvedDistance,
    clamped: Math.abs(solvedDistance - requestedDistance) > 1e-7,
  };
}
