// Shared types for Ironbound: Twin Grip.
import type { Vec2 } from 'planck';

export type Facing = 1 | -1;
export type PixelStyle = 'detailed' | 'coarse';
export type EnemyAppearanceId = 'light-male' | 'dark-male' | 'light-female' | 'dark-female';

export type PartName =
  | 'pelvis' | 'torso' | 'head'
  | 'upperArmL' | 'forearmL' | 'handL'
  | 'upperArmR' | 'forearmR' | 'handR'
  | 'thighL' | 'shinL' | 'footL'
  | 'thighR' | 'shinR' | 'footR';

export type DamageType = 'cut' | 'pierce' | 'blunt';

/** Unified control packet consumed by a Fighter every physics step.
 *  Produced by touch/keyboard input, by the AI brain, or by test scripts. */
export interface FighterInput {
  /** Desired world-space target for each hand, or null to return to guard. */
  left: Vec2 | null;
  right: Vec2 | null;
  /** Event-sampled mouse gesture. Travel is unwrapped so fast complete turns
   * cannot disappear between two physics frames. */
  rightGesture?: {
    id: number;
    startAngle: number;
    travel: number;
    active: boolean;
  } | null;
  /** -1 = step left, 0 = none, 1 = step right (edge-triggered). */
  step: -1 | 0 | 1;
  /** Continuous world-space walking demand. Q/E and AI locomotion hold this. */
  move?: number;
  /** Held defensive brace input; consumed by shield mechanics in 12d. */
  brace?: boolean;
}

export const IDLE_INPUT: FighterInput = { left: null, right: null, step: 0, move: 0, brace: false };

export interface DamageEvent {
  attackerId: number;
  defenderId: number;
  part: PartName;
  type: DamageType;
  energy: number;
  damage: number;
  x: number;
  y: number;
  /** Normalized weapon velocity at contact, used by directional hit feedback. */
  dirX?: number;
  dirY?: number;
  relativeSpeed?: number;
  /** Solver impulse reconstructed as an equivalent normal impact speed. */
  impactSpeed?: number;
  /** Contact normal oriented from the weapon into the struck body. */
  normalX?: number;
  normalY?: number;
  /** Directional contact semantics used to distinguish a slice from a stab. */
  axialAlignment?: number;
  transverseAlignment?: number;
  contactQuality?: number;
  /** Weapon identity lets the post-step penetration system bind the exact blade. */
  weaponInstanceId?: string;
}

export interface BlockEvent {
  attackerId: number;
  defenderId: number;
  type: DamageType;
  energy: number;
  damageFactor: number;
  x: number;
  y: number;
}

export interface FightResult {
  winnerId: number;      // 0 = player, 1 = opponent
  loserId: number;
  reason: 'death' | 'ko';
  durationSec: number;
  playerVitalityPct: number;
}

export interface BodyProportions {
  height: number;   // multiplier 0.9..1.1
  mass: number;     // multiplier 0.85..1.2
  shoulder: number; // width multiplier
  torso: number;
  hip: number;
  legs: number;
  arms: number;
}

export const DEFAULT_PROPORTIONS: BodyProportions = {
  height: 1, mass: 1, shoulder: 1, torso: 1, hip: 1, legs: 1, arms: 1,
};
