// Renderer: Canvas2D at a 960x540 logical surface with retina backing, bitmap
// art on top of the physics rig (greybox polygons as fallback). Camera tracks
// fighter midpoint with separation-based zoom.
import { Body, Fixture, Vec2, World } from 'planck';
import { CFG } from '../config';
import type { PixelStyle } from '../types';
import { Fighter } from '../physics/Fighter';
import { smootherstep } from '../physics/Gait';
import { WeaponInstance } from '../physics/Weapons';
import { ArenaArt, Assets, Atlas, arenaArtId } from './Assets';
import { DamageType, PartName } from '../types';

type EffectKind = 'hit' | 'cut' | 'pierce' | 'blunt' | 'clash' | 'dust';

// one burst particle in world space
interface Particle {
  x: number; y: number; vx: number; vy: number;
  ttl: number; maxTtl: number;
  size: number; grav: number; color: string;
}

const EFFECT_DEFS: Record<EffectKind, {
  n: number; speed: [number, number]; size: [number, number];
  grav: number; ttl: [number, number]; colors: string[];
}> = {
  hit:    { n: 8, speed: [0.7, 2.6], size: [2.0, 4.0], grav: -6,   ttl: [0.28, 0.56], colors: ['#a83a2a', '#7a2430', '#c4552f'] },
  cut:    { n: 13, speed: [1.0, 3.8], size: [2.0, 4.5], grav: -7, ttl: [0.38, 0.78], colors: ['#b03024', '#8e2f22', '#5e1820'] },
  pierce: { n: 9, speed: [1.2, 4.0], size: [1.5, 3.6], grav: -6, ttl: [0.28, 0.62], colors: ['#d8e2e8', '#8e2f22', '#5e1820'] },
  blunt:  { n: 6, speed: [0.4, 1.6], size: [2.0, 4.0], grav: -1.5, ttl: [0.40, 0.80], colors: ['#8a8177', '#6e6257', '#a89a86'] },
  clash:  { n: 7, speed: [1.5, 4.5], size: [1.0, 2.0], grav: -3,   ttl: [0.15, 0.40], colors: ['#ffd97a', '#fff3c4', '#e8b03a'] },
  dust:   { n: 6, speed: [0.3, 1.2], size: [2.0, 4.5], grav: -0.6, ttl: [0.50, 1.00], colors: ['#8a8177', '#7a7169', '#9a9186'] },
};

// floating damage number in world space
interface Floater { x: number; y: number; text: string; ttl: number; kind: string }
interface WoundMark { fighterId: number; part: string; severity: number }
interface BloodPool { x: number; size: number; alpha: number }
interface PierceStreak { x: number; y: number; dirX: number; dirY: number; length: number; ttl: number; maxTtl: number }

export interface TraumaProfile {
  throughParticles: number;
  tissueChunks: number;
  eyeFragments: number;
  streakLength: number;
}

const EXTREMITIES = /^(upperArm|forearm|hand|thigh|shin|foot)/;

export function traumaProfile(type: DamageType, part: PartName, damage: number): TraumaProfile {
  const d = Math.max(0, Number.isFinite(damage) ? damage : 0);
  const penetrating = type === 'pierce';
  const edged = penetrating || type === 'cut';
  return {
    throughParticles: penetrating ? Math.min(18, 6 + Math.floor(d * 0.7)) : 0,
    tissueChunks: edged && EXTREMITIES.test(part) && d >= 5 ? Math.min(7, 1 + Math.floor((d - 5) / 2)) : 0,
    eyeFragments: penetrating && part === 'head' && d >= 7 ? 2 : 0,
    streakLength: penetrating ? Math.min(0.48, 0.16 + d * 0.018) : 0,
  };
}

const FLOATER_TTL = 0.9;
// scratches below this aren't worth a number — they read as confident "1" lies
const FLOATER_MIN_DAMAGE = 2;
const FLOATER_COLORS: Record<string, string> = {
  blunt: '#b99a4a',   // gold
  cut: '#c04a35',     // blood
  pierce: '#e8e0cf',  // bone
};

const PALETTES = [
  { cloth: '#5d6b3f', trim: '#39422a' }, // bramble: moss
  { cloth: '#b4552d', trim: '#73341c' }, // copper: rust
  { cloth: '#4a5a66', trim: '#2e3941' }, // rime: steel blue-grey
  { cloth: '#6e3a56', trim: '#43213a' }, // ember: aubergine
];

// per-fighter-tint hue shift applied to bitmap sprites (degrees)
const TINT_HUE = [0, 22, 185, -38];

export function cameraWorldWidth(separation: number): number {
  const target = CFG.camera.baseWorldWidth + (separation - 2) * CFG.camera.zoomPerSeparation;
  return Math.max(CFG.camera.worldWidthMin, Math.min(CFG.camera.worldWidthMax, target));
}

export interface RenderBodyPose {
  x: number;
  y: number;
  angle: number;
}

/** Blend the two fixed-step transforms used by the visual frame. Angles take
 * the shortest arc so a body crossing +/-pi does not spin almost a full turn
 * on screen even though the physical rotation was only a few degrees. */
export function interpolateRenderPose(
  previous: RenderBodyPose, current: RenderBodyPose, alpha: number,
): RenderBodyPose {
  const t = Math.max(0, Math.min(1, Number.isFinite(alpha) ? alpha : 1));
  let angleDelta = (current.angle - previous.angle) % (Math.PI * 2);
  if (angleDelta > Math.PI) angleDelta -= Math.PI * 2;
  if (angleDelta < -Math.PI) angleDelta += Math.PI * 2;
  return {
    x: previous.x + (current.x - previous.x) * t,
    y: previous.y + (current.y - previous.y) * t,
    angle: previous.angle + angleDelta * t,
  };
}

export function selectsUnarmoredAtlas(material: string, forceArmorPreview = false): boolean {
  return material === 'flesh' && !forceArmorPreview;
}

export interface FootContactProfile {
  alpha: number;
  widthM: number;
  heightM: number;
}

/** Translate the physical shoe pose into a restrained ground-contact cue.
 * The shadow is not an animation clock: it is fully determined by the rigid
 * foot's measured height and angle, so an airborne shoe cannot fake a planted
 * step. */
export function footContactProfile(centerY: number, angle: number): FootContactProfile {
  const safeY = Number.isFinite(centerY) ? centerY : 1;
  const safeAngle = Number.isFinite(angle) ? angle : 0;
  const groundWeight = Math.max(0, Math.min(1, (0.16 - safeY) / 0.115));
  const soleProjection = 0.72 + 0.28 * Math.abs(Math.cos(safeAngle));
  return {
    alpha: 0.52 * groundWeight * groundWeight,
    widthM: 0.22 * soleProjection * (0.72 + 0.28 * groundWeight),
    heightM: 0.021 * (0.70 + 0.30 * groundWeight),
  };
}

const LEG_PARTS = (side: 'L' | 'R'): string[] => [
  `foot${side}`, `shin${side}`, `thigh${side}`,
];
const ARM_PARTS = (side: 'L' | 'R'): string[] => [
  `upperArm${side}`, `forearm${side}`, `hand${side}`,
];

/** Side-view depth order for a segmented fighter. The previously swinging
 * chain remains in front through early swing, then the new swing chain crosses
 * in front near mid-step when both projected limbs overlap. Switching at a
 * foot swap made six independently drawn limb sprites pop across the torso. */
export function fighterLayerOrder(
  facing: 1 | -1, gaitPhase: string, swingSide: 'L' | 'R', gaitProgress = 1,
): string[] {
  const idleFront: 'L' | 'R' = facing === 1 ? 'R' : 'L';
  const supportSide = swingSide === 'L' ? 'R' : 'L';
  const front = gaitPhase === 'idle' ? idleFront
    : gaitProgress < 0.5 ? supportSide : swingSide;
  const back = front === 'L' ? 'R' : 'L';
  return [
    ...LEG_PARTS(back),
    'pelvis', 'torso', 'head',
    ...LEG_PARTS(front),
    // Both complete arm chains remain in front of the torso. The far arm still
    // receives the depth-brightness cue, but a shield can no longer erase the
    // upper arm behind the body while the shield itself renders on top.
    ...ARM_PARTS(back),
    ...ARM_PARTS(front),
  ];
}

/** Depth cue for the two projected body sides. Both sides meet at the same
 * brightness during the mid-step crossover, preventing a second visual pop
 * when their draw order changes. */
export function fighterLimbDepthBrightness(
  facing: 1 | -1, gaitPhase: string, swingSide: 'L' | 'R', gaitProgress: number,
  side: 'L' | 'R',
): number {
  const near = 1;
  const far = 0.82;
  if (gaitPhase === 'idle') {
    const idleFront: 'L' | 'R' = facing === 1 ? 'R' : 'L';
    return side === idleFront ? near : far;
  }
  const cross = smootherstep((gaitProgress - 0.35) / 0.30);
  const swingBrightness = far + (near - far) * cross;
  const supportBrightness = near - (near - far) * cross;
  return side === swingSide ? swingBrightness : supportBrightness;
}

interface PartStyle {
  rect: string;          // name in fighter atlas
  overscan: number;      // visual size multiplier vs physics box
  overscanX?: number;    // optional separate horizontal multiplier (for skinny limbs)
  rot: number;           // base rotation offset (radians, pre-mirror)
  dx?: number;           // source-art anchor correction as fraction of rendered width
  dy: number;            // nudge along local -y (canvas down) as fraction of sprite height
}

// Fit each source plate closely to its physical segment. Earlier 2.4-3.5x limb
// overscan made both arms and both legs overlap into uncanny duplicate torsos
// and straight armor columns, hiding the actual hip-knee-ankle articulation.
const PART_STYLE: Record<string, PartStyle> = {
  pelvis:   { rect: 'pelvis',   overscan: 1.12, overscanX: 1.30, rot: 0, dy: 0.02 },
  torso:    { rect: 'torso',    overscan: 1.10, overscanX: 1.15, rot: 0, dy: 0.0 },
  head:     { rect: 'head',     overscan: 1.14, rot: 0, dx: 0.085, dy: 0.10 },
  upperArm: { rect: 'upperArm', overscan: 1.28, overscanX: 1.55, rot: 0, dy: 0.0 },
  forearm:  { rect: 'forearm',  overscan: 1.28, overscanX: 1.65, rot: 0, dy: 0.0 },
  hand:     { rect: 'hand',     overscan: 1.12, rot: 0, dy: 0.0 },
  thigh:    { rect: 'thigh',    overscan: 1.26, overscanX: 1.65, rot: 0, dy: 0.0 },
  shin:     { rect: 'shin',     overscan: 1.26, overscanX: 1.45, rot: 0, dy: 0.0 },
  foot:     { rect: 'foot',     overscan: 1.26, overscanX: 0.90, rot: 0, dx: 0.16, dy: 0.02 },
};

export interface PartSpriteMetrics {
  widthM: number;
  heightM: number;
  centerOffsetXM: number;
  centerOffsetM: number;
}

/** Size a segmented body plate from its rigid fixture, not from the source
 * crop aspect ratio. The atlas deliberately uses chunky, independently drawn
 * pieces whose source aspect ratios are not anatomical measurements. Letting
 * a widened crop dictate its own height made arms and shins span multiple
 * physical joints even though their body transforms were correct. */
export function partSpriteMetrics(styleKey: string, halfWidthM: number, halfHeightM: number): PartSpriteMetrics | null {
  const style = PART_STYLE[styleKey];
  if (!style) return null;
  const widthM = 2 * halfWidthM * (style.overscanX ?? style.overscan);
  const heightM = 2 * halfHeightM * style.overscan;
  return {
    widthM,
    heightM,
    centerOffsetXM: widthM * (style.dx ?? 0),
    centerOffsetM: heightM * style.dy,
  };
}

export class Renderer {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  camX = 0;
  zoom = 1;         // multiplies pxPerMeter
  shake = 0;
  debug = false;
  particles: Particle[] = [];
  floaters: Floater[] = [];
  partFlashes = new Map<string, number>(); // "fighterId:part" -> ttl of the impact flash
  wounds: WoundMark[] = [];
  bloodPools: BloodPool[] = [];
  pierceStreaks: PierceStreak[] = [];
  vignette = 0;
  reducedFlash = false; // accessibility: soften the struck-part flash
  pixelStyle: PixelStyle = 'detailed';
  assets: Assets | null = null;
  private ppm = CFG.physics.pxPerMeter;
  // logical render resolution; backing store = logical * dpr (set by fitStage),
  // so all layout math below stays in logical units and dpr is applied as a
  // single base transform at the start of each render()
  private readonly viewW = 960;
  private readonly viewH = 540;
  realm = 'bramble'; // active arena art id
  private readonly forceArmorPreview: boolean;
  private previousBodyPoses = new Map<Body, RenderBodyPose>();
  private physicsInterpolation = 1;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('no 2d context');
    this.ctx = ctx;
    this.forceArmorPreview = typeof location !== 'undefined' &&
      new URLSearchParams(location.search).get('armor') === '1';
    ctx.imageSmoothingEnabled = false;
  }

  /** Preserve the state immediately before a fixed 60 Hz game step. The
   * renderer later blends this snapshot toward the resolved state using the
   * accumulator remainder, while physics and hit detection stay untouched. */
  capturePhysicsState(world: World): void {
    this.previousBodyPoses.clear();
    for (let body = world.getBodyList(); body; body = body.getNext()) {
      const p = body.getPosition();
      this.previousBodyPoses.set(body, { x: p.x, y: p.y, angle: body.getAngle() });
    }
  }

  setPhysicsInterpolation(alpha: number): void {
    this.physicsInterpolation = Math.max(0, Math.min(1, Number.isFinite(alpha) ? alpha : 1));
  }

  interpolationDiagnostics(body: Body): {
    alpha: number; snapshotBodies: number; physicsX: number; renderX: number;
  } {
    return {
      alpha: this.physicsInterpolation,
      snapshotBodies: this.previousBodyPoses.size,
      physicsX: body.getPosition().x,
      renderX: this.bodyPose(body).x,
    };
  }

  private bodyPose(body: Body): RenderBodyPose {
    const p = body.getPosition();
    const current = { x: p.x, y: p.y, angle: body.getAngle() };
    const previous = this.previousBodyPoses.get(body);
    return previous
      ? interpolateRenderPose(previous, current, this.physicsInterpolation)
      : current;
  }

  private localPoint(body: Body, local: Vec2): Vec2 {
    const pose = this.bodyPose(body);
    const cos = Math.cos(pose.angle), sin = Math.sin(pose.angle);
    return Vec2(
      pose.x + cos * local.x - sin * local.y,
      pose.y + sin * local.x + cos * local.y,
    );
  }

  addEffect(x: number, y: number, kind: EffectKind): void {
    const def = EFFECT_DEFS[kind];
    for (let i = 0; i < def.n; i++) {
      const ang = Math.random() * Math.PI; // upper half-cone
      const spd = def.speed[0] + Math.random() * (def.speed[1] - def.speed[0]);
      const ttl = def.ttl[0] + Math.random() * (def.ttl[1] - def.ttl[0]);
      this.particles.push({
        x, y,
        vx: Math.cos(ang) * spd,
        vy: Math.sin(ang) * spd,
        ttl, maxTtl: ttl,
        size: def.size[0] + Math.random() * (def.size[1] - def.size[0]),
        grav: def.grav,
        color: def.colors[(Math.random() * def.colors.length) | 0],
      });
    }
    if (this.particles.length > 220) this.particles.splice(0, this.particles.length - 220);
  }

  /** brief brightness flash on the struck body part (sprite path only) */
  flashPart(fighterId: number, part: string, ttl = 0.14): void {
    this.partFlashes.set(`${fighterId}:${part}`, ttl);
  }

  addDamageNumber(x: number, y: number, damage: number, kind: string): void {
    if (damage < FLOATER_MIN_DAMAGE) return;
    if (this.floaters.length > 20) this.floaters.shift();
    this.floaters.push({ x, y: y + 0.12, text: `${Math.round(damage)}`, ttl: FLOATER_TTL, kind });
  }

  addBloodSpray(x: number, y: number, direction: number, severity: number): void {
    const count = Math.max(8, Math.min(26, Math.round(8 + severity * 0.65)));
    for (let i = 0; i < count; i++) {
      const speed = 0.9 + Math.random() * Math.min(4.6, 1.5 + severity * 0.10);
      const ttl = 0.42 + Math.random() * 0.72;
      this.particles.push({
        x, y,
        vx: direction * speed * (0.65 + Math.random() * 0.55),
        vy: 0.20 + Math.random() * 2.4,
        ttl, maxTtl: ttl,
        size: 2.0 + Math.random() * 3.6,
        grav: -7.5,
        color: Math.random() < 0.55 ? '#8e2f22' : '#5e1820',
      });
    }
    if (this.particles.length > 220) this.particles.splice(0, this.particles.length - 220);
    const existing = this.bloodPools.find(pool => Math.abs(pool.x - x) < 0.22);
    if (existing) {
      existing.size = Math.min(0.38, existing.size + severity * 0.003);
      existing.alpha = Math.min(0.75, existing.alpha + 0.08);
    } else if (this.bloodPools.length < 12) {
      this.bloodPools.push({ x, size: Math.min(0.25, 0.06 + severity * 0.006), alpha: 0.58 });
    }
  }

  addWound(fighterId: number, part: string, severity: number): void {
    const existing = this.wounds.find(wound => wound.fighterId === fighterId && wound.part === part);
    if (existing) existing.severity = Math.max(existing.severity, severity);
    else this.wounds.push({ fighterId, part, severity });
    if (this.wounds.length > 24) this.wounds.shift();
  }

  addTraumaBurst(
    x: number, y: number, dirX: number, dirY: number,
    type: DamageType, part: PartName, damage: number,
  ): void {
    const profile = traumaProfile(type, part, damage);
    const magnitude = Math.hypot(dirX, dirY);
    const nx = magnitude > 0.001 ? dirX / magnitude : 1;
    const ny = magnitude > 0.001 ? dirY / magnitude : 0;
    if (profile.streakLength > 0) {
      this.pierceStreaks.push({
        x, y, dirX: nx, dirY: ny, length: profile.streakLength,
        ttl: 0.13, maxTtl: 0.13,
      });
      if (this.pierceStreaks.length > 10) this.pierceStreaks.shift();
    }
    for (let i = 0; i < profile.throughParticles; i++) {
      const side = (Math.random() - 0.5) * 0.55;
      const speed = 1.4 + Math.random() * 3.8;
      const ttl = 0.32 + Math.random() * 0.46;
      this.particles.push({
        x: x + nx * 0.035, y: y + ny * 0.035,
        vx: nx * speed - ny * side,
        vy: ny * speed + nx * side + 0.25,
        ttl, maxTtl: ttl, size: 1.5 + Math.random() * 2.8, grav: -7,
        color: Math.random() < 0.2 ? '#d8cbb8' : Math.random() < 0.55 ? '#8e2f22' : '#5e1820',
      });
    }
    for (let i = 0; i < profile.tissueChunks; i++) {
      const ttl = 0.55 + Math.random() * 0.55;
      this.particles.push({
        x, y,
        vx: nx * (0.8 + Math.random() * 2.2) + (Math.random() - 0.5) * 1.2,
        vy: 0.8 + Math.random() * 2.4,
        ttl, maxTtl: ttl, size: 4 + Math.random() * 3.5, grav: -8.5,
        color: Math.random() < 0.5 ? '#6f1c20' : '#9b3025',
      });
    }
    for (let i = 0; i < profile.eyeFragments; i++) {
      const ttl = 0.65 + i * 0.08;
      this.particles.push({
        x, y: y + 0.015,
        vx: nx * (1.2 + i * 0.45) + (i ? 0.22 : -0.22),
        vy: 1.35 + i * 0.3,
        ttl, maxTtl: ttl, size: 3.2, grav: -7.8,
        color: i === 0 ? '#ddd1b9' : '#22161a',
      });
    }
    if (this.particles.length > 260) this.particles.splice(0, this.particles.length - 260);
  }

  pulseVignette(strength: number): void {
    const cap = this.reducedFlash ? 0.22 : 0.48;
    this.vignette = Math.min(cap, Math.max(this.vignette, strength));
  }

  /** world->screen without the camera-shake jitter: floaters are text and must stay readable */
  private sxCalm(wx: number): number { return (wx - this.camX) * this.ppm * this.zoom + this.viewW / 2; }
  private syCalm(wy: number): number { return this.viewH * 0.78 - wy * this.ppm * this.zoom; }

  /** Browser client coordinates -> world coordinates using the calm camera. */
  screenToWorld(clientX: number, clientY: number): Vec2 {
    const rect = this.canvas.getBoundingClientRect();
    const sx = (clientX - rect.left) * (this.viewW / Math.max(1, rect.width));
    const sy = (clientY - rect.top) * (this.viewH / Math.max(1, rect.height));
    return Vec2(
      this.camX + (sx - this.viewW / 2) / (this.ppm * this.zoom),
      (this.viewH * 0.78 - sy) / (this.ppm * this.zoom),
    );
  }

  kick(strength: number): void {
    this.shake = Math.min(CFG.camera.shakeCap, this.shake + strength * 0.02);
  }

  private sx(wx: number): number {
    return (wx - this.camX) * this.ppm * this.zoom + this.viewW / 2 +
      (this.shake > 0 ? (Math.random() - 0.5) * this.shake * this.ppm : 0);
  }
  private sy(wy: number): number {
    return this.viewH * 0.78 - wy * this.ppm * this.zoom +
      (this.shake > 0 ? (Math.random() - 0.5) * this.shake * this.ppm : 0);
  }

  updateCamera(a: Fighter, b: Fighter, dt: number): void {
    const ax = this.bodyPose(a.pelvis()).x, bx = this.bodyPose(b.pelvis()).x;
    const mid = (ax + bx) / 2;
    const sep = Math.abs(ax - bx);
    const targetX = Math.max(-CFG.physics.arenaHalfWidth + 1.4, Math.min(CFG.physics.arenaHalfWidth - 1.4, mid));
    this.camX += (targetX - this.camX) * CFG.camera.lerp;
    const worldW = cameraWorldWidth(sep);
    const targetZoom = this.viewW / (worldW * this.ppm);
    this.zoom += (targetZoom - this.zoom) * CFG.camera.lerp;
    this.shake = Math.max(0, this.shake - dt * 0.5);
  }

  private poly(pts: [number, number][], fill: string, stroke = '#14101a'): void {
    const c = this.ctx;
    c.beginPath();
    c.moveTo(this.sx(pts[0][0]), this.sy(pts[0][1]));
    for (let i = 1; i < pts.length; i++) c.lineTo(this.sx(pts[i][0]), this.sy(pts[i][1]));
    c.closePath();
    c.fillStyle = fill;
    c.fill();
    c.strokeStyle = stroke;
    c.lineWidth = Math.max(1, this.zoom);
    c.stroke();
  }

  private fighterAtlasFor(f: Fighter): Atlas | null {
    if (!this.assets) return null;
    if (!selectsUnarmoredAtlas(f.armorMaterial, this.forceArmorPreview)) {
      return this.assets.armorFighters[f.armorMaterial] ?? this.assets.fighter;
    }
    if (f.visualVariant) {
      const variant = this.assets.enemyFighters[f.visualVariant];
      if (variant) return variant;
    }
    return this.pixelStyle === 'coarse'
      ? this.assets.unarmoredFighterCoarse ?? this.assets.unarmoredFighter
      : this.assets.unarmoredFighter;
  }

  private drawSpritePart(f: Fighter, name: string, depthBrightness = 1): boolean {
    const atlas = this.fighterAtlasFor(f);
    const style = PART_STYLE[this.styleKey(name)];
    if (!atlas || !style) return false;
    const rect = atlas.rects[style.rect];
    if (!rect) return false;
    const pd = f.part(name as any);
    const body = pd.body;
    const p = this.bodyPose(body);
    const ang = p.angle;
    const c = this.ctx;

    // physics box dims (meters) from first fixture AABB in local space
    let hw = 0.1, hh = 0.1;
    const fx = body.getFixtureList();
    if (fx) {
      const shape: any = fx.getShape();
      if (shape.getType() === 'circle') { hw = hh = shape.m_radius; }
      else {
        const vs: Vec2[] = shape.m_vertices;
        let mxx = 0, mxy = 0;
        for (const v of vs) { mxx = Math.max(mxx, Math.abs(v.x)); mxy = Math.max(mxy, Math.abs(v.y)); }
        hw = mxx; hh = mxy;
      }
    }

    const ppz = this.ppm * this.zoom;
    // Long-axis length follows the physical segment; overscanX can still make
    // a chunky limb wider without accidentally making it span two joints.
    const metrics = partSpriteMetrics(this.styleKey(name), hw, hh)!;
    const dw = metrics.widthM * ppz;
    const dh = metrics.heightM * ppz;

    c.save();
    c.translate(this.sx(p.x), this.sy(p.y));
    c.rotate(-ang + style.rot);
    if (f.facing === -1) c.scale(-1, 1);
    // Keep hard texel boundaries at gameplay size. Bilinear downsampling made
    // the articulated silhouette look smeared and hid the contact between feet
    // and the ground; nearest-neighbour gives the requested chunky pixel read.
    c.imageSmoothingEnabled = false;
    // silhouette separation: shadow halo follows the sprite's actual alpha
    // shape (not a wireframe rect), so rotated/limb sprites get clean contrast
    // without producing "framing shard" artifacts around each part.
    c.shadowColor = 'rgba(8,6,10,0.7)';
    c.shadowBlur = Math.max(2, Math.min(dw, dh) * 0.08);
    c.shadowOffsetX = 0;
    c.shadowOffsetY = 0;
    // tint by realm palette; desaturate hurt parts; gentle brightness lift on
    // armor so mid-tones separate from dark arena backgrounds
    const r = pd.tissue / pd.tissueMax;
    const unarmored = atlas === this.assets?.unarmoredFighter ||
      atlas === this.assets?.unarmoredFighterCoarse ||
      Object.values(this.assets?.enemyFighters ?? {}).includes(atlas);
    const hue = unarmored ? 0 : TINT_HUE[f.tint % TINT_HUE.length];
    const flash = (this.partFlashes.get(`${f.id}:${name}`) ?? 0) > 0;
    const hurt = flash ? (this.reducedFlash ? ' brightness(1.3)' : ' brightness(2.1) saturate(0.35)')
      : r < 0.4 ? ' brightness(0.72) saturate(0.55)' : ' brightness(1.18)';
    const depth = Math.abs(depthBrightness - 1) > 0.001
      ? ` brightness(${depthBrightness.toFixed(3)})`
      : '';
    try { (c as any).filter = `hue-rotate(${hue}deg)${hurt}${depth}`; } catch { /* older canvas */ }
    c.drawImage(atlas.img, rect.x, rect.y, rect.w, rect.h,
      -dw / 2 + dw * (style.dx ?? 0), -dh / 2 + dh * style.dy, dw, dh);
    const wound = this.wounds.find(mark => mark.fighterId === f.id && mark.part === name);
    if (wound) {
      c.globalAlpha = Math.min(0.85, 0.35 + wound.severity * 0.02);
      c.strokeStyle = '#5e1820';
      c.lineWidth = Math.max(1.5, Math.min(dw, dh) * 0.08);
      c.beginPath();
      c.moveTo(-dw * 0.22, -dh * 0.12);
      c.lineTo(dw * 0.20, dh * 0.16);
      c.stroke();
      c.globalAlpha = 1;
    }
    try { (c as any).filter = 'none'; } catch { /* ignore */ }
    c.restore();
    return true;
  }

  private styleKey(name: string): string {
    // strip L/R suffix: thighL -> thigh
    return name.replace(/[LR]$/, '');
  }

  private drawFootContactShadows(f: Fighter): void {
    const c = this.ctx;
    const ppz = this.ppm * this.zoom;
    for (const side of ['L', 'R'] as const) {
      const foot = f.part(side === 'L' ? 'footL' : 'footR').body;
      const p = this.bodyPose(foot);
      const profile = footContactProfile(p.y, p.angle);
      if (profile.alpha < 0.005) continue;
      const width = Math.max(2, Math.round(profile.widthM * ppz));
      const height = Math.max(2, Math.round(profile.heightM * ppz));
      const x = Math.round(this.sx(p.x) - width / 2);
      const y = Math.round(this.sy(0.008) - height / 2);
      c.fillStyle = `rgba(9, 7, 10, ${profile.alpha.toFixed(3)})`;
      c.fillRect(x, y, width, height);
      c.fillStyle = `rgba(9, 7, 10, ${(profile.alpha * 0.48).toFixed(3)})`;
      c.fillRect(x + Math.round(width * 0.14), y - 1, Math.round(width * 0.72), 1);
    }
  }

  private drawWeaponSprite(w: WeaponInstance): boolean {
    const atlas = this.assets?.weapons;
    if (!atlas) return false;
    const rect = atlas.rects[w.def.id];
    if (!rect) return false;
    const b = w.body;
    const p = this.bodyPose(b);
    const ang = p.angle;
    const c = this.ctx;
    const ppz = this.ppm * this.zoom;
    // sprite grip at left: pommel sits 0.09 m behind the grip point
    const pommel = 0.09;
    // The bitmap and contact geometry share one scale. Visible blade tips now
    // stop where the physical piercing fixture stops.
    const destW = (w.def.length + pommel) * ppz;
    const destH = destW * (rect.h / rect.w);
    c.save();
    c.translate(this.sx(p.x), this.sy(p.y));
    c.rotate(-ang);
    c.imageSmoothingEnabled = false;
    // silhouette shadow so the blade separates from dark backgrounds without
    // producing wireframe-rect artifacts at rotated angles
    c.shadowColor = 'rgba(8,6,10,0.85)';
    c.shadowBlur = 3;
    c.shadowOffsetX = 0;
    c.shadowOffsetY = 0;
    // brightness lift so metal reads against dark palettes
    try { (c as any).filter = 'brightness(1.3) contrast(1.1)'; } catch { /* older canvas */ }
    c.drawImage(atlas.img, rect.x, rect.y, rect.w, rect.h,
      -pommel * ppz, -destH / 2, destW, destH);
    try { (c as any).filter = 'none'; } catch { /* ignore */ }
    c.restore();
    return true;
  }

  private drawFlailSprites(w: WeaponInstance): boolean {
    const art = this.assets?.flail;
    if (!art || w.def.kind !== 'flail' || w.bodies.length < 3) return false;
    const c = this.ctx;
    const ppz = this.ppm * this.zoom;
    const drawBody = (img: HTMLImageElement, body: Body, widthM: number, heightM: number, offsetM = 0) => {
      const p = this.bodyPose(body);
      c.save();
      c.translate(this.sx(p.x), this.sy(p.y));
      c.rotate(-p.angle);
      c.imageSmoothingEnabled = false;
      c.shadowColor = 'rgba(8,6,10,0.82)';
      c.shadowBlur = 3;
      try { (c as any).filter = 'brightness(1.14) contrast(1.06)'; } catch { /* older canvas */ }
      c.drawImage(img, offsetM * ppz, -heightM * ppz / 2, widthM * ppz, heightM * ppz);
      try { (c as any).filter = 'none'; } catch { /* ignore */ }
      c.restore();
    };

    drawBody(art.handle, w.body, 0.26, 0.046, -0.040);
    for (const link of w.bodies.slice(1, -1)) drawBody(art.link, link, 0.076, 0.036, -0.038);
    drawBody(art.ball, w.tipBody, 0.15, 0.14, -0.075);
    return true;
  }

  private drawShieldSprite(f: Fighter): boolean {
    const img = this.assets?.shield;
    const shield = f.shield;
    if (!img || !shield) return false;
    const p = this.bodyPose(shield.body);
    const width = CFG.shield.width * this.ppm * this.zoom;
    const height = CFG.shield.height * this.ppm * this.zoom;
    const c = this.ctx;
    c.save();
    c.translate(this.sx(p.x), this.sy(p.y));
    c.rotate(-p.angle);
    if (f.facing === -1) c.scale(-1, 1);
    c.imageSmoothingEnabled = false;
    c.shadowColor = 'rgba(8,6,10,0.85)';
    c.shadowBlur = 3;
    try { (c as any).filter = 'brightness(1.08) contrast(1.08)'; } catch { /* older canvas */ }
    c.drawImage(img, -width / 2, -height / 2, width, height);
    try { (c as any).filter = 'none'; } catch { /* ignore */ }
    c.restore();
    return true;
  }

  private drawFixture(fx: Fixture, fill: string): void {
    const body = fx.getBody();
    const shape: any = fx.getShape();
    const type = shape.getType();
    const c = this.ctx;
    if (type === 'polygon') {
      const verts: [number, number][] = shape.m_vertices.map((v: Vec2) => {
        const w = this.localPoint(body, v);
        return [w.x, w.y];
      });
      this.poly(verts, fill);
    } else if (type === 'circle') {
      const p = this.localPoint(body, shape.m_p);
      c.beginPath();
      c.arc(this.sx(p.x), this.sy(p.y), shape.m_radius * this.ppm * this.zoom, 0, Math.PI * 2);
      c.fillStyle = fill;
      c.fill();
      c.strokeStyle = '#14101a';
      c.lineWidth = Math.max(1, this.zoom);
      c.stroke();
    }
  }

  private drawArenaArt(art: ArenaArt): void {
    const c = this.ctx, W = this.viewW, H = this.viewH;
    const groundY = this.sy(0); // canvas y of the physics ground plane
    const img = art.img;
    // Draw the arena as one coherent plate. The old renderer independently
    // scaled and panned sky at 0.15x and ground at 1.0x, so the horizon visibly
    // split and the two halves slid in different directions during camera
    // motion. One transform keeps every pixel on the same camera plane.
    const scale = Math.max(
      W / img.width,
      groundY / Math.max(1, art.horizon * img.height),
      (H - groundY) / Math.max(1, (1 - art.horizon) * img.height),
    );
    const drawnW = img.width * scale;
    const drawnH = img.height * scale;
    const slack = Math.max(0, drawnW - W);
    const unifiedParallax = 0.32;
    const cameraOffset = this.camX * this.ppm * this.zoom * unifiedParallax;
    const xOff = Math.round(Math.max(-slack, Math.min(0, -slack / 2 - cameraOffset)));
    const yOff = groundY - art.horizon * drawnH;
    c.imageSmoothingEnabled = false;
    try { (c as any).filter = 'contrast(1.08) saturate(1.04)'; } catch { /* older canvas */ }
    c.drawImage(img, xOff, yOff, drawnW, drawnH);
    try { (c as any).filter = 'none'; } catch { /* ignore */ }
    // contact shadow strip under the play line for grounding
    c.fillStyle = 'rgba(10,8,12,0.35)';
    c.fillRect(0, groundY + 2, W, 3);
  }

  private arenaArt(): ArenaArt | null {
    if (!this.assets) return null;
    const id = arenaArtId(this.realm);
    if (this.pixelStyle === 'coarse' && (id === 'bramble' || id === 'chunky')) {
      return this.assets.arenas.chunkyCoarse ?? this.assets.arenas[id] ?? null;
    }
    return this.assets.arenas[id] ?? null;
  }

  drawBackground(): void {
    const art = this.arenaArt();
    if (art) this.drawArenaArt(art);
    else this.drawProceduralBackground();
  }

  private drawProceduralBackground(): void {
    const c = this.ctx, W = this.viewW, H = this.viewH;
    // sky
    const g = c.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, '#2b2233');
    g.addColorStop(0.6, '#3d2f3a');
    g.addColorStop(1, '#241c26');
    c.fillStyle = g;
    c.fillRect(0, 0, W, H);
    // distant hills (parallax 0.3)
    c.fillStyle = '#33283c';
    const off = -this.camX * this.ppm * this.zoom * 0.3;
    for (let i = -2; i < 8; i++) {
      const x = off + i * 140;
      c.fillRect(x, H * 0.55, 120, H * 0.25);
    }
    // arena fence at back plane (parallax 0.8)
    c.fillStyle = '#1d1620';
    const off2 = -this.camX * this.ppm * this.zoom * 0.8;
    for (let i = -4; i < 12; i++) {
      c.fillRect(off2 + i * 46, H * 0.68, 5, H * 0.1);
    }
    c.fillRect(0, H * 0.7, W, 4);
    // ground
    c.fillStyle = '#3a3230';
    c.fillRect(0, this.sy(0), W, H - this.sy(0));
    c.fillStyle = '#332b29';
    c.fillRect(0, this.sy(0), W, 3);
    // arena side posts
    for (const wx of [-CFG.physics.arenaHalfWidth, CFG.physics.arenaHalfWidth]) {
      this.poly([[wx - 0.04, 0], [wx + 0.04, 0], [wx + 0.04, 1.6], [wx - 0.04, 1.6]], '#4a3b2e');
    }
  }

  private partColor(f: Fighter, name: string): string {
    const pal = PALETTES[f.tint % PALETTES.length];
    const p = f.part(name as any);
    const r = p.tissue / p.tissueMax;
    if (name.startsWith('foot')) return r < 0.4 ? '#4e2925' : '#5b3f2b';
    if (name === 'torso' || name === 'pelvis' || name.startsWith('thigh')) return r < 0.4 ? '#7a3030' : pal.cloth;
    return r < 0.4 ? '#7a5b52' : '#d8c9ae'; // skin
  }

  /** Small under-sprite pads close the visual seam at each real revolute
   * anchor. They sit behind the articulated plates, so joints remain readable
   * without inflating whole limbs into overlapping duplicate silhouettes. */
  private drawJointBridges(f: Fighter): void {
    const c = this.ctx;
    const ppz = this.ppm * this.zoom;
    const armorColor: Record<string, string> = {
      padded: '#67513b', mail: '#4c514b', plate: '#767b7f',
    };
    const pad = (point: Vec2, radiusM: number, fill: string): void => {
      const radius = Math.max(3, Math.round(radiusM * ppz));
      const x = Math.round(this.sx(point.x));
      const y = Math.round(this.sy(point.y));
      c.beginPath();
      c.arc(x, y, radius, 0, Math.PI * 2);
      c.fillStyle = fill;
      c.fill();
      c.strokeStyle = '#241820';
      c.lineWidth = 1.5;
      c.stroke();
    };
    for (const joint of f.joints) {
      if (joint.name === 'spine') continue;
      const lower = /^(hip|knee|ankle)/.test(joint.name);
      const radius = joint.name === 'neck' ? 0.042
        : joint.name.startsWith('hip') ? 0.040
        : joint.name.startsWith('shoulder') ? 0.036
        : joint.name.startsWith('knee') ? 0.034
        : joint.name.startsWith('ankle') ? 0.028 : 0.032;
      const color = armorColor[f.armorMaterial] ??
        (lower ? this.partColor(f, joint.attachedPart) : '#b97855');
      pad(joint.joint.getAnchorA(), radius, color);
    }
    for (const side of ['L', 'R'] as const) {
      if (side === 'L' && f.shield) continue;
      const hand = f.part(side === 'L' ? 'handL' : 'handR').body;
      pad(hand.getWorldPoint(Vec2(0, 0.05)), 0.032,
        armorColor[f.armorMaterial] ?? '#b97855');
    }
  }

  drawFighter(f: Fighter): void {
    // Keep the currently articulated swing chain visible. Fixed L/R depth
    // ordering hid every second step behind the torso and read as missing or
    // duplicated limbs even though all 15 physical bodies were present.
    const gait = f.gaitDiagnostics();
    const order = fighterLayerOrder(f.facing, gait.phase, gait.swing, gait.progress);
    this.drawFootContactShadows(f);
    const useSprites = !!this.fighterAtlasFor(f);
    if (useSprites) this.drawJointBridges(f);
    for (const name of order) {
      // The off-hand is physically inside the shield grip. Drawing its fist on
      // top of the heater shield made the attachment look detached and uncanny.
      if (name === 'handL' && f.shield) continue;
      const side = name.endsWith('L') ? 'L' : name.endsWith('R') ? 'R' : null;
      const depthBrightness = side
        ? fighterLimbDepthBrightness(f.facing, gait.phase, gait.swing, gait.progress, side)
        : 1;
      if (useSprites && this.drawSpritePart(f, name, depthBrightness)) continue;
      const body = f.part(name as any).body;
      for (let fx = body.getFixtureList(); fx; fx = fx.getNext()) {
        this.drawFixture(fx, this.partColor(f, name));
      }
    }
    // off-hand shield and weapon on top
    if (f.shield && !this.drawShieldSprite(f)) {
      for (let fx = f.shield.body.getFixtureList(); fx; fx = fx.getNext()) this.drawFixture(fx, '#544737');
    }
    if (f.weapon) {
      if (!this.drawFlailSprites(f.weapon) && !this.drawWeaponSprite(f.weapon)) {
        for (const wb of f.weapon.bodies) {
          for (let fx = wb.getFixtureList(); fx; fx = fx.getNext()) {
            const ud: any = fx.getUserData();
            const col = ud?.weaponPart === 'ball' ? '#7d8792'
              : ud?.weaponPart === 'chain' ? '#98a1a8'
              : ud?.weaponPart === 'handle' ? '#5b3f2b'
              : ud?.surface === 'blunt' ? '#6e6257' : '#9aa8b5';
            this.drawFixture(fx, col);
          }
        }
      }
    }
    if (this.debug) this.drawDebug(f);
  }

  private drawDebug(f: Fighter): void {
    const c = this.ctx;
    c.fillStyle = '#ff5';
    // hand targets from last input
    for (const side of ['left', 'right'] as const) {
      const t = f.lastInput[side];
      if (!t) continue;
      c.strokeStyle = side === 'left' ? '#4af' : '#fa4';
      c.beginPath();
      c.moveTo(this.sx(t.x) - 4, this.sy(t.y)); c.lineTo(this.sx(t.x) + 4, this.sy(t.y));
      c.moveTo(this.sx(t.x), this.sy(t.y) - 4); c.lineTo(this.sx(t.x), this.sy(t.y) + 4);
      c.stroke();
    }
    // joints
    c.fillStyle = '#f44';
    for (const j of f.joints) {
      const a = j.joint.getAnchorA();
      c.fillRect(this.sx(a.x) - 1, this.sy(a.y) - 1, 2, 2);
    }
    // center of mass marker (pelvis proxy) + text
    const p = this.bodyPose(f.pelvis());
    c.fillStyle = '#4f4';
    c.fillRect(this.sx(p.x) - 1, this.sy(p.y) - 6, 2, 2);
    c.font = '6px monospace';
    c.fillText(
      `S:${(f.stamina.fraction() * 100) | 0} tip:${f.lastTipSpeed.toFixed(1)} ${f.dead ? 'DEAD' : ''}`,
      this.sx(p.x) - 30, this.sy(p.y) - 16,
    );
  }

  private drawParticles(dt: number): void {
    const c = this.ctx;
    const zoomK = Math.max(0.75, this.zoom);
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.ttl -= dt;
      if (p.ttl <= 0) { this.particles.splice(i, 1); continue; }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += p.grav * dt;
      const k = p.ttl / p.maxTtl;
      const s = Math.max(1, p.size * (0.6 + 0.4 * k) * zoomK);
      c.globalAlpha = Math.min(1, k * 1.6);
      c.fillStyle = p.color;
      c.fillRect(this.sx(p.x) - s / 2, this.sy(p.y) - s / 2, s, s);
    }
    c.globalAlpha = 1;
  }

  private drawBloodPools(): void {
    const c = this.ctx;
    for (const pool of this.bloodPools) {
      c.globalAlpha = pool.alpha;
      c.fillStyle = '#4d1319';
      c.beginPath();
      c.ellipse(this.sx(pool.x), this.sy(0.012), pool.size * this.ppm * this.zoom, 2.5 * this.zoom, 0, 0, Math.PI * 2);
      c.fill();
    }
    c.globalAlpha = 1;
  }

  private drawPierceStreaks(dt: number): void {
    const c = this.ctx;
    for (let i = this.pierceStreaks.length - 1; i >= 0; i--) {
      const streak = this.pierceStreaks[i];
      streak.ttl -= dt;
      if (streak.ttl <= 0) { this.pierceStreaks.splice(i, 1); continue; }
      const alpha = streak.ttl / streak.maxTtl;
      const tailX = streak.x - streak.dirX * streak.length * 0.25;
      const tailY = streak.y - streak.dirY * streak.length * 0.25;
      const tipX = streak.x + streak.dirX * streak.length;
      const tipY = streak.y + streak.dirY * streak.length;
      c.globalAlpha = alpha;
      c.strokeStyle = '#5e1820';
      c.lineWidth = Math.max(3, 4 * this.zoom);
      c.beginPath(); c.moveTo(this.sx(tailX), this.sy(tailY)); c.lineTo(this.sx(tipX), this.sy(tipY)); c.stroke();
      c.strokeStyle = '#e6d7bd';
      c.lineWidth = Math.max(1, 1.4 * this.zoom);
      c.beginPath(); c.moveTo(this.sx(streak.x), this.sy(streak.y)); c.lineTo(this.sx(tipX), this.sy(tipY)); c.stroke();
    }
    c.globalAlpha = 1;
  }

  private drawVignette(dt: number): void {
    if (this.vignette <= 0.005) { this.vignette = 0; return; }
    const c = this.ctx;
    const g = c.createRadialGradient(this.viewW / 2, this.viewH / 2, this.viewH * 0.28, this.viewW / 2, this.viewH / 2, this.viewW * 0.68);
    g.addColorStop(0, 'rgba(80,0,10,0)');
    g.addColorStop(1, `rgba(95,0,12,${this.vignette.toFixed(3)})`);
    c.fillStyle = g;
    c.fillRect(0, 0, this.viewW, this.viewH);
    this.vignette = Math.max(0, this.vignette - dt * 2.6);
  }

  private drawFloaters(dt: number): void {
    const c = this.ctx;
    for (let i = this.floaters.length - 1; i >= 0; i--) {
      const f = this.floaters[i];
      f.ttl -= dt;
      if (f.ttl <= 0) { this.floaters.splice(i, 1); continue; }
      const k = f.ttl / FLOATER_TTL;
      const x = this.sxCalm(f.x);
      const y = this.syCalm(f.y + (1 - k) * 0.3); // rise 0.3 m while fading
      const px = Math.max(10, Math.round(12 * this.zoom));
      c.font = `bold ${px}px monospace`;
      c.textAlign = 'center';
      c.globalAlpha = Math.min(1, k * 2.5);
      c.lineWidth = 3;
      c.strokeStyle = '#0d0a10';
      c.strokeText(f.text, x, y);
      c.fillStyle = FLOATER_COLORS[f.kind] ?? '#e8e0cf';
      c.fillText(f.text, x, y);
      c.globalAlpha = 1;
    }
  }

  render(world: World, fighters: Fighter[], dt: number, realm = 'bramble'): void {
    this.realm = realm;
    // device-pixel-ratio base transform: backing store may be viewW*dpr wide;
    // everything below draws in logical units
    const c = this.ctx;
    const dpr = Math.max(1, this.canvas.width / this.viewW);
    c.setTransform(dpr, 0, 0, dpr, 0, 0);
    c.imageSmoothingEnabled = false;
    c.clearRect(0, 0, this.viewW, this.viewH);
    // decay part impact flashes
    for (const [key, t] of this.partFlashes) {
      if (t - dt <= 0) this.partFlashes.delete(key);
      else this.partFlashes.set(key, t - dt);
    }
    this.drawBackground();
    this.drawBloodPools();
    for (const f of fighters) this.drawFighter(f);
    this.drawPierceStreaks(dt);
    this.drawParticles(dt);
    this.drawFloaters(dt);
    this.drawVignette(dt);
  }
}
