// Campaign: original realm data + deterministic seeded encounter generation.
// 4 realms x 250 encounters = 1,000 records, generated from controlled templates.
// DOM-free; usable from Node tests.

export interface Realm {
  id: string;
  name: string;
  flavor: string;
  palette: number; // renderer tint variant
  weaponPool: string[];
  arenaCount: number;
}

export const REALMS: Realm[] = [
  {
    id: 'bramble', name: 'Bramble Coast',
    flavor: 'Timber forts, rain, mud and sea wind.',
    palette: 0, weaponPool: ['dagger', 'sword', 'mace'], arenaCount: 3,
  },
  {
    id: 'copper', name: 'Copper Throne',
    flavor: 'Stone cities, guild banners, late plate.',
    palette: 1, weaponPool: ['sword', 'mace'], arenaCount: 3,
  },
  {
    id: 'rime', name: 'Rime Principality',
    flavor: 'Snow yards and broad courtyards.',
    palette: 2, weaponPool: ['sword', 'mace'], arenaCount: 3,
  },
  {
    id: 'ember', name: 'Ember Isles',
    flavor: 'Volcanic hills and layered lacquer.',
    palette: 3, weaponPool: ['dagger', 'sword'], arenaCount: 3,
  },
];

export const ENCOUNTERS_PER_REALM = 250;

export interface Encounter {
  realm: string;
  index: number;          // 1..250
  label: string;
  aiTier: 'novice' | 'regular' | 'veteran' | 'boss';
  weaponId: string;
  isBoss: boolean;
  coinReward: number;
  modifier: string | null;
}

function mulberry32(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6D2B79F5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const NAME_A = ['Fen', 'Moor', 'Ald', 'Brann', 'Kell', 'Dorn', 'Hesk', 'Ravn', 'Torm', 'Gyth'];
const NAME_B = ['wick', 'bar', 'mund', 'rek', 'holm', 'gard', 'sen', 'fell', 'mar', 'dreg'];
const MODIFIERS = [null, null, null, 'slippery-ground', 'narrow-field', 'heavy-air', 'faulty-blades'];

function bossLabel(realm: string, milestone: number): string {
  const titles: Record<string, string> = {
    bramble: 'Briar Warden', copper: 'Guild Champion', rime: 'Frost Thegn', ember: 'Ash Blade',
  };
  return `${titles[realm] ?? 'Warlord'} of Mark ${milestone}`;
}

export function generateEncounters(realmId: string): Encounter[] {
  const realm = REALMS.find(r => r.id === realmId);
  if (!realm) throw new Error(`unknown realm ${realmId}`);
  const out: Encounter[] = [];
  const rnd = mulberry32(realmId.length * 1000 + realmId.charCodeAt(0));
  for (let i = 1; i <= ENCOUNTERS_PER_REALM; i++) {
    const isBoss = i % 25 === 0;
    const t = i / ENCOUNTERS_PER_REALM;
    const aiTier: Encounter['aiTier'] = isBoss ? 'boss' : t < 0.25 ? 'novice' : t < 0.65 ? 'regular' : 'veteran';
    const weaponId = realm.weaponPool[Math.floor(rnd() * realm.weaponPool.length)];
    const label = isBoss
      ? bossLabel(realm.id, i)
      : `${NAME_A[Math.floor(rnd() * NAME_A.length)]}${NAME_B[Math.floor(rnd() * NAME_B.length)]} of ${realm.name.split(' ')[0]}`;
    out.push({
      realm: realm.id, index: i, label, aiTier, weaponId, isBoss,
      coinReward: isBoss ? 120 + i : 12 + Math.floor(t * 30),
      modifier: MODIFIERS[Math.floor(rnd() * MODIFIERS.length)],
    });
  }
  return out;
}

export function getEncounter(realmId: string, index: number): Encounter {
  return generateEncounters(realmId)[index - 1];
}

/** Verify: every encounter in every realm is reachable/generatable (used by tests). */
export function validateCampaign(): { encounters: number; bosses: number } {
  let encounters = 0, bosses = 0;
  for (const r of REALMS) {
    const gen = generateEncounters(r.id);
    encounters += gen.length;
    bosses += gen.filter(e => e.isBoss).length;
  }
  return { encounters, bosses };
}
