import type { EnemyAppearanceId } from '../types';

export const ENEMY_APPEARANCES: readonly EnemyAppearanceId[] = [
  'light-male',
  'dark-male',
  'light-female',
  'dark-female',
] as const;

/** Stable selection keeps replays and browser QA reproducible while still
 * distributing all shipped appearances across encounters. */
export function enemyAppearanceFor(seed: string | number): EnemyAppearanceId {
  const text = String(seed);
  let hash = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return ENEMY_APPEARANCES[(hash >>> 0) % ENEMY_APPEARANCES.length];
}

export function isEnemyAppearance(value: string | null): value is EnemyAppearanceId {
  return value !== null && (ENEMY_APPEARANCES as readonly string[]).includes(value);
}
