// Damage pipeline: physics contacts -> typed damage events.
// DOM-free; usable from Node tests.
import { Contact, Vec2, World } from 'planck';
import { CFG } from '../config';
import { BlockEvent, DamageEvent, DamageType, PartName } from '../types';

type EventSink = (evt: DamageEvent) => void;

interface EpisodeKey { [key: string]: number }

export interface ContactMotionProfile {
  axialAlignment: number;
  transverseAlignment: number;
  quality: number;
}

/** Score how the physical weapon surface moved through the contact. Edge
 * fixtures only cut efficiently when velocity crosses the blade axis; a tip
 * fixture only pierces while travelling forward along that axis. */
export function contactMotionProfile(
  surface: DamageType,
  axisX: number,
  axisY: number,
  velocityX: number,
  velocityY: number,
): ContactMotionProfile {
  if (surface === 'blunt') {
    return { axialAlignment: 0, transverseAlignment: 0, quality: 1 };
  }
  const axisLength = Math.hypot(axisX, axisY);
  const velocityLength = Math.hypot(velocityX, velocityY);
  if (!Number.isFinite(axisLength) || !Number.isFinite(velocityLength) ||
      axisLength < 0.0001 || velocityLength < 0.0001) {
    return { axialAlignment: 0, transverseAlignment: 0, quality: 0 };
  }
  const ax = axisX / axisLength;
  const ay = axisY / axisLength;
  const vx = velocityX / velocityLength;
  const vy = velocityY / velocityLength;
  const axialAlignment = ax * vx + ay * vy;
  const transverseAlignment = Math.abs(ax * vy - ay * vx);
  const quality = surface === 'pierce'
    ? (axialAlignment >= CFG.damage.pierceForwardAlignmentMin ? axialAlignment : 0)
    : CFG.damage.cutAxialQualityFloor +
      (1 - CFG.damage.cutAxialQualityFloor) * transverseAlignment;
  return { axialAlignment, transverseAlignment, quality };
}

export class DamageSystem {
  private cooldowns: EpisodeKey = {};
  private preSolveMotion = new WeakMap<object, { relAX: number; relAY: number; speed: number }>();
  private time = 0;
  lastError: unknown = null;
  onEvent: EventSink = () => {};
  onClash: (x: number, y: number, energy: number) => void = () => {};
  onBlock: (evt: BlockEvent) => void = () => {};
  onFall: (fighterId: number, part: PartName, energy: number) => void = () => {};

  install(world: World): void {
    (world as any).on('pre-step', (dt: number) => { this.time += dt; });
    world.on('pre-solve', (contact: Contact) => {
      const wm: any = contact.getWorldManifold(null as any);
      const point = wm?.points?.[0];
      const bodyA = contact.getFixtureA()?.getBody();
      const bodyB = contact.getFixtureB()?.getBody();
      if (!point || !bodyA || !bodyB) return;
      const velocityA = bodyA.getLinearVelocityFromWorldPoint(point);
      const velocityB = bodyB.getLinearVelocityFromWorldPoint(point);
      const relAX = velocityA.x - velocityB.x;
      const relAY = velocityA.y - velocityB.y;
      this.preSolveMotion.set(contact, { relAX, relAY, speed: Math.hypot(relAX, relAY) });
    });
    world.on('post-solve', (contact: Contact, impulse: any) => {
      try { this.handle(contact, impulse); } catch (error) {
        this.lastError = error; // retain diagnostics without crashing the physics loop
      }
    });
  }

  private handle(contact: Contact, impulse: any): void {
    const fA = contact.getFixtureA();
    const fB = contact.getFixtureB();
    if (!fA || !fB) return;
    const udA: any = fA.getUserData();
    const udB: any = fB.getUserData();

    // weapon surface vs body part of a different fighter
    const pair = (wUd: any, pUd: any, wFix: any, pFix: any, normalSign: 1 | -1) => {
      if (!wUd || !pUd) return;
      if (wUd.kind !== 'weaponSurface' || pUd.kind !== 'part') return;
      if (wUd.embedded) return;
      if (wUd.ownerId === pUd.fighterId) return;
      this.resolveHit(contact, impulse, wUd, pUd, wFix.getBody(), pFix.getBody(), normalSign);
    };
    pair(udA, udB, fA, fB, 1);
    pair(udB, udA, fB, fA, -1);

    const shieldPair = (wUd: any, sUd: any, wFix: any, sFix: any) => {
      if (wUd?.kind !== 'weaponSurface' || sUd?.kind !== 'shield') return;
      if (wUd.ownerId === sUd.ownerId) return;
      this.resolveBlock(contact, impulse, wUd, sUd, wFix.getBody(), sFix.getBody());
    };
    shieldPair(udA, udB, fA, fB);
    shieldPair(udB, udA, fB, fA);

    // weapon vs weapon (no damage, feedback event)
    if (udA?.kind === 'weaponSurface' && udB?.kind === 'weaponSurface' && udA.ownerId !== udB.ownerId) {
      const wm: any = contact.getWorldManifold(null as any);
      const p = wm?.points?.[0] ?? Vec2(0, 0);
      const e = impulse?.normalImpulses?.[0] ?? 0;
      if (e > 1.5) this.onClash(p.x, p.y, e);
    }

    // hard body impacts with the ground (fall damage signal).
    // feet/shins touch the ground constantly in normal stance — their contacts
    // are stance micro-impacts, not falls; only upper-body ground hits count.
    const FALL_EXEMPT = new Set(['footL', 'footR', 'shinL', 'shinR']);
    const groundPair = (pUd: any, otherUd: any, pFix: any) => {
      if (pUd?.kind === 'part' && otherUd?.kind === 'ground' && !FALL_EXEMPT.has(pUd.part)) {
        const e = impulse?.normalImpulses?.[0] ?? 0;
        if (e > 12) this.onFall(pUd.fighterId, pUd.part, e);
      }
    };
    groundPair(udA, udB, fA);
    groundPair(udB, udA, fB);
  }

  private resolveBlock(contact: Contact, impulse: any, wUd: any, sUd: any, wBody: any, sBody: any): void {
    const key = `block:${wUd.instanceId}:${sUd.instanceId}`;
    const last = this.cooldowns[key] ?? -1;
    if (this.time - last < CFG.damage.cooldown) return;
    const wm: any = contact.getWorldManifold(null as any);
    if (!wm?.points?.length) return;
    const p = wm.points[0];
    const vW = wBody.getLinearVelocityFromWorldPoint(p);
    const vS = sBody.getLinearVelocityFromWorldPoint(p);
    const relSpeed = Math.hypot(vW.x - vS.x, vW.y - vS.y);
    const mEff = Math.min(wBody.getMass(), sBody.getMass());
    const normalImpulse = Math.abs(impulse?.normalImpulses?.[0] ?? 0);
    const impulseEnergy = normalImpulse * normalImpulse / Math.max(0.001, 2 * mEff);
    const energy = Math.max(0.5 * mEff * relSpeed * relSpeed, impulseEnergy);
    if (energy < 0.5) return;
    const type = wUd.surface as DamageType;
    const damageFactor = CFG.shield.factor[type] ?? CFG.shield.factor.blunt;
    this.cooldowns[key] = this.time;
    this.onBlock({
      attackerId: wUd.ownerId,
      defenderId: sUd.ownerId,
      type,
      energy,
      damageFactor,
      x: p.x,
      y: p.y,
    });
  }

  private resolveHit(
    contact: Contact, impulse: any, wUd: any, pUd: any,
    wBody: any, pBody: any, normalSign: 1 | -1,
  ): void {
    const key = `${wUd.instanceId}:${pUd.part}:${wUd.ownerId}`;
    const last = this.cooldowns[key] ?? -1;
    if (this.time - last < CFG.damage.cooldown) return;

    const wm: any = contact.getWorldManifold(null as any);
    if (!wm || !wm.points || wm.points.length === 0) return;
    const p = wm.points[0];

    // relative velocity at the contact point, including angular contribution
    const vW = wBody.getLinearVelocityFromWorldPoint(p);
    const vP = pBody.getLinearVelocityFromWorldPoint(p);
    const postRelX = vW.x - vP.x, postRelY = vW.y - vP.y;
    const postRelSpeed = Math.hypot(postRelX, postRelY);
    const pre = this.preSolveMotion.get(contact);
    const weaponIsA = contact.getFixtureA()?.getBody() === wBody;
    const preRelX = pre ? (weaponIsA ? pre.relAX : -pre.relAX) : 0;
    const preRelY = pre ? (weaponIsA ? pre.relAY : -pre.relAY) : 0;
    const relSpeed = Math.max(postRelSpeed, pre?.speed ?? 0);
    const usePreSolveDirection = !!pre && pre.speed > 0.001;
    const relX = usePreSolveDirection ? preRelX : postRelX;
    const relY = usePreSolveDirection ? preRelY : postRelY;

    const mW = wBody.getMass();
    const mP = pBody.getMass();
    const mEff = Math.min(mW + 0.6, (mW * mP) / (mW + mP) + mW * 0.35);
    // Preserve both the measured pre-solve approach speed and the solver's
    // normal impulse. Post-solve velocity alone can point sideways or reverse
    // after the exact contact that stopped a committed stab.
    const normalImpulse = Math.abs(impulse?.normalImpulses?.[0] ?? 0);
    const impulseEnergy = normalImpulse * normalImpulse / Math.max(0.001, 2 * mEff);
    const impactSpeed = normalImpulse / Math.max(0.001, mEff);
    const rawEnergy = Math.max(0.5 * mEff * relSpeed * relSpeed, impulseEnergy);
    if (relSpeed < 0.8 && impulseEnergy < CFG.damage.minEnergy) return;

    const surface = wUd.surface as DamageType;
    const weaponAxis = wBody.getWorldVector(Vec2(1, 0));
    const motion = contactMotionProfile(surface, weaponAxis.x, weaponAxis.y, relX, relY);
    const energy = rawEnergy * motion.quality;
    if (energy < CFG.damage.minEnergy) return;
    const surfaceF = CFG.damage.surfaceFactor[surface] ?? 1;
    const partF = CFG.damage.partFactor[pUd.part] ?? CFG.damage.partFactor.default;
    const weaponF = wUd.factor ?? 1;
    const damage = energy * surfaceF * partF * weaponF * 0.22;

    this.cooldowns[key] = this.time;
    this.onEvent({
      attackerId: wUd.ownerId,
      defenderId: pUd.fighterId,
      part: pUd.part as PartName,
      type: surface,
      energy,
      damage,
      x: p.x, y: p.y,
      dirX: relSpeed > 0.001 ? relX / relSpeed : 0,
      dirY: relSpeed > 0.001 ? relY / relSpeed : 0,
      relativeSpeed: relSpeed,
      impactSpeed: Math.max(relSpeed, impactSpeed),
      normalX: (wm.normal?.x ?? 0) * normalSign,
      normalY: (wm.normal?.y ?? 0) * normalSign,
      axialAlignment: motion.axialAlignment,
      transverseAlignment: motion.transverseAlignment,
      contactQuality: motion.quality,
      weaponInstanceId: wUd.instanceId,
    });
  }

  /** Pure helper: damage multiplier of an armor material vs damage type (for tests + future armor). */
  static materialFactor(material: string, type: DamageType): number {
    const m = (CFG.damage.material as any)[material];
    return m ? (m as any)[type] : 1;
  }
}
