// Game orchestrator: owns the world, the fighters, the loop and the screens.
import { Edge, Vec2, World } from 'planck';
import { CFG } from '../config';
import { DamageSystem } from '../physics/Damage';
import { PenetrationSystem } from '../physics/Penetration';
import { Fighter } from '../physics/Fighter';
import { settleFightersForSpawn } from '../physics/SpawnSettle';
import { WEAPONS } from '../physics/Weapons';
import { AIBrain } from '../ai/AIBrain';
import { Controls } from '../input/Controls';
import { Renderer } from '../render/Renderer';
import { Hud } from '../render/Hud';
import { Assets, arenaArtId } from '../render/Assets';
import { AudioBus } from './Audio';
import { Encounter, getEncounter, REALMS } from './Campaign';
import { loadSave, persistSave, SaveData, sealsFor } from './Save';
import { Tutorial } from './Tutorial';
import { DamageEvent, FightResult, FighterInput, IDLE_INPUT } from '../types';
import { ARMOR_ORDER, armorById, buyArmor, equipArmor } from './Armor';
import { enemyAppearanceFor, isEnemyAppearance } from './EnemyAppearance';
import { buyWeapon, equipWeapon, equippedWeapon, fightWeaponId, WEAPON_ORDER } from './WeaponLoadout';
import { combatStyleForWeapon, CombatStyleId, COMBAT_STYLES } from '../combat/CombatStyles';
import { DEFAULT_SHIELD_STYLE, SHIELD_STYLES, ShieldStyleId } from '../combat/ShieldStyles';

export type GameMode = 'duel' | 'training' | 'gauntlet' | 'journey';

const GAUNTLET_TIERS = ['novice', 'regular', 'regular', 'veteran', 'veteran', 'boss'] as const;

export class Game {
  canvas: HTMLCanvasElement;
  renderer: Renderer;
  hud = new Hud();
  audio = new AudioBus();
  controls = new Controls();
  save: SaveData;

  world!: World;
  fighters: Fighter[] = [];
  brains: (AIBrain | null)[] = [];
  damageSys = new DamageSystem();
  penetration = new PenetrationSystem();

  state: 'home' | 'journey' | 'armor' | 'combatlab' | 'shieldlab' | 'fight' | 'results' = 'home';
  mode: GameMode = 'duel';
  encounter: Encounter | null = null;
  realmId = REALMS[0].id;
  gauntletStreak = 0;
  activeArena = 'bramble'; // arena art for the current fight
  private duelCount = 0;

  private accumulator = 0;
  private lastT = 0;
  private animationFrameId: number | null = null;
  private running = false;
  private events = new AbortController();
  paused = false;
  fightStarted = false;      // true once the countdown reaches FIGHT
  fightOver = false;
  result: FightResult | null = null;
  private endTimer = -1;
  private faceTimer = 0;
  private elapsed = 0;         // fight time, only counted after FIGHT
  private countdownT = 0;      // seconds left in the 3-2-1 countdown
  private fightFlashT = 0;     // seconds left to show the FIGHT flash
  private hitStopT = 0;
  private countdownText = '';  // last text written to the countdown element
  tutorial = new Tutorial();
  private tutText: string | null = null; // last text written to the tutorial element
  private settingsReturnToPause = false;
  private urlParams = new URLSearchParams(location.search);
  private telemetryEnabled = this.urlParams.get('telemetry') === '1';
  private qaMode = this.telemetryEnabled ? this.urlParams.get('qa') : null;
  private silentMode = this.telemetryEnabled || this.urlParams.get('mute') === '1';
  private sandboxMode = this.urlParams.get('sandbox') === '1';
  private fightingRebuildMode = this.urlParams.get('fighting-rebuild') === '1';
  private fightingRebuildWeapon = 'sword';

  // test hooks
  overridePlayerInput: FighterInput | null = null;
  disableAI = false;
  onFightEnd: ((r: FightResult) => void) | null = null;
  lastDamageEvents: any[] = [];

  private el = (id: string) => document.getElementById(id)!;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.renderer = new Renderer(canvas);
    if (this.silentMode) this.audio.enabled = false;
    this.save = loadSave();
    if (this.sandboxMode) {
      this.save.coins = Number.MAX_SAFE_INTEGER;
      this.save.unlockedWeapons = Object.keys(WEAPONS);
      this.save.settings.pixelStyle = 'detailed';
      persistSave(this.save);
    }
    this.controls.attach(canvas, (x, y) => this.renderer.screenToWorld(x, y));
    this.damageSys.onEvent = evt => this.handleDamage(evt);
    this.damageSys.onClash = (x, y, e) => {
      this.renderer.addEffect(x, y, 'clash');
      this.audio.impact(e, 'metal', x / CFG.physics.arenaHalfWidth);
    };
    this.damageSys.onBlock = evt => {
      const defender = this.fighters[evt.defenderId];
      defender?.absorbBlock(evt.energy, evt.damageFactor);
      this.renderer.addEffect(evt.x, evt.y, 'clash');
      this.renderer.kick(Math.min(0.7, evt.energy / 55));
      this.audio.impact(evt.energy, 'wood', evt.x / CFG.physics.arenaHalfWidth);
    };
    this.damageSys.onFall = (fid, part, e) => {
      const f = this.fighters[fid];
      if (f) {
        const p = f.part(part).body.getPosition();
        this.renderer.addEffect(p.x, Math.max(0.06, p.y * 0.3), 'dust');
        this.audio.impact(e * 0.6, 'wood', p.x / CFG.physics.arenaHalfWidth);
      }
    };
    this.penetration.onEmbed = event => {
      this.renderer.addEffect(event.x, event.y, 'pierce');
      this.renderer.kick(0.18);
    };
    this.penetration.onExtract = event => {
      const direction = this.fighters[event.defenderId]?.pelvis().getPosition().x >=
        this.fighters[event.attackerId]?.pelvis().getPosition().x ? 1 : -1;
      this.renderer.addBloodSpray(event.x, event.y, direction, 2.8);
      this.renderer.addEffect(event.x, event.y, 'pierce');
    };
    this.wireScreens();
    this.refreshHome();
    this.applySettings();
    window.addEventListener('keydown', e => {
      if (e.key === 'Escape' && this.tutorial.active) {
        this.tutorial.skip();
        this.setTutorial(null);
        this.markTutorialDone();
      } else if (e.key === 'Escape' && this.settingsReturnToPause) {
        this.returnToPauseMenu();
      } else if (e.key === 'Escape' && this.state === 'fight') {
        this.setPaused(!this.paused);
      }
    }, { signal: this.events.signal });
  }

  /** Guarded tutorial overlay write (same anti-churn pattern as setCountdown). */
  private setTutorial(text: string | null): void {
    if (text === this.tutText) return;
    this.tutText = text;
    const el = this.el('tut');
    if (text === null) { el.classList.add('hidden'); return; }
    el.textContent = text;
    el.classList.remove('hidden');
  }

  private markTutorialDone(): void {
    if (!this.save.tutorialsDone.includes('controls')) this.save.tutorialsDone.push('controls');
    persistSave(this.save);
  }

  /** Push persisted settings into audio/renderer/DOM. */
  private applySettings(): void {
    const s = this.save.settings;
    this.audio.setVolume(s.audioVolume);
    this.renderer.reducedFlash = s.reduceFlash;
    this.renderer.pixelStyle = s.pixelStyle;
    document.body.classList.toggle('hc', s.highContrast);
    document.body.classList.toggle('noflash', s.reduceFlash);
    document.body.classList.toggle('pixelCoarse', s.pixelStyle === 'coarse');
  }

  private showSettings(returnToPause = false): void {
    this.settingsReturnToPause = returnToPause;
    const s = this.save.settings;
    (this.el('setVolume') as HTMLInputElement).value = String(Math.round(s.audioVolume * 100));
    (this.el('setReduceFlash') as HTMLInputElement).checked = s.reduceFlash;
    (this.el('setHighContrast') as HTMLInputElement).checked = s.highContrast;
    (this.el('setPixelStyle') as HTMLSelectElement).value = s.pixelStyle;
    this.show('settings');
  }

  private setPaused(value: boolean): void {
    this.paused = value;
    this.controls.enabled = !value;
    this.el('pauseMenu').classList.toggle('hidden', !value);
    if (value) this.setCountdown(null);
  }

  private returnToPauseMenu(): void {
    this.settingsReturnToPause = false;
    this.show('');
    this.el('pauseMenu').classList.remove('hidden');
  }

  private quitFight(): void {
    this.setPaused(false);
    this.settingsReturnToPause = false;
    this.audio.stopAmbience();
    this.tutorial.reset(false);
    this.setTutorial(null);
    this.state = 'home';
    this.hud.show(false);
    this.show('home');
    this.refreshHome();
  }

  // ------------------------------------------------------------ screens
  private coinLabel(): string {
    return this.save.coins >= 1_000_000_000 ? 'MAX' : String(this.save.coins);
  }

  private show(id: string): void {
    for (const s of ['home', 'journey', 'armor', 'combatlab', 'shieldlab', 'results', 'settings']) this.el(s).classList.add('hidden');
    if (id) this.el(id).classList.remove('hidden');
  }

  private refreshHome(): void {
    this.el('homeCoins').textContent = this.coinLabel();
    this.el('homeArmor').textContent = armorById(this.save.equippedArmor).name;
    this.el('homeWeapon').textContent = equippedWeapon(this.save).name.toUpperCase();
    const weapon = equippedWeapon(this.save);
    this.el('homeCombat').textContent = `${COMBAT_STYLES[combatStyleForWeapon(weapon.id)].name.toUpperCase()} · ${weapon.name.toUpperCase()}`;
    this.el('homeShield').textContent = SHIELD_STYLES[DEFAULT_SHIELD_STYLE].name.toUpperCase();
  }

  private showCombatLab(): void {
    this.state = 'combatlab';
    this.hud.show(false);
    this.show('combatlab');
  }

  private startCombatPrototype(style: CombatStyleId): void {
    this.startFight('training', undefined, COMBAT_STYLES[style].weaponId);
  }

  private showShieldLab(): void {
    this.state = 'shieldlab';
    this.hud.show(false);
    this.show('shieldlab');
  }

  private startShieldPrototype(style: ShieldStyleId): void {
    this.startFight('training', undefined, 'sword', style);
  }

  private showArmory(): void {
    this.state = 'armor';
    this.el('armorCoins').textContent = this.coinLabel();
    const list = this.el('armorList');
    list.innerHTML = '';
    const weaponHeading = document.createElement('h2');
    weaponHeading.className = 'armorySection';
    weaponHeading.textContent = 'WEAPONS';
    list.appendChild(weaponHeading);
    for (const id of WEAPON_ORDER) {
      const def = WEAPONS[id];
      const owned = this.save.unlockedWeapons.includes(id);
      const equipped = this.save.equippedWeapon === id;
      const node = document.createElement('button');
      node.type = 'button';
      node.className = `node armorNode weaponNode${equipped ? ' equipped' : ''}`;
      node.setAttribute('aria-pressed', String(equipped));
      const status = equipped ? 'EQUIPPED' : owned ? 'EQUIP' : `${def.price} COINS`;
      node.innerHTML = `<span class="weaponGlyph weapon-${id}" aria-hidden="true"></span><span class="armorCopy"><b>${def.name.toUpperCase()}</b><small>${def.kind.toUpperCase()} · ${def.mass.toFixed(2)} kg · ${def.length.toFixed(2)} m</small></span><span class="seals">${status}</span>`;
      node.addEventListener('click', () => {
        if (owned) equipWeapon(this.save, id);
        else if (buyWeapon(this.save, id) === 'bought') equipWeapon(this.save, id);
        persistSave(this.save);
        this.audio.ui();
        this.showArmory();
      });
      list.appendChild(node);
    }
    const armorHeading = document.createElement('h2');
    armorHeading.className = 'armorySection';
    armorHeading.textContent = 'ARMOR';
    list.appendChild(armorHeading);
    for (const id of ARMOR_ORDER) {
      const def = armorById(id);
      const owned = this.save.unlockedArmor.includes(id);
      const equipped = this.save.equippedArmor === id;
      const node = document.createElement('button');
      node.type = 'button';
      node.className = `node armorNode${equipped ? ' equipped' : ''}`;
      const status = equipped ? 'EQUIPPED' : owned ? 'EQUIP' : `${def.price} COINS`;
      node.innerHTML = `<img class="armorIcon" src="/assets/ui/armor_${id}.png" alt="" aria-hidden="true"><span class="armorCopy"><b>${def.name}</b><small>${def.description} · ${def.mass.toFixed(1)} kg</small></span><span class="seals">${status}</span>`;
      node.addEventListener('click', () => {
        if (owned) equipArmor(this.save, id);
        else if (buyArmor(this.save, id) === 'bought') equipArmor(this.save, id);
        persistSave(this.save);
        this.audio.ui();
        this.showArmory();
      });
      list.appendChild(node);
    }
    this.show('armor');
  }

  private wireScreens(): void {
    const click = (id: string, fn: () => void) => {
      this.el(id).addEventListener('click', () => { this.audio.ui(); fn(); }, { signal: this.events.signal });
    };
    click('btnDuel', () => this.startFight('duel'));
    click('btnTraining', () => this.startFight('training'));
    click('btnGauntlet', () => { this.gauntletStreak = 0; this.startFight('gauntlet'); });
    click('btnJourney', () => { this.showJourney(); });
    click('btnJourneyBack', () => { this.state = 'home'; this.show('home'); this.refreshHome(); this.hud.show(false); });
    click('btnResultNext', () => this.afterResults());
    click('btnResultRematch', () => this.rematch());
    click('btnSettings', () => this.showSettings(false));
    click('btnArmory', () => this.showArmory());
    click('btnCombatLab', () => this.showCombatLab());
    click('btnCombatLabBack', () => { this.state = 'home'; this.show('home'); this.refreshHome(); });
    click('btnCombatClassic', () => this.startCombatPrototype('classic'));
    click('btnCombatGuided', () => this.startCombatPrototype('guided'));
    click('btnCombatMomentum', () => this.startCombatPrototype('momentum'));
    click('btnCombatCommitted', () => this.startCombatPrototype('committed'));
    click('sandboxDagger', () => this.startFightingSandbox('dagger'));
    click('sandboxSword', () => this.startFightingSandbox('sword'));
    click('sandboxMace', () => this.startFightingSandbox('mace'));
    click('sandboxFlail', () => this.startFightingSandbox('flail'));
    click('sandboxRestart', () => this.startFightingSandbox(this.fightingRebuildWeapon));
    click('btnShieldLab', () => this.showShieldLab());
    click('btnShieldLabBack', () => { this.state = 'home'; this.show('home'); this.refreshHome(); });
    click('btnShieldDirect', () => this.startShieldPrototype('direct'));
    click('btnShieldFortress', () => this.startShieldPrototype('fortress'));
    click('btnShieldBash', () => this.startShieldPrototype('bash'));
    click('btnArmorBack', () => { this.state = 'home'; this.show('home'); this.refreshHome(); });
    click('btnSettingsBack', () => {
      if (this.settingsReturnToPause) this.returnToPauseMenu();
      else { this.show('home'); this.refreshHome(); }
    });
    click('btnPauseResume', () => this.setPaused(false));
    click('btnPauseSettings', () => {
      this.el('pauseMenu').classList.add('hidden');
      this.showSettings(true);
    });
    click('btnPauseQuit', () => this.quitFight());
    click('touchPause', () => {
      if (this.state === 'fight') this.setPaused(true);
    });

    const s = this.save.settings;
    const vol = this.el('setVolume') as HTMLInputElement;
    vol.addEventListener('input', () => { s.audioVolume = Number(vol.value) / 100; this.applySettings(); persistSave(this.save); }, { signal: this.events.signal });
    const rf = this.el('setReduceFlash') as HTMLInputElement;
    rf.addEventListener('change', () => { s.reduceFlash = rf.checked; this.applySettings(); persistSave(this.save); }, { signal: this.events.signal });
    const hc = this.el('setHighContrast') as HTMLInputElement;
    hc.addEventListener('change', () => { s.highContrast = hc.checked; this.applySettings(); persistSave(this.save); }, { signal: this.events.signal });
    const pixelStyle = this.el('setPixelStyle') as HTMLSelectElement;
    pixelStyle.addEventListener('change', () => {
      s.pixelStyle = pixelStyle.value === 'coarse' ? 'coarse' : 'detailed';
      this.applySettings();
      persistSave(this.save);
    }, { signal: this.events.signal });
  }

  /** Restart the same fight setup; duels keep the same arena (no rotation advance). */
  private rematch(): void {
    if (this.mode === 'duel') this.duelCount--;
    this.startFight(this.mode, this.encounter ?? undefined);
  }

  private showJourney(): void {
    this.state = 'journey';
    this.hud.show(false);
    this.el('realmName').textContent = REALMS.find(r => r.id === this.realmId)!.name.toUpperCase();
    const list = this.el('levelList');
    list.innerHTML = '';
    for (let i = 1; i <= 12; i++) {
      const enc = getEncounter(this.realmId, i);
      const seals = sealsFor(this.save, this.realmId, i);
      const prevDone = i === 1 || sealsFor(this.save, this.realmId, i - 1) >= 0;
      const node = document.createElement('div');
      node.className = 'node' + (prevDone ? '' : ' locked');
      node.innerHTML = `<span>${i}. ${enc.label}${enc.isBoss ? ' ☠' : ''}</span>` +
        `<span class="seals">${seals < 0 ? '···' : '★'.repeat(seals) || '—'}</span>`;
      if (prevDone) node.addEventListener('click', () => { this.audio.ui(); this.startFight('journey', enc); });
      list.appendChild(node);
    }
    this.show('journey');
  }

  private afterResults(): void {
    if (this.mode === 'gauntlet' && this.result && this.result.winnerId === 0) {
      this.gauntletStreak++;
      this.startFight('gauntlet');
      return;
    }
    this.state = this.mode === 'journey' ? 'journey' : 'home';
    this.hud.show(false);
    this.show(this.mode === 'journey' ? 'journey' : 'home');
    if (this.mode === 'journey') this.showJourney(); else this.refreshHome();
  }

  // ------------------------------------------------------------ world
  private buildWorld(): void {
    this.penetration.clear();
    this.world = World({ gravity: Vec2(0, CFG.physics.gravityY) });
    const ground = this.world.createBody();
    ground.createFixture({
      shape: Edge(Vec2(-20, 0), Vec2(20, 0)),
      friction: CFG.physics.groundFriction, restitution: 0,
      userData: { kind: 'ground' },
    });
    // invisible arena walls keep fighters inside the field
    const hw = CFG.physics.arenaHalfWidth;
    const walls = this.world.createBody();
    walls.createFixture({
      shape: Edge(Vec2(-hw, -0.2), Vec2(-hw, CFG.physics.wallHeight)),
      friction: 0.2, restitution: 0.2, userData: { kind: 'wall' },
    });
    walls.createFixture({
      shape: Edge(Vec2(hw, -0.2), Vec2(hw, CFG.physics.wallHeight)),
      friction: 0.2, restitution: 0.2, userData: { kind: 'wall' },
    });
  }

  startFight(
    mode: GameMode,
    encounter?: Encounter,
    prototypeWeapon?: string,
    prototypeShield: ShieldStyleId = DEFAULT_SHIELD_STYLE,
  ): void {
    this.setPaused(false);
    this.settingsReturnToPause = false;
    this.mode = mode;
    this.encounter = encounter ?? null;
    this.buildWorld();

    const gTier = GAUNTLET_TIERS[Math.min(this.gauntletStreak, GAUNTLET_TIERS.length - 1)];
    const foeTier = mode === 'training' ? 'novice'
      : mode === 'gauntlet' ? gTier
      : mode === 'journey' ? this.encounter!.aiTier : 'regular';
    const foeWeapon = prototypeWeapon ?? (mode === 'journey' ? this.encounter!.weaponId
      : mode === 'gauntlet' ? ['dagger', 'sword', 'mace'][this.gauntletStreak % 3]
      : 'sword');
    const requestedQaWeapon = this.telemetryEnabled ? this.urlParams.get('weapon') : null;
    const playerWeapon = prototypeWeapon ?? fightWeaponId(this.save, requestedQaWeapon);
    const playerWeaponDef = WEAPONS[playerWeapon] ?? WEAPONS.dagger;
    const foeWeaponDef = WEAPONS[foeWeapon] ?? WEAPONS.sword;
    const playerCombatStyle = combatStyleForWeapon(playerWeaponDef.id);
    const foeCombatStyle = combatStyleForWeapon(foeWeaponDef.id);
    // Read-only browser QA can preview every material without mutating the
    // player's local save. Normal sessions always use the equipped armor.
    const qaArmorMaterial = this.telemetryEnabled ? this.urlParams.get('armorMaterial') : null;
    const playerArmor = armorById(qaArmorMaterial ?? this.save.equippedArmor);
    const appearanceSeed = `${mode}:${this.encounter?.realm ?? this.realmId}:${this.encounter?.index ?? 0}:${this.gauntletStreak}:${this.duelCount}`;
    const requestedAppearance = this.telemetryEnabled ? this.urlParams.get('enemyAppearance') : null;
    const foeAppearance = isEnemyAppearance(requestedAppearance)
      ? requestedAppearance
      : enemyAppearanceFor(appearanceSeed);

    const penetrationQa = this.qaMode === 'stab';
    const shoveQa = this.qaMode === 'shove';
    const controlledMotionQa = penetrationQa || shoveQa || this.qaMode === 'arms' ||
      this.qaMode === 'orbit' || this.qaMode === 'fastorbit' ||
      this.qaMode === 'flailturn' || this.qaMode === 'shieldbox' ||
      this.qaMode === 'edgedhigh' || this.qaMode === 'edgedlow';
    const playerSpawnX = shoveQa ? -0.38 : penetrationQa ? -0.40 : -1.3;
    const foeSpawnX = shoveQa ? 0.38 : penetrationQa ? 0.40 : 1.3;
    const p = new Fighter(this.world, {
      id: 0, x: playerSpawnX, facing: 1, label: 'YOU', tint: 0,
      equipmentMassKg: playerWeaponDef.mass + CFG.shield.mass + playerArmor.mass,
      locomotionRate: 1.08,
      combatStyle: playerCombatStyle,
      shieldStyle: prototypeShield,
    });
    const e = new Fighter(this.world, {
      id: 1, x: foeSpawnX, facing: -1,
      label: mode === 'journey' ? this.encounter!.label.toUpperCase().slice(0, 14) : 'FOE',
      tint: mode === 'gauntlet' ? (this.gauntletStreak % 4) : 1,
      equipmentMassKg: foeWeaponDef.mass + CFG.shield.mass,
      visualVariant: foeAppearance,
      locomotionRate: mode === 'training' ? 1 : 0.95,
      combatStyle: foeCombatStyle,
      shieldStyle: prototypeShield,
    });
    p.armorMaterial = playerArmor.material;
    p.equipWeapon(playerWeaponDef);
    if (!this.fightingRebuildMode) e.equipWeapon(foeWeaponDef);
    if (penetrationQa) e.dropWeapon();
    if (!penetrationQa) p.equipShield();
    if (!penetrationQa && !shoveQa && !this.fightingRebuildMode) e.equipShield();
    if (controlledMotionQa) this.disableAI = true;
    this.fighters = [p, e];
    // Build and settle the active ragdolls off-screen. The player therefore
    // appears already planted and cannot drift inward during 3-2-1.
    settleFightersForSpawn(this.world, this.fighters);
    this.damageSys.install(this.world);

    // pick the arena art set for this fight
    const gauntletArenas = ['bramble', 'copper', 'rime'];
    this.activeArena = mode === 'journey' ? arenaArtId(this.encounter!.realm)
      : mode === 'gauntlet' ? gauntletArenas[this.gauntletStreak % gauntletArenas.length]
      : mode === 'duel' ? gauntletArenas[this.duelCount++ % gauntletArenas.length]
      : 'bramble';
    const qaArena = this.telemetryEnabled ? this.urlParams.get('arena') : null;
    if (qaArena && ['bramble', 'copper', 'rime', 'ember', 'chunky'].includes(qaArena)) {
      this.activeArena = qaArena;
    }

    this.brains = [null, mode === 'training' ? null : new AIBrain(foeTier as any, 9000 + this.gauntletStreak * 77)];
    this.fightStarted = false;
    this.fightOver = false;
    this.result = null;
    this.endTimer = -1;
    this.elapsed = 0;
    this.countdownT = CFG.round.countdownSec;
    this.fightFlashT = 0;
    this.countdownText = '';
    this.lastDamageEvents = [];
    this.hitStopT = 0;
    this.state = 'fight';
    this.show('');
    this.hud.show(true);
    const combat = COMBAT_STYLES[p.combatStyle];
    const shield = SHIELD_STYLES[p.shieldStyle];
    this.el('hint').textContent = `SPACE / E = FORWARD · TAP SPACE / Q = BACK · ${combat.instructions} · ${shield.instructions} · ESC = PAUSE`;
    this.renderer.camX = 0;
    this.tutorial.reset(mode === 'training' && !this.save.tutorialsDone.includes('controls'));
    this.setTutorial(null);
    // arena ambience bed (bramble: coastal wind+rain, copper: crowd, rime: wind)
    const amb = { bramble: 'windrain', copper: 'crowd', rime: 'wind' } as const;
    this.audio.startAmbience(amb[this.activeArena as keyof typeof amb] ?? 'wind');
    this.renderer.floaters.length = 0; // no stray damage numbers from the previous fight
    this.renderer.particles.length = 0;
    this.renderer.partFlashes.clear();
    this.renderer.wounds.length = 0;
    this.renderer.bloodPools.length = 0;
    this.renderer.pierceStreaks.length = 0;
    this.renderer.vignette = 0;
  }

  /** Isolated, muted-by-URL fighting surface. It deliberately skips campaign,
   * enemy weapons, AI and the countdown while keeping the selected Fortress
   * shield so weapon and shield contact can be tested against a passive dummy. */
  startFightingSandbox(requestedWeapon: string): void {
    const weaponId = Object.prototype.hasOwnProperty.call(WEAPONS, requestedWeapon)
      ? requestedWeapon
      : 'sword';
    this.fightingRebuildMode = true;
    this.fightingRebuildWeapon = weaponId;
    this.disableAI = true;
    this.startFight('training', undefined, weaponId);
    this.brains = [null, null];
    this.tutorial.reset(false);
    this.setTutorial(null);
    this.fightStarted = true;
    this.countdownT = 0;
    this.fightFlashT = 0;
    this.setCountdown(null);
    document.body.classList.add('fightingRebuild');
    document.title = 'Ironbound: Fighting Rebuild Sandbox';
    this.el('fightingSandboxBar').classList.remove('hidden');
    for (const [id, value] of [
      ['sandboxDagger', 'dagger'],
      ['sandboxSword', 'sword'],
      ['sandboxMace', 'mace'],
      ['sandboxFlail', 'flail'],
    ] as const) {
      this.el(id).setAttribute('aria-pressed', String(value === weaponId));
    }
    this.el('hint').textContent =
      'CLICK + DRAG = DIRECT WEAPON · RELEASE = SHORT PHYSICAL CARRY · SHIFT + WASD = FORTRESS SHIELD · SPACE / E = FORWARD · Q = BACK';
    const url = new URL(location.href);
    url.searchParams.set('fighting-rebuild', '1');
    url.searchParams.set('weapon', weaponId);
    url.searchParams.set('mute', '1');
    history.replaceState(null, '', url);
  }

  // ------------------------------------------------------------ damage flow
  private handleDamage(evt: DamageEvent): void {
    // Countdown contacts are pose settling, not combat. In particular, a
    // close-range training setup must not turn guard repositioning into an
    // invisible pre-fight wound or penetration lock.
    if (!this.fightStarted || this.fightOver) return;
    const defender = this.fighters[evt.defenderId];
    if (!defender) return;
    const attacker = this.fighters[evt.attackerId];
    if (evt.type === 'pierce' && attacker?.weapon &&
        attacker.weapon.instanceId === evt.weaponInstanceId) {
      this.penetration.queue(
        evt, attacker.weapon, defender.part(evt.part).body, defender.armorMaterial,
      );
    }
    defender.applyDamage(evt.part, evt.damage, evt.type);
    this.lastDamageEvents.push(evt);
    if (this.lastDamageEvents.length > 200) this.lastDamageEvents.shift();
    this.renderer.addEffect(evt.x, evt.y, evt.type);
    this.renderer.flashPart(evt.defenderId, evt.part);
    this.renderer.addDamageNumber(evt.x, evt.y, evt.damage, evt.type);
    this.renderer.kick(Math.min(1, evt.energy / 40));
    const direction = attacker && defender.pelvis().getPosition().x >= attacker.pelvis().getPosition().x ? 1 : -1;
    const hitDirX = typeof evt.dirX === 'number' && Number.isFinite(evt.dirX) && Math.abs(evt.dirX) > 0.001
      ? evt.dirX : direction;
    const hitDirY = typeof evt.dirY === 'number' && Number.isFinite(evt.dirY) ? evt.dirY : 0;
    defender.applyHitReaction(evt.part, evt.energy, hitDirX, hitDirY, evt.x, evt.y);
    const bloodSeverity = evt.type === 'blunt' ? evt.damage * 0.42 : evt.damage * 1.25;
    if (evt.type === 'cut' || evt.type === 'pierce' || bloodSeverity >= 2.2) {
      this.renderer.addBloodSpray(evt.x, evt.y, direction, bloodSeverity);
      this.renderer.addWound(evt.defenderId, evt.part, evt.damage);
    }
    this.renderer.addTraumaBurst(
      evt.x, evt.y, evt.dirX ?? direction, evt.dirY ?? 0,
      evt.type, evt.part, evt.damage,
    );
    if (evt.defenderId === 0) this.renderer.pulseVignette(Math.min(0.48, 0.10 + evt.damage * 0.025));
    const hitStop = Math.min(0.085, 0.032 + Math.sqrt(Math.max(0, evt.energy)) * 0.0045);
    this.hitStopT = Math.max(this.hitStopT, this.save.settings.reduceFlash ? Math.min(0.03, hitStop) : hitStop);
    const pan = evt.x / CFG.physics.arenaHalfWidth;
    this.audio.impact(evt.energy, evt.type === 'blunt' ? 'wood' : 'flesh', pan);
    if (attacker?.weapon?.def.kind === 'flail') this.audio.chain(evt.energy, pan);
    this.audio.grunt(Math.min(1, evt.damage / 18));
    if (this.save.settings.vibration && (navigator as any).vibrate) {
      try { navigator.vibrate(Math.min(35, evt.energy)); } catch { /* ignore */ }
    }
  }

  // ------------------------------------------------------------ loop
  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastT = performance.now();
    const loop = (t: number) => {
      if (!this.running) return;
      if (this.paused) {
        this.lastT = t;
        this.animationFrameId = requestAnimationFrame(loop);
        return;
      }
      let frame = (t - this.lastT) / 1000;
      this.lastT = t;
      if (frame > 0.25) frame = 0.25;
      this.accumulator += frame;
      const dt = CFG.physics.dt;
      let steps = 0;
      while (this.accumulator >= dt && steps < 4) {
        if (this.state === 'fight') this.renderer.capturePhysicsState(this.world);
        this.step(dt);
        this.accumulator -= dt;
        steps++;
      }
      this.renderer.setPhysicsInterpolation(this.accumulator / dt);
      if (this.state === 'fight') {
        this.renderer.updateCamera(this.fighters[0], this.fighters[1], frame);
        this.renderer.render(this.world, this.fighters, frame, this.activeArena);
        this.hud.update(this.fighters[0], this.fighters[1], 'YOU', this.fighters[1].label);
        this.publishTelemetry();
      }
      this.animationFrameId = requestAnimationFrame(loop);
    };
    this.animationFrameId = requestAnimationFrame(loop);
  }

  stop(): void {
    this.running = false;
    if (this.animationFrameId !== null) cancelAnimationFrame(this.animationFrameId);
    this.animationFrameId = null;
    this.controls.detach();
    this.events.abort();
    this.audio.stopAmbience();
  }

  /** DOM-only, opt-in telemetry so browser QA measures the real rendered run
   * without exposing mutable game internals or affecting normal gameplay. */
  private publishTelemetry(): void {
    if (!this.telemetryEnabled || this.fighters.length < 2) return;
    const lastDamage = this.lastDamageEvents[this.lastDamageEvents.length - 1] ?? null;
    this.canvas.dataset.motion = JSON.stringify({
      state: this.state,
      elapsed: this.elapsed,
      audio: {
        footsteps: this.audio.footstepCount,
        lastFootstepIntensity: this.audio.lastFootstepIntensity,
      },
      camera: {
        x: this.renderer.camX,
        zoom: this.renderer.zoom,
        worldWidth: 960 / (CFG.physics.pxPerMeter * this.renderer.zoom),
      },
      render: this.renderer.interpolationDiagnostics(this.fighters[0].pelvis()),
      art: {
        pixelStyle: this.renderer.pixelStyle,
        activeArena: this.activeArena,
        effectiveArena: this.renderer.pixelStyle === 'coarse' &&
          (this.activeArena === 'bramble' || this.activeArena === 'chunky')
          ? 'chunkyCoarse' : this.activeArena,
        coarseFighterLoaded: !!this.renderer.assets?.unarmoredFighterCoarse,
        coarseArenaLoaded: !!this.renderer.assets?.arenas.chunkyCoarse,
        armorAtlasesLoaded: Object.keys(this.renderer.assets?.armorFighters ?? {}).sort(),
        playerArmorMaterial: this.fighters[0].armorMaterial,
        enemyAppearance: this.fighters[1].visualVariant,
        enemyAtlasesLoaded: Object.keys(this.renderer.assets?.enemyFighters ?? {}).sort(),
      },
      combatStyle: this.fighters[0].combatStyle,
      combatStyles: {
        player: this.fighters[0].combatStyle,
        foe: this.fighters[1].combatStyle,
      },
      shieldStyles: {
        player: this.fighters[0].shieldStyle,
        foe: this.fighters[1].shieldStyle,
      },
      controls: this.controls.diagnostics(),
      ai: this.brains[1]?.diagnostics() ?? null,
      damage: {
        count: this.lastDamageEvents.length,
        last: lastDamage ? {
          defenderId: lastDamage.defenderId,
          part: lastDamage.part,
          type: lastDamage.type,
          energy: lastDamage.energy,
          damage: lastDamage.damage,
          relativeSpeed: lastDamage.relativeSpeed,
          impactSpeed: lastDamage.impactSpeed,
          dirX: lastDamage.dirX,
          dirY: lastDamage.dirY,
          axialAlignment: lastDamage.axialAlignment,
          transverseAlignment: lastDamage.transverseAlignment,
          contactQuality: lastDamage.contactQuality,
        } : null,
      },
      penetration: {
        embedded: this.penetration.count(),
        inserting: this.penetration.insertingCount(),
        locked: this.penetration.lockedCount(),
        depth: this.penetration.maxInsertedDepth(),
        records: this.penetration.diagnostics(),
      },
      shieldShove: this.fighters[0].shieldShoveDiagnostics(),
      player: this.fighters[0].motionDiagnostics(),
      foe: this.fighters[1].motionDiagnostics(),
    });
  }

  /** Write the countdown overlay; null hides it. Guarded against per-frame DOM churn. */
  private setCountdown(text: string | null): void {
    if (text === this.countdownText) return;
    this.countdownText = text ?? '';
    const el = this.el('countdown');
    if (text === null) { el.classList.add('hidden'); return; }
    el.textContent = text;
    el.classList.toggle('fight', text === 'FIGHT!');
    el.classList.remove('hidden');
    this.audio.ui(); // tick on each countdown beat
  }

  private updateCountdown(dt: number): void {
    if (!this.fightStarted) {
      this.countdownT -= dt;
      this.setCountdown(this.countdownT > 0 ? String(Math.ceil(this.countdownT)) : null);
      if (this.countdownT <= 0) {
        this.fightStarted = true;
        this.fightFlashT = CFG.round.fightFlashSec;
        this.setCountdown('FIGHT!');
      }
    } else if (this.fightFlashT > 0) {
      this.fightFlashT -= dt;
      if (this.fightFlashT <= 0) this.setCountdown(null);
    }
  }

  step(dt: number): void {
    if (this.state !== 'fight') return;
    if (this.hitStopT > 0) {
      this.hitStopT = Math.max(0, this.hitStopT - dt);
      return;
    }
    this.updateCountdown(dt);

    const inputsLocked = this.fightOver || !this.fightStarted;
    const playerInput = this.overridePlayerInput ?? this.qaInput() ??
      this.controls.poll(this.fighters[0], this.state === 'fight' && !inputsLocked);
    if (this.fightStarted) this.elapsed += dt;

    if (this.tutorial.active && this.fightStarted && !this.fightOver) {
      this.setTutorial(this.tutorial.update(dt, playerInput, this.lastDamageEvents));
      if (this.tutorial.consumeFinished()) this.markTutorialDone();
    }

    const foeFighter = this.fighters[1];
    let foeInput: FighterInput = { ...IDLE_INPUT };
    if (this.mode === 'training' && this.qaMode === 'stab' && !this.fightOver) {
      // Move into the isolated stab target pose during the countdown so the
      // arms are already clear when combat contacts become eligible.
      foeInput = {
        left: foeFighter.stickToWorld('L', Vec2(0, 1)),
        right: foeFighter.stickToWorld('R', Vec2(0, 1)),
        step: 0,
        move: 0,
      };
    } else if (!inputsLocked && !this.disableAI && this.brains[1]) {
      this.brains[1]!.update(dt, foeFighter, this.fighters[0], foeInput);
    } else if (this.mode === 'training' && !inputsLocked) {
      foeInput = { left: null, right: null, step: 0, move: 0 }; // training dummy: passive pose
    }

    this.faceTimer -= dt;
    if (this.faceTimer <= 0) {
      this.faceTimer = 0.6;
      this.fighters[0].faceToward(foeFighter.pelvis().getPosition().x);
      foeFighter.faceToward(this.fighters[0].pelvis().getPosition().x);
    }

    // physics substeps (120 Hz): one input frame, n servo+world integrations —
    // the 60 Hz discrete servo loop limit-cycled the arm chain (see 12b notes)
    const n = CFG.physics.substeps;
    const sdt = dt / n;
    const in0 = inputsLocked ? { ...IDLE_INPUT } : playerInput;
    const in1 = this.fightOver ? { ...IDLE_INPUT } : foeInput;
    for (let s = 0; s < n; s++) {
      this.fighters[0].update(sdt, in0);
      foeFighter.update(sdt, in1);
      this.world.step(sdt, CFG.physics.velocityIterations, CFG.physics.positionIterations);
      this.penetration.flush(this.world);
      this.penetration.update(this.world, sdt, fighterId => fighterId === 0 ? in0 : in1);
      this.fighters[0].postStep();
      foeFighter.postStep();
      if (inputsLocked) {
        this.fighters[0].stabilizeVisibleGuard();
        foeFighter.stabilizeVisibleGuard();
      }
    }
    for (const fighter of this.fighters) {
      for (const plant of fighter.consumeFootPlantEvents()) {
        this.audio.footstep(plant.intensity, plant.x / CFG.physics.arenaHalfWidth);
        this.renderer.addEffect(plant.x, 0.045, 'dust');
      }
    }

    if (!this.fightOver && (this.fighters[0].dead || this.fighters[1].dead)) {
      this.fightOver = true;
      this.endTimer = 1.4;
      const winner = this.fighters[0].dead ? 1 : 0;
      this.audio.sting(winner === 0);
      this.result = {
        winnerId: winner, loserId: 1 - winner,
        reason: 'death', durationSec: this.elapsed,
        playerVitalityPct: this.fighters[0].vitality(),
      };
    }
    if (this.fightOver && this.endTimer > 0) {
      this.endTimer -= dt;
      if (this.endTimer <= 0 && this.result) this.showResults(this.result);
    }
  }

  /** Deterministic, URL-gated live input for browser motion measurement. It is
   * unreachable in a normal game URL and exercises the full render/physics loop. */
  private qaInput(): FighterInput | null {
    const player = this.fighters[0];
    if (!player || !this.qaMode) return null;
    if (this.qaMode === 'walk') {
      return { left: null, right: null, step: 0, move: player.facing };
    }
    if (this.qaMode === 'back') {
      return { left: null, right: null, step: 0, move: -player.facing };
    }
    if (this.qaMode === 'pulse') {
      return { left: null, right: null, step: 0, move: this.elapsed < 2.5 ? player.facing : 0 };
    }
    if (this.qaMode === 'reverse') {
      return {
        left: null,
        right: null,
        step: 0,
        move: this.elapsed < 1.17 ? player.facing : -player.facing,
      };
    }
    if (this.qaMode === 'arms') {
      const t = this.elapsed;
      const leftStick = Vec2(Math.cos(t * 1.55), Math.sin(t * 1.55));
      const rightStick = Vec2(Math.cos(t * 2.05), Math.sin(t * 2.05));
      return {
        left: player.shieldToWorld(leftStick),
        right: player.stickToWorld('R', rightStick),
        step: 0,
        move: 0,
      };
    }
    if (this.qaMode === 'shieldbox') {
      const corners = [Vec2(1, 1), Vec2(-1, 1), Vec2(-1, -1), Vec2(1, -1)];
      const corner = corners[Math.floor(this.elapsed / 0.8) % corners.length];
      const shoulder = player.shoulderWorld('R');
      return {
        left: player.shieldToWorld(corner),
        right: Vec2(shoulder.x + player.facing * CFG.fighter.hand.reach, shoulder.y),
        step: 0,
        move: 0,
      };
    }
    if (this.qaMode === 'edgedhigh' || this.qaMode === 'edgedlow') {
      const referenceStick = this.qaMode === 'edgedhigh'
        ? Vec2(0, 1)
        : Vec2(0, -1);
      return {
        left: null,
        right: player.stickToWorld('R', referenceStick),
        step: 0,
        move: 0,
      };
    }
    if (this.qaMode === 'orbit' || this.qaMode === 'fastorbit' || this.qaMode === 'flailturn') {
      const orbitDuration = this.qaMode === 'fastorbit' ? 0.45 :
        this.qaMode === 'flailturn' ? 0.95 : 2.1;
      if (this.elapsed >= orbitDuration) return { ...IDLE_INPUT };
      // Begin point-forward, matching a desktop relative-drag circle. Starting
      // overhead spent the first quarter-turn merely reaching the gesture and
      // made a valid full orbit look incomplete in live QA.
      const angle = (this.elapsed / orbitDuration) * Math.PI * 2;
      return {
        left: null,
        right: player.stickToWorld('R', Vec2(Math.cos(angle), Math.sin(angle))),
        step: 0,
        move: 0,
      };
    }
    if (this.qaMode === 'stab') {
      const shoulder = player.shoulderWorld('R');
      // Let the unarmed dummy move its arms clear before the first thrust. A
      // thrust during that guard transition measures an arm collision instead
      // of the intended live torso insertion/extraction path.
      const warmupSec = 1.2;
      const stabElapsed = Math.max(0, this.elapsed - warmupSec);
      const drivingForward = this.elapsed >= warmupSec && stabElapsed % 1.35 >= 0.48;
      const reach = this.elapsed < warmupSec ? 0.05
        : drivingForward ? CFG.fighter.hand.reach : 0.18;
      return {
        left: null,
        right: Vec2(
          shoulder.x + player.facing * reach,
          shoulder.y - 0.05,
        ),
        step: 0,
        move: 0,
      };
    }
    if (this.qaMode === 'shove') {
      return {
        left: player.shieldToWorld(Vec2(player.facing, 0)),
        right: null,
        step: 0,
        move: 0,
        brace: true,
      };
    }
    return null;
  }

  private showResults(r: FightResult): void {
    this.state = 'results';
    this.hud.show(false);
    this.audio.stopAmbience();
    const win = r.winnerId === 0;
    let seals = 0, coins = 0;
    if (this.mode === 'training') {
      this.el('resultTitle').textContent = win ? 'DUMMY DOWN' : 'YOU FELL';
      coins = 0;
    } else if (win) {
      const v = r.playerVitalityPct;
      seals = v >= 66 ? 3 : v >= 33 ? 2 : 1;
      coins = (this.encounter?.coinReward ?? 15) + seals * 10;
      if (this.mode === 'gauntlet') coins += this.gauntletStreak * 5;
      this.el('resultTitle').textContent = this.mode === 'gauntlet' ? `STREAK ${this.gauntletStreak + 1}` : 'VICTORY';
    } else {
      this.el('resultTitle').textContent = 'DEFEAT';
    }
    this.el('resultSeals').textContent = '★'.repeat(seals) + '☆'.repeat(Math.max(0, 3 - seals));
    this.el('resultCoins').textContent = win ? `+${coins} coins` : '+0 coins';
    if (win && this.mode !== 'training') {
      this.save.coins += coins;
      if (this.mode === 'journey' && this.encounter) {
        const rec = (this.save.campaign[this.realmId] ??= {});
        rec[this.encounter.index] = Math.max(rec[this.encounter.index] ?? 0, seals);
      }
      if (this.mode === 'gauntlet') {
        this.save.gauntletBest = Math.max(this.save.gauntletBest, this.gauntletStreak + 1);
      }
      persistSave(this.save);
    }
    this.el('btnResultNext').textContent = this.mode === 'gauntlet' && win ? 'NEXT FOE' : 'CONTINUE';
    this.show('results');
    this.onFightEnd?.(r);
  }
}
