// Bounded, body-part-specific impulse distribution for readable physical hits.
// The collision solver remains authoritative; this only replaces the former
// one-body horizontal flinch with a small contact-direction reaction that is
// shared through the articulated kinetic chain.
import { PartName } from '../types';

export interface HitReactionProfile {
  dirX: number;
  dirY: number;
  localImpulse: number;
  rootImpulse: number;
}

const RESPONSE: Record<PartName, { local: number; root: number }> = {
  head: { local: 1.20, root: 0.22 },
  torso: { local: 0.76, root: 0.44 },
  pelvis: { local: 0.88, root: 0 },
  upperArmL: { local: 1.15, root: 0.12 },
  forearmL: { local: 1.18, root: 0.10 },
  handL: { local: 1.22, root: 0.08 },
  upperArmR: { local: 1.15, root: 0.12 },
  forearmR: { local: 1.18, root: 0.10 },
  handR: { local: 1.22, root: 0.08 },
  thighL: { local: 0.92, root: 0.22 },
  shinL: { local: 0.98, root: 0.18 },
  footL: { local: 1.02, root: 0.14 },
  thighR: { local: 0.92, root: 0.22 },
  shinR: { local: 0.98, root: 0.18 },
  footR: { local: 1.02, root: 0.14 },
};

export function hitReactionProfile(
  part: PartName, energy: number, dirX: number, dirY: number,
): HitReactionProfile {
  const safeEnergy = Math.max(0, Number.isFinite(energy) ? energy : 0);
  const x = Number.isFinite(dirX) ? dirX : 0;
  const y = Number.isFinite(dirY) ? dirY : 0;
  const magnitude = Math.hypot(x, y);
  const nx = magnitude > 0.001 ? x / magnitude : 1;
  const ny = magnitude > 0.001 ? y / magnitude : 0;
  const base = Math.max(0.035, Math.min(0.19, 0.035 + Math.sqrt(safeEnergy) * 0.016));
  const response = RESPONSE[part];
  return {
    dirX: nx,
    dirY: ny,
    localImpulse: base * response.local,
    rootImpulse: base * response.root,
  };
}
