export type ShieldStyleId = 'direct' | 'fortress' | 'bash';

export interface ShieldStyleProfile {
  id: ShieldStyleId;
  name: string;
  shortName: string;
  principle: string;
  instructions: string;
  axisSpeedScale: number;
  handForceScale: number;
  gripSpeedScale: number;
  gripKpScale: number;
  gripTorqueScale: number;
  braceTorqueScale: number;
  shoveImpulseScale: number;
  shoveCooldownScale: number;
  shoveStaminaScale: number;
  braceStaminaScale: number;
  blockStaminaScale: number;
}

