import type { SaveData } from './Save';
import { WEAPONS, WeaponDef } from '../physics/Weapons';

export const WEAPON_ORDER = ['dagger', 'sword', 'mace', 'flail'] as const;

export type WeaponPurchaseResult = 'bought' | 'owned' | 'insufficient' | 'unknown';

export function weaponById(id: string | undefined): WeaponDef {
  return WEAPONS[id ?? ''] ?? WEAPONS.dagger;
}

export function buyWeapon(save: SaveData, id: string): WeaponPurchaseResult {
  const def = WEAPONS[id];
  if (!def) return 'unknown';
  if (save.unlockedWeapons.includes(def.id)) return 'owned';
  if (save.coins < def.price) return 'insufficient';
  save.coins -= def.price;
  save.unlockedWeapons.push(def.id);
  return 'bought';
}

export function equipWeapon(save: SaveData, id: string): boolean {
  const def = WEAPONS[id];
  if (!def || !save.unlockedWeapons.includes(def.id)) return false;
  save.equippedWeapon = def.id;
  return true;
}

export function equippedWeapon(save: SaveData): WeaponDef {
  const requested = WEAPONS[save.equippedWeapon];
  if (requested && save.unlockedWeapons.includes(requested.id)) return requested;
  return WEAPONS.dagger;
}

/** Resolve the next fight loadout. URL weapon overrides are strictly an
 * opt-in telemetry surface; every playable mode, including Training Hall,
 * otherwise respects the persistent Armory choice. */
export function fightWeaponId(save: SaveData, telemetryWeaponId?: string | null): string {
  if (telemetryWeaponId && WEAPONS[telemetryWeaponId]) return telemetryWeaponId;
  return equippedWeapon(save).id;
}
