// Physical off-hand shield with a compliant, braceable grip.
import { Body, Polygon, RevoluteJoint, Vec2, World } from 'planck';
import { CFG } from '../config';

export interface ShieldInstance {
  body: Body;
  gripJoint: RevoluteJoint;
  mass: number;
  ownerId: number;
  instanceId: string;
}

export interface ShieldControlScales {
  speed: number;
  kp: number;
  torque: number;
  braceTorque: number;
}

const DEFAULT_SHIELD_SCALES: ShieldControlScales = {
  speed: 1,
  kp: 1,
  torque: 1,
  braceTorque: 1,
};

let shieldCounter = 0;

/** Convex heater-shield silhouette used by both collision tests and runtime.
 * The old full rectangle collided in the transparent top and lower corners,
 * which read as an invisible wall around the rendered shield. */
export function shieldFixtureVertices(
  width = CFG.shield.width, height = CFG.shield.height,
): Vec2[] {
  const hw = width / 2;
  const hh = height / 2;
  return [
    Vec2(-hw * 0.36, hh),
    Vec2(-hw, hh * 0.32),
    Vec2(-hw * 0.82, -hh * 0.30),
    Vec2(0, -hh),
    Vec2(hw * 0.82, -hh * 0.30),
    Vec2(hw, hh * 0.32),
    Vec2(hw * 0.36, hh),
  ];
}

function polygonArea(vertices: Vec2[]): number {
  let twiceArea = 0;
  for (let i = 0; i < vertices.length; i++) {
    const a = vertices[i];
    const b = vertices[(i + 1) % vertices.length];
    twiceArea += a.x * b.y - a.y * b.x;
  }
  return Math.abs(twiceArea) / 2;
}

export function shieldControlSpeedScale(mass: number): number {
  const safeMass = Math.max(0.1, mass);
  const raw = Math.pow(CFG.shield.controlReferenceMass / safeMass, CFG.shield.controlMassExponent);
  return Math.max(CFG.shield.controlSpeedScaleMin,
    Math.min(CFG.shield.controlSpeedScaleMax, raw));
}

export function createShield(
  world: World, hand: Body, facing: 1 | -1, groupIndex: number, ownerId: number,
): ShieldInstance {
  const handPos = hand.getPosition();
  const offset = CFG.shield.gripOffset * facing;
  const body = world.createBody({
    type: 'dynamic',
    position: Vec2(handPos.x + offset, handPos.y + 0.02),
    angle: 0,
    bullet: true,
    angularDamping: 9.0,
    linearDamping: 3.0,
  });
  const instanceId = `s${++shieldCounter}`;
  const vertices = shieldFixtureVertices();
  const fixture = body.createFixture({
    shape: Polygon(vertices),
    density: CFG.shield.mass / polygonArea(vertices),
    friction: 0.28,
    restitution: 0.06,
    filterGroupIndex: groupIndex,
    userData: { kind: 'shield', ownerId, fighterId: ownerId, instanceId },
  });
  void fixture;
  // The pointed heater silhouette has a slightly lowered geometric centroid.
  // Keep its physical centre on the rendered/pivot origin so a neutral shield
  // cannot pull the whole fighter sideways while the grip motor holds guard.
  body.setMassData({
    mass: CFG.shield.mass,
    center: Vec2(0, 0),
    I: body.getInertia(),
  });
  const gripJoint = world.createJoint(RevoluteJoint({
    enableMotor: true,
    motorSpeed: 0,
    maxMotorTorque: CFG.shield.gripMotorTorque,
  }, hand, body, Vec2(handPos.x, handPos.y))) as RevoluteJoint;
  return { body, gripJoint, mass: CFG.shield.mass, ownerId, instanceId };
}

export function updateShield(
  shield: ShieldInstance,
  motorScale: number,
  brace: boolean,
  scales: ShieldControlScales = DEFAULT_SHIELD_SCALES,
): void {
  const angle = shield.body.getAngle();
  const targetSpeed = Math.abs(angle) < 0.04 ? 0 : -angle * CFG.shield.gripMotorKP * scales.kp;
  const speedLimit = CFG.shield.gripMotorSpeed * shieldControlSpeedScale(shield.mass) * scales.speed;
  const speed = Math.max(-speedLimit, Math.min(speedLimit, targetSpeed));
  shield.gripJoint.setMotorSpeed(speed);
  const braceScale = brace ? CFG.shield.braceTorqueScale * scales.braceTorque : 1;
  shield.gripJoint.setMaxMotorTorque(CFG.shield.gripMotorTorque * braceScale * motorScale * scales.torque);
}
