// Versioned offline save (localStorage), atomic-ish write with backup slot.
import type { PixelStyle } from '../types';

const KEY = 'ironbound_save_v1';
const BACKUP_KEY = 'ironbound_save_v1.bak';

export interface SaveData {
  version: 1;
  coins: number;
  unlockedWeapons: string[];
  equippedWeapon: string;
  unlockedArmor: string[];
  equippedArmor: string;
  campaign: Record<string, Record<number, number>>; // realm -> encounter index -> seals (0..3)
  gauntletBest: number;
  tutorialsDone: string[];
  settings: {
    stickMode: 'dynamic' | 'fixed';
    swapHands: boolean;
    vibration: boolean;
    audioVolume: number;
    reduceFlash: boolean;
    highContrast: boolean;
    pixelStyle: PixelStyle;
    debug: boolean;
  };
}

export function defaultSave(): SaveData {
  return {
    version: 1,
    coins: 30,
    unlockedWeapons: ['dagger'],
    equippedWeapon: 'dagger',
    unlockedArmor: ['none'],
    equippedArmor: 'none',
    campaign: {},
    gauntletBest: 0,
    tutorialsDone: [],
    settings: {
      stickMode: 'dynamic', swapHands: false, vibration: true, audioVolume: 0.5,
      reduceFlash: false, highContrast: false, pixelStyle: 'detailed', debug: false,
    },
  };
}

export function loadSave(): SaveData {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return defaultSave();
    const data = JSON.parse(raw) as SaveData;
    if (data.version !== 1) return migrate(data);
    // older saves may predate newer settings keys — fill gaps with defaults
    return hydrateSave(data);
  } catch {
    // attempt backup recovery
    try {
      const bak = localStorage.getItem(BACKUP_KEY);
      if (bak) return hydrateSave(JSON.parse(bak));
    } catch { /* fall through */ }
    return defaultSave();
  }
}

function hydrateSave(data: Partial<SaveData>): SaveData {
  const d = defaultSave();
  const hydrated = { ...d, ...data, settings: { ...d.settings, ...(data.settings ?? {}) } } as SaveData;
  if (!hydrated.unlockedWeapons.includes(hydrated.equippedWeapon)) hydrated.equippedWeapon = 'dagger';
  hydrated.settings.pixelStyle = normalizePixelStyle(hydrated.settings.pixelStyle);
  return hydrated;
}

export function normalizePixelStyle(value: unknown): PixelStyle {
  return value === 'coarse' ? 'coarse' : 'detailed';
}

function migrate(_old: any): SaveData {
  // future schema versions migrate here; keep old data where possible
  return defaultSave();
}

export function persistSave(d: SaveData): void {
  try {
    const prev = localStorage.getItem(KEY);
    if (prev) localStorage.setItem(BACKUP_KEY, prev);
    localStorage.setItem(KEY, JSON.stringify(d));
  } catch { /* storage may be unavailable (private mode); game continues in-memory */ }
}

export function sealsFor(d: SaveData, realm: string, index: number): number {
  return d.campaign?.[realm]?.[index] ?? -1; // -1 = not completed
}

export function nextEncounterIndex(d: SaveData, realm: string): number {
  const rec = d.campaign?.[realm] ?? {};
  let i = 1;
  while ((rec[i] ?? -1) >= 0) i++;
  return i;
}
