import type { SaveData } from './Save';

export type ArmorId = 'none' | 'padded' | 'mail' | 'plate';

export interface ArmorDef {
  id: ArmorId;
  name: string;
  material: 'flesh' | 'padded' | 'mail' | 'plate';
  mass: number;
  price: number;
  description: string;
}

export const ARMOR: Record<ArmorId, ArmorDef> = {
  none: {
    id: 'none', name: 'UNARMORED', material: 'flesh', mass: 0, price: 0,
    description: 'Fast and exposed',
  },
  padded: {
    id: 'padded', name: 'PADDED JACK', material: 'padded', mass: 2.2, price: 45,
    description: 'Light impact protection',
  },
  mail: {
    id: 'mail', name: 'RIVETED MAIL', material: 'mail', mass: 4.3, price: 120,
    description: 'Strong against cuts',
  },
  plate: {
    id: 'plate', name: 'IRON PLATE', material: 'plate', mass: 6.8, price: 260,
    description: 'Maximum protection, low stamina',
  },
};

export const ARMOR_ORDER: ArmorId[] = ['none', 'padded', 'mail', 'plate'];

export function armorById(id: string | undefined): ArmorDef {
  return ARMOR[id as ArmorId] ?? ARMOR.none;
}

export type ArmorPurchaseResult = 'bought' | 'owned' | 'insufficient' | 'unknown';

export function buyArmor(save: SaveData, id: string): ArmorPurchaseResult {
  const def = ARMOR[id as ArmorId];
  if (!def) return 'unknown';
  if (save.unlockedArmor.includes(def.id)) return 'owned';
  if (save.coins < def.price) return 'insufficient';
  save.coins -= def.price;
  save.unlockedArmor.push(def.id);
  return 'bought';
}

export function equipArmor(save: SaveData, id: string): boolean {
  const def = ARMOR[id as ArmorId];
  if (!def || !save.unlockedArmor.includes(def.id)) return false;
  save.equippedArmor = def.id;
  return true;
}
