// Entry: size stage, boot game, wire hotkeys, run autotest when requested.
import { Game } from './core/Game';
import { Assets } from './render/Assets';
import { runAutoTest } from './test/AutoTest';

const pageParams = new URLSearchParams(location.search);
if (pageParams.get('touchpreview') === '1') document.body.classList.add('touchPreview');
const telemetryErrorHandler = (event: ErrorEvent): void => {
  document.documentElement.dataset.runtimeError = `${event.message}\n${event.error?.stack ?? ''}`;
};
const telemetryRejectionHandler = (event: PromiseRejectionEvent): void => {
  const reason = event.reason;
  document.documentElement.dataset.runtimeError = `Unhandled rejection: ${reason?.stack ?? reason}`;
};
if (pageParams.get('telemetry') === '1') {
  window.addEventListener('error', telemetryErrorHandler);
  window.addEventListener('unhandledrejection', telemetryRejectionHandler);
}

function fitStage(): void {
  const stage = document.getElementById('stage')!;
  const canvas = document.getElementById('game') as HTMLCanvasElement;
  const W = 960, H = 540;
  // retina-aware backing store: logical 960x540 * devicePixelRatio, clamped to
  // [1,2] — below 1 (e.g. 80% browser zoom) the renderer's own dpr floor of 1
  // would paint past the backing store; above 2 just costs fill rate
  const dpr = Math.min(Math.max(window.devicePixelRatio || 1, 1), 2);
  const bw = Math.round(W * dpr), bh = Math.round(H * dpr);
  if (canvas.width !== bw) canvas.width = bw;
  if (canvas.height !== bh) canvas.height = bh;
  const scale = Math.min(window.innerWidth / W, window.innerHeight / H);
  canvas.style.width = `${Math.floor(W * scale)}px`;
  canvas.style.height = `${Math.floor(H * scale)}px`;
  stage.style.width = canvas.style.width;
  stage.style.height = canvas.style.height;
}

const handleOrientationChange = (): void => { setTimeout(fitStage, 120); };
window.addEventListener('resize', fitStage);
window.addEventListener('orientationchange', handleOrientationChange);

const canvas = document.getElementById('game') as HTMLCanvasElement;
const previousGame = (window as any).__game as Game | undefined;
previousGame?.stop();
const game = new Game(canvas);
let disposed = false;
fitStage();
(game as any).fitStage = fitStage;

// bitmap art: load in parallel with boot; renderer falls back to greybox until ready
Assets.load(new URL('.', document.baseURI).toString()).then(assets => {
  if (disposed) return;
  game.renderer.assets = assets;
  (window as any).__assets = assets;
  if (!assets.ready) console.warn('[assets] bitmap art unavailable — greybox fallback active');
});

game.start();
if (pageParams.get('fighting-rebuild') === '1') {
  game.startFightingSandbox(pageParams.get('weapon') ?? 'sword');
}

// debug toggle: F1 or backquote or `g`
const handleDebugKey = (e: KeyboardEvent): void => {
  if (e.key === 'F1' || e.key === '`' || e.key.toLowerCase() === 'g') {
    e.preventDefault();
    game.renderer.debug = !game.renderer.debug;
  }
};
window.addEventListener('keydown', handleDebugKey);

// pause on background
const handleVisibilityChange = (): void => { game.paused = document.hidden; };
document.addEventListener('visibilitychange', handleVisibilityChange);

// expose for console-driven verification
(window as any).__game = game;

// autotest mode
if (pageParams.get('autotest') === '1') {
  const log = document.getElementById('testlog')!;
  log.classList.remove('hidden');
  document.getElementById('home')!.classList.add('hidden');
  runAutoTest(game, line => { log.textContent += line + '\n'; });
}

interface ViteHotContext {
  dispose(callback: () => void): void;
}

const hot = (import.meta as ImportMeta & { hot?: ViteHotContext }).hot;
if (hot) {
  hot.dispose(() => {
    disposed = true;
    game.stop();
    window.removeEventListener('resize', fitStage);
    window.removeEventListener('orientationchange', handleOrientationChange);
    window.removeEventListener('keydown', handleDebugKey);
    window.removeEventListener('error', telemetryErrorHandler);
    window.removeEventListener('unhandledrejection', telemetryRejectionHandler);
    document.removeEventListener('visibilitychange', handleVisibilityChange);
    if ((window as any).__game === game) delete (window as any).__game;
  });
}
