// Weapon definitions + weapon rigid-body construction.
// A weapon is its own dynamic body attached to a hand via a motor-driven revolute grip.
// Local axes: +x runs from grip toward the tip. Grip point is at local x=0.
// Damage surfaces are separate fixtures with userData consumed by Damage.ts.
import { Body, Box, Circle, RevoluteJoint, Vec2, World } from 'planck';
import { CFG } from '../config';

export interface WeaponDef {
  id: string;
  name: string;
  kind: 'dagger' | 'sword' | 'mace' | 'axe' | 'spear' | 'flail';
  length: number;        // total meters, grip-to-tip plus pommel
  thickness: number;     // meters
  mass: number;          // kg
  bladeStart: number;    // where the damaging surface begins (m from grip)
  headRadius?: number;   // for mace: blunt head circle instead of edge
  twoHanded?: boolean;
  price: number;
  realm: string;
}

