// AI brain: drives a Fighter through the exact same FighterInput packet as the
// player. Utility state machine with reaction delay, noise, stamina discipline.
// DOM-free; usable from Node tests.
import { Vec2 } from 'planck';
import { CFG } from '../config';
import { FighterInput, IDLE_INPUT } from '../types';
import { Fighter } from '../physics/Fighter';

export interface AIDifficulty {
  reaction: number;     // seconds between decisions
  noise: number;        // target noise in meters
  aggression: number;   // 0..1 probability to attack when in range
  discipline: number;   // 0..1 how strictly stamina floor is respected
}

export const AI_TIERS: Record<string, AIDifficulty> = {
  novice:   { reaction: 0.5,  noise: 0.16, aggression: 0.4, discipline: 0.3 },
  regular:  { reaction: 0.32, noise: 0.09, aggression: 0.6, discipline: 0.6 },
  veteran:  { reaction: 0.22, noise: 0.05, aggression: 0.75, discipline: 0.85 },
  boss:     { reaction: 0.15, noise: 0.02, aggression: 0.9, discipline: 0.95 },
};

type Mode = 'guard' | 'advance' | 'retreat' | 'windup' | 'strike' | 'recover' | 'rest';
export type AIAttackKind = 'thrust' | 'overhead' | 'sweep' | 'orbit';

export function attackKindForWeapon(weaponKind: string | undefined, roll: number): AIAttackKind {
  const r = Math.max(0, Math.min(0.999999, roll));
  if (weaponKind === 'flail') return 'orbit';
  if (weaponKind === 'mace') return r < 0.55 ? 'overhead' : 'sweep';
  if (weaponKind === 'sword') return r < 0.04 ? 'thrust' : r < 0.42 ? 'overhead' : 'sweep';
  return r < 0.50 ? 'thrust' : r < 0.76 ? 'overhead' : 'sweep';
}

export interface AIDiagnostics {
  mode: Mode;
  attackKind: AIAttackKind;
  distance: number;
  engageInner: number;
  engageOuter: number;
  movementCooldown: number;
}

export class AIBrain {
  diff: AIDifficulty;
  private mode: Mode = 'guard';
  private modeTimer = 0;
  private modeDuration = 0;
  private decisionTimer = 0;
  private strikeTarget: Vec2 | null = null;
  private strikeKind: AIAttackKind = 'thrust';
  private orbitDirection: -1 | 1 = 1;
  private rngState: number;
  private movementCooldown = 0;
  private lastDistance = 0;
  private engageInner = 0.58;
  private engageOuter = 0.90;

  constructor(tier: keyof typeof AI_TIERS = 'regular', seed = 1337) {
    this.diff = AI_TIERS[tier];
    this.rngState = seed >>> 0;
  }

  private rand(): number {
    // mulberry32
    this.rngState = (this.rngState + 0x6D2B79F5) >>> 0;
    let t = this.rngState;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  private noise(): number {
    return (this.rand() * 2 - 1) * this.diff.noise;
  }

  private setMode(m: Mode, duration: number): void {
    if (this.mode !== m) { this.mode = m; }
    this.modeTimer = duration;
    this.modeDuration = duration;
  }

  private modeProgress(): number {
    if (this.modeDuration <= 0) return 1;
    return Math.max(0, Math.min(1, 1 - this.modeTimer / this.modeDuration));
  }

  /** Per-tick update; fills `out` with hand targets / step commands. */
  update(dt: number, self: Fighter, foe: Fighter, out: FighterInput): void {
    out.left = null; out.right = null; out.step = 0; out.move = 0; out.brace = false;
    if (self.dead || foe.dead) return;
    if (self.stamina.collapsed) { this.setMode('rest', 0.4); return; }

    // Use a hysteresis band rather than one threshold. The old single reach
    // value made the AI sprint into contact, stop abruptly, then oscillate
    // between advance and retreat as articulated bodies separated by pixels.
    const weaponLength = self.weapon?.def.length ?? 0.5;
    const engageOuter = Math.max(0.76, Math.min(1.02, weaponLength + 0.23));
    const engageInner = Math.max(0.50, engageOuter - 0.32);
    const myX = self.pelvis().getPosition().x;
    const foeX = foe.pelvis().getPosition().x;
    const dist = Math.abs(foeX - myX);
    this.lastDistance = dist;
    this.engageInner = engageInner;
    this.engageOuter = engageOuter;
    self.faceToward(foeX);
    const f = self.facing;

    this.decisionTimer -= dt;
    this.modeTimer -= dt;
    this.movementCooldown = Math.max(0, this.movementCooldown - dt);

    const foeHead = foe.headBody().getPosition();
    const foeTorso = foe.torso().getPosition();

    const tired = self.stamina.fraction() < (CFG.ai.staminaFloor / 100);

    const canChooseMode = this.mode === 'guard' || this.mode === 'advance' ||
      this.mode === 'retreat' || this.mode === 'rest';
    if (this.decisionTimer <= 0 && canChooseMode) {
      this.decisionTimer = this.diff.reaction * (0.7 + this.rand() * 0.6);
      if (tired && this.rand() < this.diff.discipline) {
        this.setMode('rest', 0.9);
      } else if (dist > engageOuter + 0.08) {
        this.setMode('advance', 0.5);
      } else if (dist < engageInner && this.rand() < 0.65) {
        this.setMode('retreat', 0.4);
      } else if (this.rand() < this.diff.aggression) {
        // choose an attack pattern
        const r = this.rand();
        this.strikeKind = attackKindForWeapon(self.weapon?.def.kind, r);
        if (this.strikeKind === 'orbit') this.orbitDirection = this.rand() < 0.5 ? -1 : 1;
        this.setMode('windup', this.strikeKind === 'orbit' ? 0.42 :
          this.strikeKind === 'overhead' ? 0.30 : this.strikeKind === 'sweep' ? 0.26 : 0.22);
        const aim = this.rand() < 0.6 ? foeHead : foeTorso;
        this.strikeTarget = Vec2(aim.x + this.noise(), aim.y + this.noise());
      }
    }

    const shoulderR = self.shoulderWorld('R');
    const shoulderL = self.shoulderWorld('L');

    switch (this.mode) {
      case 'rest': {
        out.right = null;
        out.left = null;
        if (dist < engageInner) this.commandStep(out, -f, 0.58, self);
        if (!tired && this.modeTimer <= 0) this.setMode('guard', 0.3);
        break;
      }
      case 'advance': {
        this.guardPose(out, shoulderR, shoulderL, f, foe);
        if (dist <= engageOuter) this.setMode('guard', 0.2);
        // Hold the direction through the physical gait state machine. A
        // one-frame cadence pulse could arrive during the final plant and be
        // discarded, leaving the AI idle at long range indefinitely.
        else out.move = f;
        break;
      }
      case 'retreat': {
        this.guardPose(out, shoulderR, shoulderL, f, foe);
        if (this.modeTimer <= 0) this.setMode('guard', 0.3);
        else this.commandStep(out, -f, 0.56, self);
        break;
      }
      case 'guard': {
        this.guardPose(out, shoulderR, shoulderL, f, foe);
        break;
      }
      case 'windup': {
        // Keep thrusts axial and make only genuine cuts use a rear windup.
        // The former universal back/up pose sent every rigid weapon around a
        // large arc before contact and read as uncontrolled dagger spinning.
        if (this.strikeKind === 'orbit') {
          const angle = this.orbitDirection * this.modeProgress() * Math.PI;
          out.right = self.stickToWorld('R', Vec2(f * Math.cos(angle), Math.sin(angle)));
        } else if (this.strikeKind === 'thrust') {
          out.right = Vec2(shoulderR.x + 0.18 * f, shoulderR.y - 0.05);
        } else if (this.strikeKind === 'overhead') {
          out.right = Vec2(shoulderR.x + 0.10 * f + this.noise(), shoulderR.y + 0.52 + this.noise());
        } else {
          out.right = Vec2(shoulderR.x - 0.30 * f + this.noise(), shoulderR.y + 0.24 + this.noise());
        }
        out.left = Vec2(shoulderL.x + 0.18 * f, shoulderL.y - 0.15);
        out.brace = true;
        if (this.modeTimer <= 0) this.setMode('strike', this.strikeKind === 'orbit' ? 0.68 : 0.30);
        break;
      }
      case 'strike': {
        const t = this.strikeTarget ?? foeTorso;
        // aim PAST the target: overpenetration keeps the hand accelerating and
        // lets the blade whip through via grip compliance + inertia
        if (this.strikeKind === 'orbit') {
          const angle = this.orbitDirection * (Math.PI + this.modeProgress() * Math.PI);
          out.right = self.stickToWorld('R', Vec2(f * Math.cos(angle), Math.sin(angle)));
        } else if (this.strikeKind === 'overhead') {
          out.right = Vec2(t.x + 0.2 * f + this.noise(), t.y - 0.45);
        } else if (this.strikeKind === 'sweep') {
          out.right = Vec2(t.x + 0.35 * f, t.y + 0.1 * (this.rand() - 0.5) * 2);
        } else {
          out.right = Vec2(t.x + 0.3 * f, t.y);
        }
        out.left = Vec2(shoulderL.x + 0.2 * f, shoulderL.y - 0.12);
        out.brace = true;
        if (this.modeTimer <= 0) this.setMode('recover', 0.34);
        break;
      }
      case 'recover': {
        this.guardPose(out, shoulderR, shoulderL, f, foe);
        if (this.modeTimer <= 0) this.setMode('guard', 0.2);
        break;
      }
    }
  }

  /** Pulse one complete physical footfall. Continuous held movement made the
   * AI chain full-length 0.38 s strides into a 1.4 m/s sprint and read as
   * skating. A deliberate plant interval leaves both feet visibly loaded. */
  private commandStep(out: FighterInput, direction: number, cadence: number, self: Fighter): void {
    // Only spend the one-frame cadence pulse once the gait controller can
    // accept it. Mid-stride pulses used to be discarded and left the AI
    // visibly frozen at combat distance until a later decision cycle.
    if (this.movementCooldown > 0 || self.gaitDiagnostics().phase !== 'idle') return;
    out.step = Math.sign(direction) as -1 | 1;
    this.movementCooldown = cadence;
  }

  diagnostics(): AIDiagnostics {
    return {
      mode: this.mode,
      attackKind: this.strikeKind,
      distance: this.lastDistance,
      engageInner: this.engageInner,
      engageOuter: this.engageOuter,
      movementCooldown: this.movementCooldown,
    };
  }

  private guardPose(out: FighterInput, shoulderR: Vec2, shoulderL: Vec2, f: number, foe: Fighter): void {
    // Neutral guard is owned by Fighter's zero-input posture controller.
    // Explicit targets here used to drain stamina and disable idle balance on
    // every frame, so the AI collapsed before it could complete an attack.
    out.right = null;
    out.left = null;
    void shoulderR; void shoulderL; void f; void foe;
  }
}

export function idleInput(): FighterInput {
  return { ...IDLE_INPUT };
}
