import { World } from 'planck';
import { CFG } from '../config';
import { IDLE_INPUT } from '../types';
import { Fighter } from './Fighter';

/** Resolve the initial articulated pose before the countdown becomes visible.
 * This removes construction-time settling while preserving normal collisions
 * and knockback after control unlocks. */
export function settleFightersForSpawn(
  world: World,
  fighters: Fighter[],
  seconds = CFG.round.spawnSettleSec,
): void {
  const substep = CFG.physics.dt / CFG.physics.substeps;
  const steps = Math.ceil(seconds / substep);
  for (let step = 0; step < steps; step++) {
    for (const fighter of fighters) fighter.update(substep, IDLE_INPUT);
    world.step(substep, CFG.physics.velocityIterations, CFG.physics.positionIterations);
    for (const fighter of fighters) fighter.postStep();
  }
  for (const fighter of fighters) fighter.prepareVisibleSpawn();
}
