// First-run interactive tutorial (training hall): staged prompts that advance
// only when the player actually performs each action. Done state persists via
// save.tutorialsDone — the Game owns persistence, this class is pure UI state.
import { FighterInput } from '../types';

interface Step {
  text: string;
  hold: number; // seconds the condition must hold before advancing
  latch?: boolean; // once observed true, stays true (for one-frame impulses)
  ok(inp: FighterInput, damageEvents: any[]): boolean;
}

const STEPS: Step[] = [
  { text: 'OFF HAND — W A S D · left touch stick', hold: 0.5, ok: inp => !!inp.left },
  { text: 'SWORD — HOLD + DRAG MOUSE · arrows · right touch stick', hold: 0.5, ok: inp => !!inp.right },
  { text: 'WALK — HOLD SPACE FORWARD · TAP SPACE BACK', hold: 0.12, latch: true, ok: inp => Math.abs(inp.move ?? 0) > 0 || inp.step !== 0 },
  { text: 'NOW STRIKE THE DUMMY!', hold: 0.05, ok: (_inp, evts) => evts.some(e => e.attackerId === 0) },
];

const SKIP = '   ·   ESC = SKIP';
const FAREWELL = 'WELL STRUCK — THE HALL IS YOURS';
const FAREWELL_SEC = 3;

export class Tutorial {
  active = false;
  private index = 0;
  private hold = 0;
  private latched = false;
  private farewellT = 0;
  private finished = false; // one-shot flag consumed by the Game for persistence

  reset(active: boolean): void {
    this.active = active;
    this.index = 0;
    this.hold = 0;
    this.latched = false;
    this.farewellT = 0;
    this.finished = false;
  }

  skip(): void {
    if (this.active) this.finished = true; // skipping also counts as seen
    this.active = false;
  }

  consumeFinished(): boolean {
    const f = this.finished;
    this.finished = false;
    return f;
  }

  /** Prompt to show this frame, or null to hide. */
  update(dt: number, inp: FighterInput, damageEvents: any[]): string | null {
    if (!this.active) return null;
    if (this.index >= STEPS.length) {
      this.farewellT -= dt;
      if (this.farewellT <= 0) { this.active = false; return null; }
      return FAREWELL;
    }
    const s = STEPS[this.index];
    if (s.latch && s.ok(inp, damageEvents)) this.latched = true;
    const ok = s.latch ? this.latched : s.ok(inp, damageEvents);
    this.hold = ok ? this.hold + dt : 0;
    if (this.hold >= s.hold) {
      this.index++;
      this.hold = 0;
      this.latched = false;
      if (this.index >= STEPS.length) { this.farewellT = FAREWELL_SEC; this.finished = true; return FAREWELL; }
    }
    return STEPS[this.index].text + SKIP;
  }
}
