// Fighter: an active ragdoll built from articulated rigid bodies, revolute
// position-to-velocity motors, PD force hand control, physical stepping, stamina,
// localized injury and weapon grip. DOM-free (usable from Node tests).
import { Body, Box, Circle, Polygon, RevoluteJoint, Vec2, WeldJoint, WheelJoint, World } from 'planck';
import { CFG, MotorTuning } from '../config';
import { BodyProportions, DEFAULT_PROPORTIONS, DamageType, EnemyAppearanceId, Facing, FighterInput, IDLE_INPUT, PartName } from '../types';
import { Stamina } from './Stamina';
import { createWeapon, tipSpeed, updateGrip, weaponControlSpeedScale, WeaponDef, WeaponInstance, WEAPONS } from './Weapons';
import { createShield, shieldControlSpeedScale, ShieldInstance, updateShield } from './Shield';
import { combatStyleForWeapon, CombatStyleId, COMBAT_STYLES, normalizeCombatStyle, resolveCombatAim } from '../combat/CombatStyles';
import { normalizeShieldStyle, SHIELD_STYLES, ShieldStyleId } from '../combat/ShieldStyles';
import { gaitArmJointOffsets, gaitPose, gaitTrunkTargets, HEEL_STRIKE_PHASE, smootherstep, TOE_OFF_PHASE, velocityAwareStepLength } from './Gait';
import { clampTargetXToReach, solveTwoBoneIK } from './LegIK';
import { hitReactionProfile, HitReactionProfile } from './HitReaction';

interface PartData {
  name: PartName;
  body: Body;
  tissue: number;
  tissueMax: number;
  bone: number;      // 100 = intact
  bleeding: number;  // 0..100 accumulated bleed-out
  motorMult: number; // injury-driven torque multiplier for attached joints
}

interface JointRec {
  name: string;
  joint: RevoluteJoint;
  tuning: MotorTuning;
  stanceTarget: number;      // radians, facing-mirrored at build time
  currentTarget: number;
  attachedPart: PartName;    // injury of this part weakens the joint
  gaitRole: 'none' | 'lead' | 'trail';
}

export interface FootPlantEvent {
  side: 'L' | 'R';
  x: number;
  intensity: number;
}

const PART_MASS: Record<PartName, number> = {
  pelvis: 11, torso: 19, head: 4.5,
  upperArmL: 1.7, forearmL: 1.3, handL: 0.5,
  upperArmR: 1.7, forearmR: 1.3, handR: 0.5,
  thighL: 6.5, shinL: 3.2, footL: 0.9,
  thighR: 6.5, shinR: 3.2, footR: 0.9,
};

const PART_TISSUE: Record<PartName, number> = {
  pelvis: 70, torso: 90, head: 32,
  upperArmL: 34, forearmL: 28, handL: 18,
  upperArmR: 34, forearmR: 28, handR: 18,
  thighL: 46, shinL: 36, footL: 20,
  thighR: 46, shinR: 36, footR: 20,
};

export const HEAD_RADIUS = 0.125;

export class Fighter {
  world: World;
  id: number;
  facing: Facing;
  label: string;
  props: BodyProportions;
  parts = new Map<PartName, PartData>();
  joints: JointRec[] = [];
  stamina: Stamina;
  weapon: WeaponInstance | null = null;
  shield: ShieldInstance | null = null;
  lastInput: FighterInput = { left: null, right: null, step: 0 };
  dead = false;
  deathReason = '';
  bloodPool = 100;
  poseTargetsLocked = false; // true while dead — motors released
  // stepping
  private stepTimer = 0;
  private stepCooldown = 0;
  private stepDir: -1 | 0 | 1 = 0;
  private stepPhase: 'idle' | 'lift' | 'plant' | 'recover' = 'idle';
  private continuousStep = false;
  private stepEntryVelocityX = 0;
  private footAnchorX: Record<'L' | 'R', number> = { L: 0, R: 0 };
  private supportSide: 'L' | 'R' = 'L';
  private swingSide: 'L' | 'R' = 'R';
  private lastStepDir: -1 | 0 | 1 = 0;
  private swingStartX = 0;
  private swingTargetX = 0;
  private supportAnchorX = 0;
  private footGround!: Body;
  private footRail: Record<'L' | 'R', WheelJoint | null> = { L: null, R: null };
  private footRailPivot: Record<'L' | 'R', 'center' | 'heel' | 'toe'> = { L: 'center', R: 'center' };
  private shapedHandTarget: Record<'L' | 'R', Vec2 | null> = { L: null, R: null };
  private shapedHandAngle: Record<'L' | 'R', number | null> = { L: null, R: null };
  private weaponAimAngle: number | null = null;
  private weaponPointerAngle: number | null = null;
  private weaponAimVelocity = 0;
  private weaponAimVelocityHold = 0;
  private weaponGripLocked = false;
  private weaponHasControlHistory = false;
  private weaponGestureId = -1;
  private weaponGestureBaseAngle = 0;
  private weaponPointerSampleAge = 0;
  private weaponGestureTravel = 0;
  private weaponFollowThroughTarget: number | null = null;
  private weaponFollowThroughTimer = 0;
  private weaponControlWasActive = false;
  private weaponMomentumPrimed = false;
  private combatReplant = false;
  private combatReplantTimer = 0.80;
  private combatReplantNextSide: 'L' | 'R' = 'R';
  private combatStanceCenterX: number | null = null;
  private activeGaitPose = gaitPose(0, 1, 0);
  private pelvisStepTargetX = 0;
  private pelvisTargetVelocityX = 0;
  private pelvisPathStartX = 0;
  private pelvisPathEndX = 0;
  private settlingGait = false;
  private brakingForReversal = false;
  private reversalRecoveryTimer = 0;
  private needsClosingStep = false;
  private moveWasHeld = false;
  private blockedMoveDir: -1 | 0 | 1 = 0;
  private settlePelvisX = 0;
  private poseRecoveryTimer = 0;
  private poseRecoveryStart = new Map<string, number>();
  private gaitArmBlend = 0;
  private externalContactTimer = 0;
  private shieldShoveCooldown = 0;
  private shieldShoveCount = 0;
  private lastShieldShoveImpulse = 0;
  private pendingFootPlants: FootPlantEvent[] = [];
  private activeSwingIKTarget: Vec2 | null = null;
  private activeSwingIKRequested: Vec2 | null = null;
  private activeSwingIKBlend = 0;
  private activeSwingIKDebug: Record<string, number> | null = null;
  private age = 0;
  // diagnostics
  lastHandForce = 0;
  lastTipSpeed = 0;
  shoulderOffsetX: number;
  armorMaterial = 'flesh'; // greybox baseline; armor pieces map onto parts later
  tint: number;
  visualVariant: EnemyAppearanceId | null;
  locomotionRate: number;
  combatStyle: CombatStyleId;
  shieldStyle: ShieldStyleId;

  constructor(
    world: World, opts: {
      id: number; x: number; facing: Facing; label: string;
      proportions?: BodyProportions; equipmentMassKg?: number; tint?: number;
      visualVariant?: EnemyAppearanceId | null; locomotionRate?: number;
      combatStyle?: CombatStyleId;
      shieldStyle?: ShieldStyleId;
    },
  ) {
    this.world = world;
    this.id = opts.id;
    this.facing = opts.facing;
    this.label = opts.label;
    this.props = opts.proportions ?? { ...DEFAULT_PROPORTIONS };
    this.tint = opts.tint ?? 0;
    this.visualVariant = opts.visualVariant ?? null;
    this.locomotionRate = Math.max(0.65, Math.min(1.15, opts.locomotionRate ?? 1));
    this.combatStyle = normalizeCombatStyle(opts.combatStyle);
    this.shieldStyle = normalizeShieldStyle(opts.shieldStyle);
    this.shoulderOffsetX = 0.185 * this.props.shoulder;
    this.stamina = new Stamina(opts.equipmentMassKg ?? 1.2);
    this.buildRig(opts.x);
    this.pelvisStepTargetX = opts.x;
    this.pelvisPathStartX = opts.x;
    this.pelvisPathEndX = opts.x;
    this.captureFootAnchors();
  }

  // ------------------------------------------------------------------ rig
  private mk(name: PartName, cx: number, cy: number, hw: number, hh: number, group: number): Body {
    const mass = PART_MASS[name] * this.props.mass;
    const hwM = hw * (name.includes('thigh') || name.includes('shin') ? this.props.legs : 1);
    const body = this.world.createBody({ type: 'dynamic', position: Vec2(cx, cy) });
    const area = 4 * hwM * hh;
    body.createFixture({
      shape: Box(hwM, hh), density: mass / area, friction: 0.95, restitution: 0.0,
      filterGroupIndex: group,
      userData: { kind: 'part', fighterId: this.id, part: name },
    });
    this.applyDamping(body, name);
    return body;
  }

  /** A beveled physical sole gives the ankle a real heel and toe edge to roll
   * over. A rectangular fixture stays flat under support load until enough
   * torque lifts half the body, so its correct rocker target remained visual
   * fiction. */
  private mkFoot(name: 'footL' | 'footR', cx: number, cy: number, group: number): Body {
    const hw = 0.105;
    const hh = 0.035;
    const bevel = 0.028;
    const mass = PART_MASS[name] * this.props.mass;
    const shape = Polygon([
      Vec2(-hw, -hh + bevel),
      Vec2(-hw + bevel, -hh),
      Vec2(hw - bevel, -hh),
      Vec2(hw, -hh + bevel),
      Vec2(hw, hh),
      Vec2(-hw, hh),
    ]);
    const area = 4 * hw * hh - bevel * bevel;
    const body = this.world.createBody({ type: 'dynamic', position: Vec2(cx, cy) });
    body.createFixture({
      shape, density: mass / area, friction: 1.10, restitution: 0,
      filterGroupIndex: group,
      userData: { kind: 'part', fighterId: this.id, part: name },
    });
    this.applyDamping(body, name);
    return body;
  }

  private applyDamping(b: Body, name: PartName): void {
    const d = CFG.fighter.damping;
    const limb = name !== 'pelvis' && name !== 'torso';
    b.setAngularDamping(limb ? d.limbAngular : d.torsoAngular);
    b.setLinearDamping(limb ? d.limbLinear : d.torsoLinear);
    if (name === 'handL' || name === 'handR') (b as any).setBullet?.(true);
  }

  private addJoint(
    name: string, a: Body, b: Body, x: number, y: number,
    tuning: MotorTuning, stanceTarget: number, attachedPart: PartName,
    limits: [number, number] | null, gaitRole: 'none' | 'lead' | 'trail' = 'none',
  ): void {
    const j = this.world.createJoint(RevoluteJoint({
      enableMotor: true, motorSpeed: 0, maxMotorTorque: tuning.maxTorque,
      enableLimit: !!limits,
      lowerAngle: limits?.[0] ?? 0,
      upperAngle: limits?.[1] ?? 0,
    }, a, b, Vec2(x, y))) as RevoluteJoint;
    this.joints.push({
      name, joint: j, tuning, stanceTarget, currentTarget: stanceTarget, attachedPart, gaitRole,
    });
  }

  private buildRig(x0: number): void {
    const f = this.facing;
    const g = -1 - this.id; // negative collision group: own parts never self-collide
    const H = this.props.height;

    // legs
    // Feet start directly below their shins. The former extra two-centimetre
    // outward offset made both ankles look dislocated even though the joint
    // constraint itself was intact.
    const footL = this.mkFoot('footL', x0 - 0.07 * f, 0.045, g);
    const footR = this.mkFoot('footR', x0 + 0.07 * f, 0.045, g);
    this.footGround = this.world.createBody();
    const shinL = this.mk('shinL', x0 - 0.07 * f, 0.30, 0.045, 0.20, g);
    const shinR = this.mk('shinR', x0 + 0.07 * f, 0.30, 0.045, 0.20, g);
    const thighL = this.mk('thighL', x0 - 0.075 * f, 0.71, 0.055, 0.21, g);
    const thighR = this.mk('thighR', x0 + 0.075 * f, 0.71, 0.055, 0.21, g);
    const pelvis = this.mk('pelvis', x0, 1.01, 0.135 * this.props.hip, 0.09, g);
    const torso = this.mk('torso', x0, 1.35, 0.16 * this.props.torso, 0.25, g);
    // The head circle now meets the torso at the physical neck anchor instead
    // of floating 1.5 cm above its fixture before sprite overscan hid the gap.
    const headB = this.world.createBody({ type: 'dynamic', position: Vec2(x0, 1.60 + HEAD_RADIUS) });
    headB.createFixture({
      shape: Circle(HEAD_RADIUS), density: PART_MASS.head / (Math.PI * HEAD_RADIUS * HEAD_RADIUS) * this.props.mass,
      friction: 0.5, restitution: 0.0, filterGroupIndex: g,
      userData: { kind: 'part', fighterId: this.id, part: 'head' },
    });
    headB.setAngularDamping(CFG.fighter.damping.torsoAngular);
    headB.setLinearDamping(CFG.fighter.damping.torsoLinear);

    // arms (right arm = weapon side, built slightly forward)
    const uaL = this.mk('upperArmL', x0 - this.shoulderOffsetX - 0.015 * f, 1.3775, 0.042, 0.1425, g);
    const faL = this.mk('forearmL', x0 - this.shoulderOffsetX - 0.025 * f, 1.10, 0.036, 0.135, g);
    const haL = this.mk('handL', x0 - this.shoulderOffsetX - 0.03 * f, 0.915, 0.05, 0.05, g);
    const uaR = this.mk('upperArmR', x0 + this.shoulderOffsetX + 0.015 * f, 1.3775, 0.042, 0.1425, g);
    const faR = this.mk('forearmR', x0 + this.shoulderOffsetX + 0.025 * f, 1.10, 0.036, 0.135, g);
    const haR = this.mk('handR', x0 + this.shoulderOffsetX + 0.03 * f, 0.915, 0.05, 0.05, g);

    // The wrist anchor is the shared edge of the forearm and hand fixtures.
    // Welding at the hand centre left a visible floating wrist even though the
    // two bodies were constrained together.
    this.world.createJoint(WeldJoint({}, faL, haL, Vec2(haL.getPosition().x, 0.965)));
    this.world.createJoint(WeldJoint({}, faR, haR, Vec2(haR.getPosition().x, 0.965)));

    const M = CFG.fighter.motors;
    this.addJoint('spine', pelvis, torso, x0, 1.10, M.spine, 0, 'pelvis', [-0.45, 0.45]);
    this.addJoint('neck', torso, headB, x0, 1.60, M.neck, 0, 'torso', [-0.4, 0.4]);
    this.addJoint('shoulderL', torso, uaL, torso.getPosition().x - this.shoulderOffsetX, 1.52,
      M.shoulder, 0.28 * f, 'upperArmL', null);
    this.addJoint('shoulderR', torso, uaR, torso.getPosition().x + this.shoulderOffsetX, 1.52,
      M.shoulder, 0.28 * f, 'upperArmR', null);
    // A small 5-degree extension allowance keeps impacts compliant without
    // letting the elbow bend backward into an inhuman silhouette.
    this.addJoint('elbowL', uaL, faL, uaL.getPosition().x, 1.235, M.elbow, 0.4 * f, 'forearmL', [-0.08, 2.65]);
    this.addJoint('elbowR', uaR, faR, uaR.getPosition().x, 1.235, M.elbow, 0.4 * f, 'forearmR', [-0.08, 2.65]);
    this.addJoint('hipL', pelvis, thighL, x0 - 0.075 * f, 0.92, M.hip, 0.05 * f, 'thighL', [-1.2, 1.6], 'trail');
    this.addJoint('hipR', pelvis, thighR, x0 + 0.075 * f, 0.92, M.hip, 0.05 * f, 'thighR', [-1.2, 1.6], 'lead');
    this.addJoint('kneeL', thighL, shinL, thighL.getPosition().x, 0.50, M.knee, -0.06 * f, 'shinL', [-2.4, 0.04], 'trail');
    this.addJoint('kneeR', thighR, shinR, thighR.getPosition().x, 0.50, M.knee, -0.06 * f, 'shinR', [-2.4, 0.04], 'lead');
    this.addJoint('ankleL', shinL, footL, shinL.getPosition().x, 0.10, M.ankle, 0.05 * f, 'footL', [-0.6, 0.6], 'trail');
    this.addJoint('ankleR', shinR, footR, shinR.getPosition().x, 0.10, M.ankle, 0.05 * f, 'footR', [-0.6, 0.6], 'lead');
    this.applyFacingJointLimits();

    // seed part health
    const bodies: [PartName, Body][] = [
      ['pelvis', pelvis], ['torso', torso], ['head', headB],
      ['upperArmL', uaL], ['forearmL', faL], ['handL', haL],
      ['upperArmR', uaR], ['forearmR', faR], ['handR', haR],
      ['thighL', thighL], ['shinL', shinL], ['footL', footL],
      ['thighR', thighR], ['shinR', shinR], ['footR', footR],
    ];
    for (const [n, b] of bodies) {
      this.parts.set(n, {
        name: n, body: b, tissue: PART_TISSUE[n], tissueMax: PART_TISSUE[n],
        bone: 100, bleeding: 0, motorMult: 1,
      });
    }
    this.attachFootRail('L');
    this.attachFootRail('R');
  }

  // ------------------------------------------------------------------ access
  part(n: PartName): PartData { return this.parts.get(n)!; }
  pelvis(): Body { return this.part('pelvis').body; }
  torso(): Body { return this.part('torso').body; }
  headBody(): Body { return this.part('head').body; }

  shoulderWorld(side: 'L' | 'R'): Vec2 {
    const s = this.joints.find(j => j.name === `shoulder${side}`)!;
    return s.joint.getAnchorA();
  }

  handWorld(side: 'L' | 'R'): Vec2 {
    return this.part(side === 'L' ? 'handL' : 'handR').body.getPosition();
  }

  /** World target from a normalized stick vector (screen space). */
  stickToWorld(side: 'L' | 'R', u: Vec2): Vec2 {
    const h = CFG.fighter.hand;
    const s = this.shoulderWorld(side);
    const magnitude = Math.max(0, Math.min(1, u.length()));
    const direction = magnitude > 0.0001 ? Vec2(u.x / magnitude, u.y / magnitude) : Vec2(this.facing, 0);
    const radius = 0.36 + magnitude * (h.reach - 0.36);
    return Vec2(
      s.x + direction.x * radius,
      s.y + direction.y * radius,
    );
  }

  /** Shield targets use independent horizontal and vertical axes. This keeps
   * WASD on a readable rectangular path; diagonal key combinations select the
   * corners instead of being normalized onto the old circular orbit. */
  shieldToWorld(u: Vec2): Vec2 {
    const s = this.shoulderWorld('L');
    const x = Math.max(-1, Math.min(1, u.x));
    const y = Math.max(-1, Math.min(1, u.y));
    const requestedForward = CFG.shield.controlNeutralForward + x * this.facing *
      CFG.shield.controlHorizontalTravel;
    const forward = Math.max(CFG.shield.controlMinForward,
      Math.min(CFG.shield.controlMaxForward, requestedForward));
    return Vec2(
      s.x + this.facing * forward,
      s.y + y * CFG.shield.controlVerticalTravel,
    );
  }

  vitality(): number {
    let cur = 0, max = 0;
    this.parts.forEach(p => { cur += Math.max(0, p.tissue); max += p.tissueMax; });
    return Math.min(cur / max, this.bloodPool / 100) * 100;
  }

  // ------------------------------------------------------------------ equip
  equipWeapon(defOrId: string | WeaponDef): WeaponInstance {
    this.dropWeapon();
    const def = typeof defOrId === 'string' ? WEAPONS[defOrId] : defOrId;
    this.combatStyle = combatStyleForWeapon(def.id);
    const hand = this.part('handR').body;
    this.weapon = createWeapon(this.world, def, hand, this.facing, -1 - this.id, this.id);
    this.weaponAimAngle = this.weapon.body.getAngle();
    this.weaponPointerAngle = null;
    this.weaponAimVelocity = 0;
    this.weaponAimVelocityHold = 0;
    this.weaponGripLocked = false;
    this.weaponHasControlHistory = false;
    this.weaponGestureId = -1;
    this.weaponPointerSampleAge = this.age;
    this.weaponGestureTravel = 0;
    this.weaponFollowThroughTarget = null;
    this.weaponFollowThroughTimer = 0;
    this.weaponControlWasActive = false;
    this.weaponMomentumPrimed = false;
    return this.weapon;
  }

  equipShield(): ShieldInstance {
    this.dropShield();
    const hand = this.part('handL').body;
    this.shield = createShield(this.world, hand, this.facing, -1 - this.id, this.id);
    return this.shield;
  }

  dropShield(): void {
    if (!this.shield) return;
    this.world.destroyJoint(this.shield.gripJoint);
    this.shield = null;
  }

  absorbBlock(energy: number, damageFactor: number): void {
    this.stamina.spend(energy * damageFactor * CFG.shield.blockStaminaPerJoule *
      SHIELD_STYLES[this.shieldStyle].blockStaminaScale);
  }

  dropWeapon(): void {
    if (!this.weapon) {
      this.weaponAimAngle = null;
      this.weaponPointerAngle = null;
      this.weaponAimVelocity = 0;
      this.weaponAimVelocityHold = 0;
      this.weaponGripLocked = false;
      this.weaponHasControlHistory = false;
      this.weaponGestureId = -1;
      this.weaponGestureTravel = 0;
      this.weaponFollowThroughTarget = null;
      this.weaponFollowThroughTimer = 0;
      this.weaponControlWasActive = false;
      this.weaponMomentumPrimed = false;
      return;
    }
    const w = this.weapon;
    // detach: destroying the grip joint leaves the weapon as debris
    if (w.gripJoint) this.world.destroyJoint(w.gripJoint);
    (w as any).gripJoint = null;
    this.weapon = null;
    this.weaponAimAngle = null;
    this.weaponPointerAngle = null;
    this.weaponAimVelocity = 0;
    this.weaponAimVelocityHold = 0;
    this.weaponGripLocked = false;
    this.weaponHasControlHistory = false;
    this.weaponGestureId = -1;
    this.weaponGestureTravel = 0;
    this.weaponFollowThroughTarget = null;
    this.weaponFollowThroughTimer = 0;
    this.weaponControlWasActive = false;
    this.weaponMomentumPrimed = false;
  }

  /** Finish the hidden spawn settle without carrying solver momentum into the
   * visible countdown. The fighter remains fully physical once play begins. */
  prepareVisibleSpawn(): void {
    this.stepPhase = 'idle';
    this.stepTimer = 0;
    this.stepCooldown = 0;
    this.stepDir = 0;
    this.pelvisTargetVelocityX = 0;
    this.settlingGait = false;
    this.brakingForReversal = false;
    this.reversalRecoveryTimer = 0;
    this.needsClosingStep = false;
    this.moveWasHeld = false;
    this.poseRecoveryTimer = 0;
    this.poseRecoveryStart.clear();
    this.shapedHandTarget.L = null;
    this.shapedHandTarget.R = null;
    this.lastInput = { ...IDLE_INPUT };
    this.lastHandForce = 0;
    this.lastTipSpeed = 0;
    const rootX = this.pelvis().getPosition().x;
    this.pelvisStepTargetX = rootX;
    this.pelvisPathStartX = rootX;
    this.pelvisPathEndX = rootX;
    this.settlePelvisX = rootX;
    this.captureFootAnchors();
    this.pendingFootPlants.length = 0;

    const bodies = [...this.parts.values()].map(part => part.body);
    if (this.weapon) {
      bodies.push(...this.weapon.bodies);
      this.weapon.maxTipSpeedSeen = 0;
    }
    if (this.shield) bodies.push(this.shield.body);
    for (const body of new Set(bodies)) {
      body.setLinearVelocity(Vec2(0, 0));
      body.setAngularVelocity(0);
    }
    this.stabilizeVisibleGuard();
  }

  /** The countdown is presentation, not combat. Keep one-handed rigid gear on
   * its exact neutral axes after every solver step so no spawn oscillation is
   * shown before controls unlock. Normal physical motion resumes at FIGHT. */
  stabilizeVisibleGuard(): void {
    // Countdown is a locked presentation pose. Translate the complete rig back
    // to its settled root instead of allowing asymmetric held gear to creep the
    // player inward before input is enabled.
    const rootDx = this.settlePelvisX - this.pelvis().getPosition().x;
    const guardBodies = [...this.parts.values()].map(part => part.body);
    if (this.weapon) guardBodies.push(...this.weapon.bodies);
    if (this.shield) guardBodies.push(this.shield.body);
    for (const body of new Set(guardBodies)) {
      const position = body.getPosition();
      body.setTransform(Vec2(position.x + rootDx, position.y), body.getAngle());
      const velocity = body.getLinearVelocity();
      body.setLinearVelocity(Vec2(0, velocity.y));
    }
    if (this.weapon) {
      const rigidEdged = this.weapon.def.kind === 'dagger' || this.weapon.def.kind === 'sword';
      if (rigidEdged) {
        const forward = this.facing > 0 ? 0 : Math.PI;
        this.weapon.body.setTransform(this.weapon.body.getPosition(), forward);
        this.weaponAimAngle = forward;
        this.weaponPointerAngle = null;
      }
      for (const body of this.weapon.bodies) {
        body.setLinearVelocity(Vec2(0, 0));
        body.setAngularVelocity(0);
      }
    }
    if (this.shield) {
      this.shield.body.setTransform(this.shield.body.getPosition(), 0);
      this.shield.body.setLinearVelocity(Vec2(0, 0));
      this.shield.body.setAngularVelocity(0);
    }
  }

  // ------------------------------------------------------------------ damage
  applyDamage(part: PartName, rawDamage: number, type: DamageType): number {
    if (this.dead) return 0;
    const p = this.part(part);
    const mat = (CFG.damage.material as any)[this.armorMaterial] ?? CFG.damage.material.flesh;
    const dmg = rawDamage * (mat as any)[type];
    p.tissue = Math.max(0, p.tissue - dmg);
    if (type === 'blunt') p.bone = Math.max(0, p.bone - dmg * CFG.damage.bluntBoneFactor);
    if (type === 'cut') p.bleeding = Math.min(100, p.bleeding + dmg * CFG.damage.cutBleedFactor * 10);
    this.bloodPool = Math.max(0, this.bloodPool - dmg * (type === 'cut' ? 0.55 : 0.3));

    // injury -> limb motor strength
    const tissueRatio = p.tissue / p.tissueMax;
    p.motorMult = Math.max(0.12, Math.min(1, tissueRatio / 0.5));
    if (p.bone < 35) p.motorMult = Math.min(p.motorMult, 0.3);

    if (part === 'head' && p.tissue <= 0) this.die('skull destroyed');
    else if (part === 'torso' && p.tissue <= 0) this.die('torso destroyed');
    else if (this.bloodPool <= 0) this.die('bled out');
    return dmg;
  }

  applyHitReaction(
    part: PartName, energy: number, dirX: number, dirY: number,
    contactX: number, contactY: number,
  ): HitReactionProfile {
    const reaction = hitReactionProfile(part, energy, dirX, dirY);
    const struck = this.part(part).body;
    const point = Number.isFinite(contactX) && Number.isFinite(contactY)
      ? Vec2(contactX, contactY)
      : struck.getWorldCenter();
    struck.applyLinearImpulse(
      Vec2(reaction.dirX * reaction.localImpulse, reaction.dirY * reaction.localImpulse),
      point,
      true,
    );
    const root = this.pelvis();
    if (reaction.rootImpulse > 0 && root !== struck) {
      root.applyLinearImpulse(
        Vec2(reaction.dirX * reaction.rootImpulse, reaction.dirY * reaction.rootImpulse),
        root.getWorldCenter(),
        true,
      );
    }
    return reaction;
  }

  private die(reason: string): void {
    if (this.dead) return;
    this.dead = true;
    this.deathReason = reason;
  }

  // ------------------------------------------------------------------ skeleton pose helpers
  private setJointTargets(dt: number): void {
    const previousTargets = new Map(this.joints.map(j => [j.name, j.currentTarget]));
    this.activeSwingIKTarget = null;
    this.activeSwingIKRequested = null;
    this.activeSwingIKBlend = 0;
    this.activeSwingIKDebug = null;
    // reset to stance, then overlay gait
    for (const j of this.joints) j.currentTarget = j.stanceTarget;
    if (this.stepPhase === 'idle') {
      if (this.poseRecoveryTimer > 0) {
        const progress = 1 - this.poseRecoveryTimer / CFG.locomotion.poseRecoveryDuration;
        const blend = smootherstep(progress);
        for (const j of this.joints) {
          const from = this.poseRecoveryStart.get(j.name);
          if (from !== undefined) j.currentTarget = from + (j.stanceTarget - from) * blend;
        }
      }
      // The final gait-to-stance frame must obey the same anatomical target
      // rate as the airborne IK frames; otherwise a newly aligned ankle can
      // hand a small discontinuity to its knee when the step state becomes idle.
      const maxLegTargetDelta = CFG.locomotion.legIKTargetSpeed * dt;
      for (const joint of this.joints.filter(j => /^(hip|knee|ankle)/.test(j.name))) {
        const previous = previousTargets.get(joint.name) ?? joint.currentTarget;
        joint.currentTarget = Math.max(previous - maxLegTargetDelta,
          Math.min(previous + maxLegTargetDelta, joint.currentTarget));
      }
      return;
    }

    const t = Math.max(0, Math.min(1, this.stepTimer / CFG.locomotion.stepDuration));
    const pose = gaitPose(t, this.stepDir || 1, this.stepHeightFor(this.stepDir));
    this.activeGaitPose = pose;
    const trunk = gaitTrunkTargets(pose, this.swingSide);
    const arms = gaitArmJointOffsets(pose, this.swingSide, this.facing);

    for (const j of this.joints) {
      if (j.name === 'spine') j.currentTarget = trunk.spine;
      if (j.name === 'neck') j.currentTarget = trunk.neck;
      if (j.name === `hip${this.swingSide}`) j.currentTarget = pose.swingHip;
      if (j.name === `knee${this.swingSide}`) j.currentTarget = pose.swingKnee * this.facing;
      if (j.name === `ankle${this.swingSide}`) j.currentTarget = pose.swingAnkle;
      if (j.name === `hip${this.supportSide}`) j.currentTarget = pose.supportHip;
      if (j.name === `knee${this.supportSide}`) j.currentTarget = pose.supportKnee * this.facing;
      if (j.name === `ankle${this.supportSide}`) j.currentTarget = pose.supportAnkle;
      if (j.name === 'shoulderL' && !this.lastInput.left) {
        j.currentTarget += arms.shoulderL * this.gaitArmBlend;
      }
      if (j.name === 'shoulderR' && !this.lastInput.right) {
        j.currentTarget += arms.shoulderR * this.gaitArmBlend;
      }
      if (j.name === 'elbowL' && !this.lastInput.left) {
        j.currentTarget += arms.elbowL * this.gaitArmBlend;
      }
      if (j.name === 'elbowR' && !this.lastInput.right) {
        j.currentTarget += arms.elbowR * this.gaitArmBlend;
      }
    }
    this.applySwingLegIK(pose, t);
    const maxLegTargetDelta = CFG.locomotion.legIKTargetSpeed * dt;
    for (const joint of this.joints.filter(j => /^(hip|knee|ankle)/.test(j.name))) {
      const previous = previousTargets.get(joint.name) ?? joint.currentTarget;
      joint.currentTarget = Math.max(previous - maxLegTargetDelta,
        Math.min(previous + maxLegTargetDelta, joint.currentTarget));
    }
  }

  /** Give the hand-space spring an anatomical shoulder/elbow posture to work
   * with. The force controller still owns contact and recoil; this low-torque
   * IK assist prevents the forearm from folding behind the upper arm while a
   * commanded hand extends or changes direction. */
  private applyArmIKTargets(targets: Record<'L' | 'R', Vec2 | null>): void {
    for (const side of ['L', 'R'] as const) {
      const target = targets[side];
      if (!target) continue;
      const shoulder = this.joints.find(j => j.name === `shoulder${side}`)!;
      const elbow = this.joints.find(j => j.name === `elbow${side}`)!;
      const upperArm = this.part(side === 'L' ? 'upperArmL' : 'upperArmR').body;
      const forearm = this.part(side === 'L' ? 'forearmL' : 'forearmR').body;
      const torso = this.torso();
      const root = shoulder.joint.getAnchorA();
      const elbowAnchor = elbow.joint.getAnchorA();
      const hand = this.handWorld(side);
      const upperLength = Vec2.distance(root, elbowAnchor);
      const lowerLength = Vec2.distance(elbowAnchor, hand);
      const solution = solveTwoBoneIK(
        root, target, upperLength, lowerLength, this.facing, 0.018,
      );
      const shoulderReference = upperArm.getAngle() - torso.getAngle() - shoulder.joint.getJointAngle();
      const elbowReference = forearm.getAngle() - upperArm.getAngle() - elbow.joint.getJointAngle();
      const wrappedShoulderTarget = solution.upperWorldAngle - torso.getAngle() - shoulderReference;
      shoulder.currentTarget = wrappedShoulderTarget + Math.round(
        (shoulder.currentTarget - wrappedShoulderTarget) / (Math.PI * 2),
      ) * Math.PI * 2;
      const elbowTarget = solution.lowerRelativeAngle - elbowReference;
      elbow.currentTarget = this.facing > 0
        ? Math.max(-0.04, Math.min(2.55, elbowTarget))
        : Math.max(-2.55, Math.min(0.04, elbowTarget));
    }
  }

  /** Blend an analytic hip-knee-ankle solution through the airborne part of
   * the step. The solver projects an unreachable ankle target onto the rigid
   * chain's reach, and the same projected point is passed to the force servo so
   * joint motors and foot force cannot pull the leg in opposing directions. */
  private applySwingLegIK(pose: ReturnType<typeof gaitPose>, phase: number): void {
    const side = this.swingSide;
    const hip = this.joints.find(j => j.name === `hip${side}`)!;
    const knee = this.joints.find(j => j.name === `knee${side}`)!;
    const ankle = this.joints.find(j => j.name === `ankle${side}`)!;
    const pelvis = this.pelvis();
    const thigh = this.part(side === 'L' ? 'thighL' : 'thighR').body;
    const shin = this.part(side === 'L' ? 'shinL' : 'shinR').body;
    const foot = this.part(side === 'L' ? 'footL' : 'footR').body;
    const hipAnchor = hip.joint.getAnchorA();
    const kneeAnchor = knee.joint.getAnchorA();
    const ankleAnchor = ankle.joint.getAnchorA();
    const upperLength = Vec2.distance(hipAnchor, kneeAnchor);
    const lowerLength = Vec2.distance(kneeAnchor, ankleAnchor);
    const footWorldAngle = pose.swingAnkle;
    const ankleOffset = 0.055;
    const requestedFoot = Vec2(
      this.swingStartX + (this.swingTargetX - this.swingStartX) * pose.footProgress,
      0.045 + pose.footLift,
    );
    const rawRequestedAnkle = Vec2(
      requestedFoot.x - Math.sin(footWorldAngle) * ankleOffset,
      requestedFoot.y + Math.cos(footWorldAngle) * ankleOffset,
    );
    // A contact-limited pelvis cannot always complete the nominal half-metre
    // weight transfer before heel strike. Gradually shorten only the descending
    // ankle's horizontal target; radial projection would lift it diagonally and
    // create a visible phase-1 hover/pause in close combat.
    const reachableAnkle = clampTargetXToReach(
      hipAnchor, rawRequestedAnkle, upperLength, lowerLength, 0.012,
    );
    const pelvisPathLag = Math.abs(this.pelvisStepTargetX - pelvis.getPosition().x);
    const opponentSeparation = this.opponentPelvisSeparation();
    const contactLimitedSpace = this.settlingGait || this.externalContactTimer > 0 ||
      (opponentSeparation !== null && opponentSeparation < 0.82);
    const contactLimitBlend = contactLimitedSpace
      ? smootherstep((pelvisPathLag - 0.18) / 0.16)
      : 0;
    const landingReachBlend = smootherstep((phase - 0.52) / 0.38) * contactLimitBlend;
    const requestedAnkle = Vec2(
      rawRequestedAnkle.x + (reachableAnkle.x - rawRequestedAnkle.x) * landingReachBlend,
      rawRequestedAnkle.y,
    );
    const kneeBendDirection = this.facing === 1 ? -1 : 1;
    const solution = solveTwoBoneIK(
      hipAnchor, requestedAnkle, upperLength, lowerLength, kneeBendDirection, 0.012,
    );
    const hipReference = thigh.getAngle() - pelvis.getAngle() - hip.joint.getJointAngle();
    const kneeReference = shin.getAngle() - thigh.getAngle() - knee.joint.getJointAngle();
    const ankleReference = foot.getAngle() - shin.getAngle() - ankle.joint.getJointAngle();
    const ikTargets = {
      hip: Math.max(-1.18, Math.min(1.58, solution.upperWorldAngle - pelvis.getAngle() - hipReference)),
      knee: this.facing === 1
        ? Math.max(-2.35, Math.min(0.02, solution.lowerRelativeAngle - kneeReference))
        : Math.max(-0.02, Math.min(2.35, solution.lowerRelativeAngle - kneeReference)),
      ankle: Math.max(-0.55, Math.min(0.55, footWorldAngle - solution.lowerWorldAngle - ankleReference)),
    };
    this.activeSwingIKDebug = {
      rootX: hipAnchor.x,
      rootY: hipAnchor.y,
      upperLength,
      lowerLength,
      upperWorldAngle: solution.upperWorldAngle,
      lowerRelativeAngle: solution.lowerRelativeAngle,
      lowerWorldAngle: solution.lowerWorldAngle,
      hipReference,
      kneeReference,
      ankleReference,
      hipTarget: ikTargets.hip,
      kneeTarget: ikTargets.knee,
      ankleTarget: ikTargets.ankle,
      rawAnkleX: rawRequestedAnkle.x,
      reachableAnkleX: reachableAnkle.x,
      landingReachBlend,
      pelvisPathLag,
      externalBodyContact: contactLimitedSpace ? 1 : 0,
      opponentSeparation: opponentSeparation ?? -1,
    };
    const blendIn = smootherstep((phase - TOE_OFF_PHASE) / 0.16);
    // Keep IK authoritative through physical heel strike. Blending it back to
    // zero at phase 1 released the hip/knee chain while the foot was still
    // airborne, so the straight-leg stance pose held the sole 20-30 cm above
    // the floor until gravity eventually won.
    const blend = Math.max(0, Math.min(1, blendIn));
    this.activeSwingIKBlend = blend;
    this.activeSwingIKRequested = requestedFoot;
    this.activeSwingIKTarget = Vec2(
      solution.projectedTip.x + Math.sin(footWorldAngle) * ankleOffset,
      solution.projectedTip.y - Math.cos(footWorldAngle) * ankleOffset,
    );
    hip.currentTarget += (ikTargets.hip - hip.currentTarget) * blend;
    knee.currentTarget += (ikTargets.knee - knee.currentTarget) * blend;
    ankle.currentTarget += (ikTargets.ankle - ankle.currentTarget) * blend;
  }

  /** True only when one of this fighter's articulated bodies is touching a
   * fixture owned by the opposing fighter. Ground contact and the fighter's
   * own weapon/shield are deliberately ignored. Contact state comes from the
   * previous solved substep, so it is stable input to the next motor update. */
  private hasExternalBodyContact(): boolean {
    for (const part of this.parts.values()) {
      let edge = part.body.getContactList() as any;
      while (edge) {
        const contact = edge.contact;
        if (contact?.isTouching?.()) {
          const dataA = contact.getFixtureA()?.getUserData?.() as any;
          const dataB = contact.getFixtureB()?.getUserData?.() as any;
          const other = dataA?.fighterId === this.id ? dataB
            : dataB?.fighterId === this.id ? dataA : null;
          if (other?.fighterId !== undefined && other.fighterId !== this.id) return true;
        }
        edge = edge.next;
      }
    }
    return false;
  }

  private opponentPelvisSeparation(): number | null {
    const ownPelvisX = this.pelvis().getPosition().x;
    let body = this.world.getBodyList();
    while (body) {
      let fixture = body.getFixtureList();
      while (fixture) {
        const data = fixture.getUserData() as any;
        if (data?.kind === 'part' && data.part === 'pelvis' &&
            data.fighterId !== undefined && data.fighterId !== this.id) {
          return Math.abs(body.getPosition().x - ownPelvisX);
        }
        fixture = fixture.getNext();
      }
      body = body.getNext();
    }
    return null;
  }

  private captureFootAnchors(): void {
    for (const side of ['L', 'R'] as const) {
      const foot = this.part(side === 'L' ? 'footL' : 'footR').body;
      this.footAnchorX[side] = foot.getPosition().x;
    }
  }

  private attachFootRail(
    side: 'L' | 'R', pivot: 'center' | 'heel' | 'toe' = 'center',
    direction: -1 | 1 = (this.stepDir || this.facing) as -1 | 1,
  ): boolean {
    const existing = this.footRail[side];
    if (existing && this.footRailPivot[side] === pivot) return false;
    if (existing) this.world.destroyJoint(existing);
    const foot = this.part(side === 'L' ? 'footL' : 'footR').body;
    const pivotSign = pivot === 'toe' ? 1 : pivot === 'heel' ? -1 : 0;
    const anchor = pivot === 'center'
      ? foot.getPosition()
      : foot.getWorldPoint(Vec2(pivotSign * direction * 0.105, -0.007));
    this.footRail[side] = this.world.createJoint(WheelJoint({
      frequencyHz: 0.1,
      dampingRatio: 1,
      enableMotor: false,
    }, this.footGround, foot, anchor, Vec2(0, 1))) as WheelJoint;
    this.footRailPivot[side] = pivot;
    if (!existing || pivot !== 'toe') {
      const velocity = foot.getLinearVelocity();
      // Heel strike captures the planted shoe horizontally. Keep its vertical
      // settling velocity so contact remains physical, but do not carry a
      // residual lateral landing skid through a toe-to-heel pivot replacement
      // into the support phase.
      foot.setLinearVelocity(Vec2(0, velocity.y));
    }
    return !existing;
  }

  private releaseFootRail(side: 'L' | 'R'): void {
    const rail = this.footRail[side];
    if (!rail) return;
    this.world.destroyJoint(rail);
    this.footRail[side] = null;
    this.footRailPivot[side] = 'center';
  }

  private queueFootPlant(side: 'L' | 'R'): void {
    const foot = this.part(side === 'L' ? 'footL' : 'footR').body;
    const p = foot.getPosition();
    const v = foot.getLinearVelocity();
    const impactSpeed = Math.hypot(v.x * 0.7, Math.min(0, v.y));
    this.pendingFootPlants.push({
      side,
      x: p.x,
      intensity: Math.max(0.25, Math.min(1, 0.28 + impactSpeed * 0.22)),
    });
  }

  private stepHeightFor(direction: -1 | 0 | 1): number {
    if (this.combatReplant) return CFG.locomotion.combatStepHeight;
    const backward = direction !== 0 && direction !== this.facing;
    return CFG.locomotion.stepHeight *
      (backward ? CFG.locomotion.backwardStepHeightScale : 1);
  }

  private startStep(dir: -1 | 1, alternating: boolean): void {
    this.combatReplant = false;
    this.combatStanceCenterX = null;
    // Only a physically chained footfall should inherit the previous step's
    // forward momentum. A new input from idle still ramps up naturally.
    this.continuousStep = alternating && this.stepPhase !== 'idle';
    this.stepEntryVelocityX = this.continuousStep ? this.pelvis().getLinearVelocity().x : 0;
    this.stepPhase = 'lift';
    this.stepTimer = 0;
    this.stepDir = dir;
    this.brakingForReversal = false;
    const xL = this.part('footL').body.getPosition().x;
    const xR = this.part('footR').body.getPosition().x;
    const reversing = this.lastStepDir !== 0 && this.lastStepDir !== dir;
    if (reversing) this.reversalRecoveryTimer = CFG.locomotion.reversalRecoveryDuration;
    if (reversing) {
      // On a direction change the old leading foot must cross behind the old
      // trailing foot. Selecting the foot already furthest in the new
      // direction produced a zero-length first step followed by an impossible
      // metre-long crossover. A compact physical crossover preserves cadence
      // and gives the pelvis a real base for the following normal stride.
      this.swingSide = dir > 0 ? (xL <= xR ? 'L' : 'R') : (xR >= xL ? 'R' : 'L');
      this.supportSide = this.swingSide === 'L' ? 'R' : 'L';
    } else if (!alternating || this.lastStepDir !== dir) {
      this.swingSide = dir > 0 ? (xR >= xL ? 'R' : 'L') : (xL <= xR ? 'L' : 'R');
      this.supportSide = this.swingSide === 'L' ? 'R' : 'L';
    } else {
      this.swingSide = this.supportSide === 'L' ? 'R' : 'L';
    }
    const supportFoot = this.part(this.supportSide === 'L' ? 'footL' : 'footR').body;
    const swingFoot = this.part(this.swingSide === 'L' ? 'footL' : 'footR').body;
    this.supportAnchorX = supportFoot.getPosition().x;
    this.swingStartX = swingFoot.getPosition().x;
    const directionalPelvisSpeed = this.pelvis().getLinearVelocity().x * dir;
    const backwardScale = dir === this.facing ? 1 : CFG.locomotion.backwardStrideScale;
    const nominalStride = CFG.locomotion.strideLength * backwardScale;
    const stepLength = reversing ? CFG.locomotion.reversalStepLength
      : this.reversalRecoveryTimer > 0 ? nominalStride
      : velocityAwareStepLength(
        nominalStride,
        directionalPelvisSpeed,
        CFG.locomotion.strideVelocityGain,
        CFG.locomotion.strideLengthMin * backwardScale,
        CFG.locomotion.strideLengthMax * backwardScale,
      );
    this.swingTargetX = this.supportAnchorX + dir * stepLength;
    // `strideLength` is the heel-to-heel distance between alternating contacts.
    // The moved foot travels roughly two such steps, while the foot-base centre
    // and pelvis each advance one. The previous 0.5 multiplier incorrectly
    // treated this value as a same-foot stride and held the torso behind the
    // feet, halving speed and creating the visible backward lean.
    this.pelvisPathStartX = this.pelvisStepTargetX;
    this.pelvisPathEndX = this.pelvisPathStartX + dir * stepLength;
    this.activeGaitPose = gaitPose(0, dir, this.stepHeightFor(dir));
    // A step begins by loading the new support foot through its heel while the
    // old support foot finishes the previous contact through its toe. Moving
    // the rail anchor with the anatomical contact point lets the sole rotate
    // without forcing that contact to scrape sideways across the floor.
    const supportAttached = this.attachFootRail(this.supportSide, 'heel', dir);
    if (alternating && supportAttached) this.queueFootPlant(this.supportSide);
    // Keep both feet planted through the short double-support interval. The
    // swing rail releases at toe-off inside applyFootControl().
    this.attachFootRail(this.swingSide, 'toe', dir);
  }

  /** Lift and replace one foot under the current centre of mass without
   * commanding travel. This gives active fighters visible weight changes and
   * repairs crossed legs after contact while zero movement input remains zero
   * voluntary translation. */
  private startCombatReplant(forceCrossRepair = false, followContactDisplacement = false): void {
    const pelvisX = this.pelvis().getPosition().x;
    const xL = this.part('footL').body.getPosition().x;
    const xR = this.part('footR').body.getPosition().x;
    const crossed = (xR - xL) * this.facing < -CFG.locomotion.combatCrossMargin;
    let side = this.combatReplantNextSide;
    if (forceCrossRepair || crossed) {
      side = this.facing > 0 ? (xR <= xL ? 'R' : 'L') : (xL <= xR ? 'L' : 'R');
    }
    this.combatReplantNextSide = side === 'L' ? 'R' : 'L';
    this.swingSide = side;
    this.supportSide = side === 'L' ? 'R' : 'L';
    const swingFoot = this.part(side === 'L' ? 'footL' : 'footR').body;
    const supportFoot = this.part(this.supportSide === 'L' ? 'footL' : 'footR').body;
    const sideSign = side === 'R' ? 1 : -1;
    const existingFootCenter = (xL + xR) / 2;
    if (followContactDisplacement || this.combatStanceCenterX === null) {
      this.combatStanceCenterX = followContactDisplacement ? pelvisX : existingFootCenter;
    }
    // Keep alternating weight shifts centred on one planted stance. Reusing
    // the newly solved foot centre every cycle accumulated the small heel/toe
    // pivot error and made repeated attacks crawl backwards.
    const stanceCenterX = this.combatStanceCenterX;
    const targetX = stanceCenterX + sideSign * this.facing * CFG.locomotion.combatStanceHalfWidth;
    const delta = targetX - swingFoot.getPosition().x;
    const dir = (Math.abs(delta) > 0.01 ? Math.sign(delta) : sideSign * this.facing) as -1 | 1;

    this.combatReplant = true;
    this.continuousStep = false;
    this.stepEntryVelocityX = 0;
    this.stepPhase = 'lift';
    this.stepTimer = 0;
    this.stepDir = dir;
    this.brakingForReversal = false;
    this.settlingGait = true;
    this.needsClosingStep = false;
    this.moveWasHeld = false;
    this.supportAnchorX = supportFoot.getPosition().x;
    this.swingStartX = swingFoot.getPosition().x;
    this.swingTargetX = targetX;
    this.settlePelvisX = stanceCenterX;
    this.pelvisStepTargetX = stanceCenterX;
    this.pelvisPathStartX = stanceCenterX;
    this.pelvisPathEndX = stanceCenterX;
    this.activeGaitPose = gaitPose(0, dir, CFG.locomotion.combatStepHeight);
    this.attachFootRail(this.supportSide, 'heel', dir);
    this.attachFootRail(this.swingSide, 'toe', dir);
    this.combatReplantTimer = CFG.locomotion.combatReplantInterval;
  }

  private applyFootControl(ms: number): void {
    const L = CFG.locomotion;
    const clampForce = (x: number, y: number, max: number): Vec2 => {
      const mag = Math.hypot(x, y);
      if (mag <= max) return Vec2(x, y);
      return Vec2(x * max / mag, y * max / mag);
    };

    if (this.stepPhase !== 'idle') {
      if (!this.isStanding()) {
        this.releaseFootRail('L');
        this.releaseFootRail('R');
        return;
      }
      const t = Math.max(0, Math.min(1, this.stepTimer / L.stepDuration));
      const pose = gaitPose(t, this.stepDir || 1, this.stepHeightFor(this.stepDir));
      this.activeGaitPose = pose;
      const support = this.part(this.supportSide === 'L' ? 'footL' : 'footR').body;
      const supportPivot = t < 0.28 ? 'heel' : t < 0.70 ? 'center' : 'toe';
      this.attachFootRail(this.supportSide, supportPivot, this.stepDir as -1 | 1);
      const weightAcceptance = smootherstep(t / 0.28);
      const weightRelease = smootherstep((t - 0.82) / 0.18);
      const supportLoadScale = 0.25 + 0.75 * weightAcceptance * (1 - weightRelease);
      support.applyForceToCenter(Vec2(0, -L.supportFootLoad * supportLoadScale * ms), true);
      const swing = this.part(this.swingSide === 'L' ? 'footL' : 'footR').body;
      const swingShin = this.part(this.swingSide === 'L' ? 'shinL' : 'shinR').body;
      const swingThigh = this.part(this.swingSide === 'L' ? 'thighL' : 'thighR').body;
      const wp = swing.getPosition(), wv = swing.getLinearVelocity();
      if (t <= TOE_OFF_PHASE) {
        this.attachFootRail(this.swingSide, 'toe', this.stepDir as -1 | 1);
        return;
      }
      // Once heel strike has physically captured the swing foot, keep that
      // contact through the remaining step. Releasing it again on the next
      // substep caused repeated plant events and a visible landing chatter.
      if (t >= HEEL_STRIKE_PHASE && this.footRail[this.swingSide]) return;
      this.releaseFootRail(this.swingSide);
      const rawTargetX = this.swingStartX + (this.swingTargetX - this.swingStartX) * pose.footProgress;
      const rawTargetY = 0.045 + pose.footLift;
      const ikTarget = this.activeSwingIKTarget;
      const targetX = ikTarget ? rawTargetX + (ikTarget.x - rawTargetX) * this.activeSwingIKBlend : rawTargetX;
      const targetY = ikTarget ? rawTargetY + (ikTarget.y - rawTargetY) * this.activeSwingIKBlend : rawTargetY;
      const swingForce = clampForce(
        L.swingFootKp * (targetX - wp.x) - L.swingFootKd * wv.x,
        L.swingFootKp * (targetY - wp.y) - L.swingFootKd * wv.y,
        L.swingFootForceMax * ms,
      );
      swing.applyForceToCenter(swingForce, true);
      // Hip flexors unload the airborne chain before accelerating it. Without
      // this mass-proportional feed-forward, nearly the entire vertical foot
      // servo was spent cancelling the 10.6 kg leg's weight and the sole never
      // cleared contact, feeding ground impulses back through every motor.
      const landingRelease = smootherstep((t - 0.50) / 0.40);
      const gravityAssist = -CFG.physics.gravityY * L.swingLegGravityAssist * (1 - landingRelease) * ms;
      for (const segment of [swing, swingShin, swingThigh]) {
        segment.applyForceToCenter(Vec2(0, segment.getMass() * gravityAssist), true);
      }
      const landingLoad = L.swingFootLandingForce * smootherstep((t - 0.58) / 0.32) * ms;
      swing.applyForceToCenter(Vec2(0, -landingLoad), true);
      // Move the articulated leg as a chain instead of yanking only its light
      // terminal foot. This approximates hip/knee muscle contribution while
      // preserving all joint limits and contact response.
      swingShin.applyForceToCenter(Vec2(swingForce.x * 0.72, swingForce.y * 0.28), true);
      swingThigh.applyForceToCenter(Vec2(swingForce.x * 0.42, swingForce.y * 0.14), true);
      if (t >= HEEL_STRIKE_PHASE && Math.abs(targetX - wp.x) < 0.055 && wp.y < 0.09) {
        if (this.attachFootRail(this.swingSide, 'heel', this.stepDir as -1 | 1)) {
          this.queueFootPlant(this.swingSide);
        }
      }
      return;
    }

    if (!this.isStanding()) {
      this.releaseFootRail('L');
      this.releaseFootRail('R');
      this.captureFootAnchors();
      return;
    }
    if (this.attachFootRail('L')) this.queueFootPlant('L');
    if (this.attachFootRail('R')) this.queueFootPlant('R');
  }

  // ------------------------------------------------------------------ per-step update
  update(dt: number, input: FighterInput): void {
    this.age += dt;
    const weaponControlActive = !!input.right;
    if (this.weapon && this.weaponControlWasActive && !weaponControlActive) {
      const releaseSpeed = Math.abs(this.weapon.body.getAngularVelocity());
      this.weaponFollowThroughTimer = releaseSpeed >= CFG.weapon.followThroughMinAngularSpeed
        ? Math.min(CFG.weapon.swordFollowThroughMaxSec, 0.08 + releaseSpeed * 0.012)
        : 0;
    } else if (weaponControlActive) {
      this.weaponFollowThroughTimer = 0;
    } else {
      this.weaponFollowThroughTimer = Math.max(0, this.weaponFollowThroughTimer - dt);
    }
    this.weaponControlWasActive = weaponControlActive;
    this.lastInput = input;
    this.externalContactTimer = Math.max(0, this.externalContactTimer - dt);
    this.shieldShoveCooldown = Math.max(0, this.shieldShoveCooldown - dt);
    this.combatReplantTimer = Math.max(0, this.combatReplantTimer - dt);
    this.reversalRecoveryTimer = Math.max(0, this.reversalRecoveryTimer - dt);
    // Preserve the contact-limited landing decision through the rest of the
    // current physical step even if recoil briefly opens the fixtures again.
    if (this.hasExternalBodyContact()) this.externalContactTimer = 0.65;
    this.poseRecoveryTimer = Math.max(0, this.poseRecoveryTimer - dt);
    const st = this.stamina;
    let ms = st.motorScale();
    if (this.dead) ms = 0;

    // --- locomotion state machine
    if (this.stepCooldown > 0) this.stepCooldown -= dt;
    const heldMove = Math.max(-1, Math.min(1, input.move ?? 0));
    const heldDir = Math.sign(heldMove) as -1 | 0 | 1;
    const releasingBlockedDirection = heldDir === 0 && this.blockedMoveDir !== 0;
    const escapingBlockedDirection = this.blockedMoveDir !== 0 && heldDir !== 0 &&
      heldDir !== this.blockedMoveDir;
    if (heldDir === 0 || escapingBlockedDirection) {
      this.blockedMoveDir = 0;
      // Backing away from a wall is a fresh retreat, not a mid-stride reversal.
      // Keeping the blocked approach as `lastStepDir` forced the first escape
      // footfall into the tiny crossover path and made backward control feel
      // unresponsive for most of the first second.
      if ((escapingBlockedDirection || releasingBlockedDirection) && this.stepPhase === 'idle') {
        this.lastStepDir = 0;
        this.reversalRecoveryTimer = 0;
      }
    }
    const requestedDir = Math.sign(heldMove || input.step) as -1 | 0 | 1;
    if (heldMove !== 0) this.moveWasHeld = true;
    if (requestedDir !== 0 && requestedDir !== this.blockedMoveDir &&
        this.stepPhase === 'idle' && this.stepCooldown <= 0 && !this.dead && !st.collapsed) {
      this.settlingGait = false;
      this.needsClosingStep = false;
      this.poseRecoveryTimer = 0;
      this.startStep(requestedDir, this.lastStepDir === requestedDir);
    }
    if (requestedDir === 0 && this.stepPhase === 'idle' && this.stepCooldown <= 0 &&
        !this.dead && !st.collapsed) {
      const footL = this.part('footL').body.getPosition().x;
      const footR = this.part('footR').body.getPosition().x;
      const footCenter = (footL + footR) / 2;
      const crossed = (footR - footL) * this.facing < -CFG.locomotion.combatCrossMargin;
      const displacedByContact = this.externalContactTimer > 0 &&
        Math.abs(this.pelvis().getPosition().x - footCenter) > CFG.locomotion.combatReplantPelvisOffset;
      const activeHands = !!input.left || !!input.right;
      const periodicCombatStep = activeHands && this.combatReplantTimer <= 0 &&
        this.lastHandForce < 55 && this.lastTipSpeed < 1.0;
      if (crossed || displacedByContact || periodicCombatStep) {
        this.startCombatReplant(crossed, displacedByContact);
      }
    }
    if (this.stepPhase !== 'idle' && heldMove === 0 && this.moveWasHeld && !this.settlingGait) {
      this.settlingGait = true;
      const t = Math.max(0, Math.min(1, this.stepTimer / CFG.locomotion.stepDuration));
      const pose = gaitPose(t, this.stepDir || 1, this.stepHeightFor(this.stepDir));
      const u = pose.footProgress;
      const currentTargetX = this.swingStartX + (this.swingTargetX - this.swingStartX) * u;
      const supportFoot = this.part(this.supportSide === 'L' ? 'footL' : 'footR').body;
      const closingStance = 0.30;
      const nominalEnd = supportFoot.getPosition().x + this.stepDir * closingStance;
      this.needsClosingStep = Math.abs(currentTargetX - nominalEnd) > 0.08;
      const closingEnd = this.stepDir > 0
        ? Math.max(currentTargetX, nominalEnd)
        : Math.min(currentTargetX, nominalEnd);
      // A late release may happen after the swing foot has travelled beyond
      // the pelvis' static leg reach. Freezing the pelvis immediately left the
      // IK target projected above the floor forever. Let the body finish the
      // current weight transfer behind the landing foot, then collect the
      // trailing leg in the short closing step below.
      this.settlePelvisX = closingEnd - this.stepDir * closingStance * 0.8;
      // Rebase the remaining curve so its current world target is unchanged.
      // Only the future heel-strike point moves inward.
      if (u < 0.98) this.swingStartX = (currentTargetX - closingEnd * u) / Math.max(0.02, 1 - u);
      this.swingTargetX = closingEnd;
      this.pelvisPathStartX = this.pelvisStepTargetX;
      this.pelvisPathEndX = this.pelvisStepTargetX;
    }
    if (this.stepPhase !== 'idle' && heldDir !== 0 && this.stepDir !== 0 &&
        heldDir !== this.stepDir && !this.settlingGait) {
      // Finish the already-committed footfall, but stop feeding the pelvis
      // farther along the obsolete travel direction. The position servo's
      // damping can now brake the torso during double support, so the first
      // opposite footfall starts from a controlled weight shift instead of
      // having to cancel another body-length of forward momentum.
      if (!this.brakingForReversal) {
        const t = Math.max(0, Math.min(1, this.stepTimer / CFG.locomotion.stepDuration));
        const u = gaitPose(t, this.stepDir, this.stepHeightFor(this.stepDir)).footProgress;
        const currentTargetX = this.swingStartX + (this.swingTargetX - this.swingStartX) * u;
        const supportFoot = this.part(this.supportSide === 'L' ? 'footL' : 'footR').body;
        const brakingTargetX = supportFoot.getPosition().x +
          this.stepDir * CFG.locomotion.reversalCommitLength;
        if (u < 0.98) {
          this.swingStartX = (currentTargetX - brakingTargetX * u) / Math.max(0.02, 1 - u);
        }
        this.swingTargetX = brakingTargetX;
        this.brakingForReversal = true;
      }
      this.pelvisPathStartX = this.pelvisStepTargetX;
      this.pelvisPathEndX = this.pelvisStepTargetX;
    }
    if (this.stepPhase !== 'idle') {
      const cadenceScale = this.reversalRecoveryTimer > 0 ? CFG.locomotion.reversalCadenceScale : 1;
      this.stepTimer += dt * cadenceScale * this.locomotionRate;
      const dur = CFG.locomotion.stepDuration;
      if (this.stepPhase === 'lift' && this.stepTimer > dur * 0.35) { this.stepPhase = 'plant'; }
      else if (this.stepPhase === 'plant' && this.stepTimer > dur * 0.7) { this.stepPhase = 'recover'; }
      else if (this.stepPhase === 'recover' && this.stepTimer > dur) {
        const landingFoot = this.part(this.swingSide === 'L' ? 'footL' : 'footR').body;
        const locomotionBody = this.pelvis();
        const locomotionDir = (this.stepDir || heldDir || 1) as -1 | 1;
        const targetError = (this.pelvisStepTargetX - locomotionBody.getPosition().x) * locomotionDir;
        const directionalSpeed = locomotionBody.getLinearVelocity().x * locomotionDir;
        const obstacleStall = targetError > 0.18 && directionalSpeed < 0.12;
        let physicallyPlanted = !!this.footRail[this.swingSide] && landingFoot.getPosition().y < 0.14;
        if (!physicallyPlanted && this.stepTimer > dur + CFG.locomotion.stepPlantGrace && landingFoot.getPosition().y < 0.14) {
          if (this.attachFootRail(this.swingSide, 'heel', locomotionDir)) {
            this.queueFootPlant(this.swingSide);
          }
          physicallyPlanted = true;
        }
        // Do not promote an airborne swing foot to support-leg status. The
        // previous timer-only swap created one-frame "support" feet 20-30 cm
        // above the floor and made the next leg snap underneath the body.
        if (!physicallyPlanted) {
          if (this.stepTimer > dur + CFG.locomotion.stepPlantGrace && obstacleStall) {
            // A body or arena obstacle can stop the pelvis while the held gait
            // keeps requesting a footfall through that obstacle. The rigid leg
            // solver then projects the impossible target above the floor and a
            // timer-only state machine would wait forever. Retarget to the
            // foot's current reachable x, land physically, and suppress this
            // held direction until the player releases or changes direction.
            const pelvisX = this.pelvis().getPosition().x;
            const reachableX = Math.max(pelvisX - 0.26, Math.min(pelvisX + 0.26, landingFoot.getPosition().x));
            this.blockedMoveDir = (this.stepDir || heldDir || 1) as -1 | 1;
            this.settlingGait = true;
            this.needsClosingStep = false;
            this.swingStartX = reachableX;
            this.swingTargetX = reachableX;
            this.settlePelvisX = pelvisX;
            this.pelvisPathStartX = this.pelvisStepTargetX;
            this.pelvisPathEndX = this.pelvisStepTargetX;
          }
          this.stepTimer = Math.min(this.stepTimer, dur + CFG.locomotion.stepPlantGrace + 0.001);
        } else {
          const completedDir = (this.stepDir || 1) as -1 | 1;
          if (obstacleStall && heldDir === completedDir) this.blockedMoveDir = completedDir;
          this.supportSide = this.swingSide;
          this.lastStepDir = completedDir;
          if (heldMove !== 0 && heldDir !== this.blockedMoveDir && !this.dead && !st.collapsed) {
            this.settlingGait = false;
            this.startStep(heldDir as -1 | 1, true);
          } else if (heldDir !== 0 && heldDir === this.blockedMoveDir) {
            this.finishGait();
          } else if (!this.settlingGait) {
            const footCenter = (this.part('footL').body.getPosition().x + this.part('footR').body.getPosition().x) / 2;
            const centerError = this.pelvis().getPosition().x - footCenter;
            if (Math.abs(centerError) > 0.32) {
              const settleDir = Math.sign(centerError) as -1 | 1;
              this.settlingGait = true;
              this.settlePelvisX = this.pelvis().getPosition().x;
              this.startStep(settleDir, true);
              // One deliberate catch step brings the trailing foot under the
              // centre of mass. This replaces the old pair of full-length stop
              // lunges that looked like two extra input taps.
              this.swingTargetX = this.pelvis().getPosition().x + settleDir * 0.10;
            } else {
              this.finishGait();
            }
          } else {
            if (this.needsClosingStep) {
              // A late release may happen after the moving foot has already
              // passed the closing target. Never drag that foot backwards;
              // plant it, then bring the trailing foot into a compact stance
              // with one short, physically articulated collection step.
              this.needsClosingStep = false;
              this.settlePelvisX = this.pelvis().getPosition().x;
              this.startStep(completedDir, true);
              const leadFoot = this.part(this.supportSide === 'L' ? 'footL' : 'footR').body;
              this.swingTargetX = leadFoot.getPosition().x - completedDir * 0.30;
              this.pelvisPathEndX = this.pelvisPathStartX;
            } else {
              this.finishGait();
            }
          }
        }
      }
      // The pelvis force below runs before setJointTargets(). Refresh the pose
      // here so it never consumes the previous step's terminal sample for one
      // extra substep after a physical foot swap.
      this.activeGaitPose = gaitPose(
        Math.max(0, Math.min(1, this.stepTimer / CFG.locomotion.stepDuration)),
        this.stepDir || 1,
        this.stepHeightFor(this.stepDir),
      );
      // Keep the pelvis inside the active foot base. A velocity servo can push
      // the body far ahead of feet that have not planted yet, producing the
      // frozen, leaning gait this controller is meant to eliminate.
      const fpelvis = this.pelvis();
      const pv = fpelvis.getLinearVelocity();
      const pathTargetX = this.settlingGait
        ? this.settlePelvisX
        : this.pelvisPathStartX +
          (this.pelvisPathEndX - this.pelvisPathStartX) * this.activeGaitPose.pelvisProgress;
      const physicalFootCenter = (
        this.part('footL').body.getPosition().x + this.part('footR').body.getPosition().x
      ) / 2;
      const gaitProgress = Math.max(0, Math.min(1, this.stepTimer / CFG.locomotion.stepDuration));
      // At a foot swap the new support foot is already half a stride ahead of
      // the old trailing foot. A fixed 0.20 m limit against their average
      // stopped the pelvis during double support. Allow the centre of mass to
      // pass over that forward support, then return to the tighter single-
      // support envelope as the trailing foot advances.
      const doubleSupportBlend = 1 - smootherstep(gaitProgress / 0.35);
      const maxLead = CFG.locomotion.pelvisLeadSingleSupport +
        (CFG.locomotion.pelvisLeadDoubleSupport - CFG.locomotion.pelvisLeadSingleSupport) *
          doubleSupportBlend;
      const rawDesiredX = Math.max(
        physicalFootCenter - maxLead,
        Math.min(physicalFootCenter + maxLead, pathTargetX),
      );
      const maxPelvisTargetDelta = CFG.locomotion.pelvisTargetSpeed * dt;
      const desiredX = Math.max(
        this.pelvisStepTargetX - maxPelvisTargetDelta,
        Math.min(this.pelvisStepTargetX + maxPelvisTargetDelta, rawDesiredX),
      );
      const previousTargetX = this.pelvisStepTargetX;
      this.pelvisStepTargetX = desiredX;
      const finiteDifferenceVelocity = (desiredX - previousTargetX) / Math.max(dt, 1e-6);
      // The end of one path and start of the next are the same position, so a
      // finite difference falsely reports zero velocity at the swap. Blend the
      // resolved entry velocity into the first part of the next weight transfer
      // and then return to the position-derived physical velocity.
      const entryVelocityBlend = this.continuousStep && !this.settlingGait &&
        !this.brakingForReversal && this.blockedMoveDir === 0
        ? 1 - smootherstep(gaitProgress / 0.18)
        : 0;
      const requestedVelocity = finiteDifferenceVelocity * (1 - entryVelocityBlend) +
        this.stepEntryVelocityX * entryVelocityBlend;
      const feedForwardLimit = CFG.locomotion.pelvisFeedForwardSpeed * this.locomotionRate;
      this.pelvisTargetVelocityX = Math.max(-feedForwardLimit,
        Math.min(feedForwardLimit, requestedVelocity));
      const momentumTransferBlend = this.continuousStep && !this.settlingGait
        ? 1 - smootherstep(gaitProgress / 0.22)
        : 0;
      const velocityDamping = CFG.locomotion.pelvisDriveKd *
        (1 + (CFG.locomotion.pelvisDoubleSupportKdScale - 1) * momentumTransferBlend);
      const fx = Math.max(-CFG.locomotion.pelvisForceMax, Math.min(CFG.locomotion.pelvisForceMax,
        CFG.locomotion.pelvisDriveKp * (desiredX - fpelvis.getPosition().x) -
        velocityDamping * (pv.x - this.pelvisTargetVelocityX))) * ms * this.locomotionRate;
      fpelvis.applyForceToCenter(Vec2(fx, 0), true);
    } else {
      this.pelvisTargetVelocityX = 0;
    }
    const armBlendTarget = this.stepPhase === 'idle' ? 0 : 1;
    const armBlendResponse = 1 - Math.exp(-8 * dt);
    this.gaitArmBlend += (armBlendTarget - this.gaitArmBlend) * armBlendResponse;
    const shapedHands = {
      L: this.shapeHandCommand('L', input.left, dt),
      R: this.shapeHandCommand('R', input.right, dt, input.rightGesture),
    };
    this.setJointTargets(dt);
    this.applyArmIKTargets(shapedHands);
    this.applyFootControl(ms);

    // --- pose motors (position error -> bounded motor velocity)
    if (ms > 0) {
      // facing correction: if torso flipped past 90 degrees, mirror facing
      const torsoAng = this.torso().getAngle();
      if (Math.abs(torsoAng) > 1.2 && Math.abs(torsoAng) < 2.0) {
        // crumpling is fine; only mirror when fully turned around
      }
      for (const j of this.joints) {
        const partMult = this.part(j.attachedPart).motorMult;
        const isArm = j.name.startsWith('shoulder') || j.name.startsWith('elbow');
        const sideInput = j.name.endsWith('L') ? input.left : j.name.endsWith('R') ? input.right : null;
        // A commanded hand is owned by the hand-space PD controller. Joint
        // motors remain as a weak anatomical assist instead of fighting the
        // target. In neutral they retain enough torque to hold the guard.
        const freeArmAssist = this.stepPhase === 'idle' ? 0.55 : 0.50;
        const freeGaitArm = isArm && !sideInput && this.stepPhase !== 'idle';
        const commandedArmAssist = j.name.startsWith('elbow')
          ? CFG.locomotion.armIkElbowAssist
          : CFG.locomotion.armIkShoulderAssist;
        const armsDamped = isArm ? (sideInput ? commandedArmAssist : freeArmAssist) : 1;
        let torqueMax = j.tuning.maxTorque * ms * partMult * armsDamped;
        let speed: number;
        const plantedSide = j.name === 'ankleL' ? 'L' : j.name === 'ankleR' ? 'R' : null;
        if (plantedSide && this.footRail[plantedSide] && this.isStanding() && this.stepPhase !== 'idle') {
          const L = CFG.locomotion;
          const foot = this.part(plantedSide === 'L' ? 'footL' : 'footR').body;
          const shin = this.part(plantedSide === 'L' ? 'shinL' : 'shinR').body;
          const soleTarget = plantedSide === this.supportSide
            ? this.activeGaitPose.supportAnkle
            : this.activeGaitPose.swingAnkle;
          const desiredWorldSpeed = Math.max(-L.plantedFootWorldSpeedMax, Math.min(L.plantedFootWorldSpeedMax,
            L.plantedFootAngleKp * (soleTarget - foot.getAngle())));
          // The revolute motor controls foot speed relative to the shin. Feed
          // the shin's world rotation forward so the resulting sole speed is
          // the bounded world-space correction above.
          speed = desiredWorldSpeed - shin.getAngularVelocity();
          torqueMax = L.plantedFootTorqueMax * ms * partMult;
          speed = Math.max(-L.plantedFootJointSpeedMax, Math.min(L.plantedFootJointSpeedMax, speed));
        } else {
          const rawError = j.currentTarget - j.joint.getJointAngle();
          // Resolve shoulder error on the nearest angular branch. The physical
          // limits prevent full turns, while this avoids a discontinuity near
          // the +/-pi representation boundary.
          const err = j.name.startsWith('shoulder')
            ? Math.atan2(Math.sin(rawError), Math.cos(rawError))
            : rawError;
          // A Box2D revolute motor is already a constrained velocity servo.
          // Feeding joint velocity back into its target velocity with a gain
          // above one made the command change sign every physics substep: the
          // angle looked almost correct while the rendered bodies alternated
          // between large positive/negative angular speeds. A proportional
          // position-to-speed command lets the motor's torque limit and the
          // bodies' angular damping dissipate motion instead of creating that
          // hidden limit cycle.
          speed = j.tuning.kP * (freeGaitArm ? 3.8 : 1) * err;
          speed = Math.max(-j.tuning.maxSpeed, Math.min(j.tuning.maxSpeed, speed));
        }
        j.joint.setMotorSpeed(speed);
        j.joint.setMaxMotorTorque(Math.max(0, torqueMax));
      }
    } else {
      for (const j of this.joints) j.joint.setMaxMotorTorque(0);
    }

    // --- upright balance springs (body level, scaled by motor strength)
    if (ms > 0 && this.stepPhase !== 'idle') { /* step force handled above */ }
    if (ms > 0) {
      const bal = CFG.fighter.balance;
      const pelvisB = this.pelvis();
      const torsoB = this.torso();
      const headB = this.headBody();
      const plantedStance = this.stepPhase === 'idle';
      pelvisB.setLinearDamping(plantedStance ? bal.idlePelvisLinearDamping : CFG.fighter.damping.torsoLinear);
      torsoB.setLinearDamping(plantedStance ? bal.idleTorsoLinearDamping : CFG.fighter.damping.torsoLinear);
      for (const name of ['thighL', 'shinL', 'footL', 'thighR', 'shinR', 'footR'] as PartName[]) {
        const leg = this.part(name).body;
        leg.setLinearDamping(plantedStance ? bal.idleLegLinearDamping : CFG.fighter.damping.limbLinear);
        leg.setAngularDamping(plantedStance ? bal.idleLegAngularDamping : CFG.fighter.damping.limbAngular);
      }
      const angleKpScale = plantedStance ? bal.idleAngleKpScale : bal.movingAngleKpScale;
      const angleKdScale = plantedStance ? bal.idleAngleKdScale : bal.movingAngleKdScale;
      const commandedArms = Number(!!input.left) + Number(!!input.right);
      // Route intentional arm effort through the planted stance. This keeps
      // stronger hands from visually towing the pelvis across stationary feet.
      const translationBrace = plantedStance
        ? 1 + commandedArms * bal.combatTranslationKpScalePerHand
        : 1;
      const posKpScale = (plantedStance ? bal.idlePosKpScale : 1) * translationBrace;
      const posKdScale = (plantedStance ? bal.idlePosKdScale : 1) * translationBrace;
      // A fighter recruits the trunk before moving a loaded arm. This modest
      // anticipatory brace resists whole-body folding while preserving visible
      // recoil from a heavy weapon instead of pinning the torso rigidly.
      const armBraceKp = 1 + commandedArms * 0.24;
      const armBraceKd = 1 + commandedArms * 0.16;
      const pelvisLeanBoost = 1 + Math.min(1.2, Math.max(0, Math.abs(pelvisB.getAngle()) - 0.22) * 2.4);
      const torsoLeanBoost = 1 + Math.min(1.2, Math.max(0, Math.abs(torsoB.getAngle()) - 0.22) * 2.4);
      const trunkTargets = this.stepPhase === 'idle'
        ? { pelvis: 0, thorax: 0 }
        : gaitTrunkTargets(this.activeGaitPose, this.swingSide);
      pelvisB.applyTorque((bal.pelvisAngleKp * angleKpScale * armBraceKp * pelvisLeanBoost * (trunkTargets.pelvis - pelvisB.getAngle()) - bal.pelvisAngleKd * angleKdScale * armBraceKd * pelvisB.getAngularVelocity()) * ms, true);
      torsoB.applyTorque((bal.torsoAngleKp * angleKpScale * armBraceKp * torsoLeanBoost * (trunkTargets.thorax - torsoB.getAngle()) - bal.torsoAngleKd * angleKdScale * armBraceKd * torsoB.getAngularVelocity()) * ms, true);
      const headTarget = this.stepPhase === 'idle' ? 0 : gaitTrunkTargets(this.activeGaitPose, this.swingSide).head;
      headB.applyTorque((bal.headAngleKp * (headTarget - headB.getAngle()) -
        bal.headAngleKd * headB.getAngularVelocity()) * ms, true);
      // horizontal centering of pelvis over average foot position
      const fxL = this.part('footL').body.getPosition().x;
      const fxR = this.part('footR').body.getPosition().x;
      const supportX = this.stepPhase === 'idle'
        ? (fxL + fxR) / 2
        : this.pelvisStepTargetX;
      const pv = pelvisB.getLinearVelocity();
      const pelvisVelocityError = (this.stepPhase === 'idle' ? 0 : this.pelvisTargetVelocityX) - pv.x;
      let fx = (bal.pelvisPosKp * posKpScale * (supportX - pelvisB.getPosition().x) +
        bal.pelvisPosKd * posKdScale * pelvisVelocityError) * ms;
      const translationForceMax = 420 * (plantedStance
        ? 1 + commandedArms * bal.combatTranslationForceScalePerHand
        : 1);
      fx = Math.max(-translationForceMax, Math.min(translationForceMax, fx));
      pelvisB.applyForceToCenter(Vec2(fx, 0), true);
      // Active legs support the pelvis vertically, but the height servo only
      // engages while upright; a real stumble/fall still releases it.
      if (Math.abs(torsoB.getAngle()) < 1.0 && pelvisB.getPosition().y > 0.52) {
        const targetY = bal.pelvisTargetY + (this.stepPhase === 'idle' ? 0 : this.activeGaitPose.pelvisLift);
        let fy = (bal.pelvisHeightKp * (targetY - pelvisB.getPosition().y) -
          bal.pelvisHeightKd * pv.y) * ms;
        fy = Math.max(-bal.pelvisHeightForceMax, Math.min(bal.pelvisHeightForceMax, fy));
        pelvisB.applyForceToCenter(Vec2(0, fy), true);
      }

      // Foot placement is force-controlled above. Never teleport a dynamic
      // body: hard setTransform pinning bypasses contacts and freezes gait.
      if (this.age < 1.5) {
        this.captureFootAnchors();
      } else if (!this.isStanding()) {
        this.captureFootAnchors();
      }
    }

    // --- hands: two mutually exclusive controllers (never fight each other)
    // stick present -> PD spring chases the commanded target; the effort is
    //   real physical work and counts toward stamina exertion.
    // no stick     -> gravity feed-forward (cancel arm + weapon weight) plus
    //   pure viscous damping; the POSE MOTORS alone hold the guard angles.
    //   Dissipative-only forces cannot pump limit cycles and contribute zero
    //   stamina exertion, so an idle fighter is truly calm.
    let forceImpulse = 0, speedSqSum = 0;
    if (ms > 0) {
      const h = CFG.fighter.hand;
      for (const side of ['L', 'R'] as const) {
        const rawStick = side === 'L' ? input.left : input.right;
        const stick = shapedHands[side];
        const handB = this.part(side === 'L' ? 'handL' : 'handR').body;
        const fa = this.part(side === 'L' ? 'forearmL' : 'forearmR').body;
        const ua = this.part(side === 'L' ? 'upperArmL' : 'upperArmR').body;
        const vel = handB.getLinearVelocity();
        const idleLinearDamping = 3.4;
        const idleAngularDamping = 5.0;
        for (const body of [ua, fa, handB]) {
          body.setLinearDamping(stick ? CFG.fighter.damping.limbLinear : idleLinearDamping);
          body.setAngularDamping(stick ? CFG.fighter.damping.limbAngular : idleAngularDamping);
        }
        speedSqSum += vel.lengthSquared();
        if (stick) {
          const pos = handB.getPosition();
          const placedHold = !rawStick && ((side === 'R' && !!this.weapon) ||
            (side === 'L' && !!this.shield));
          const placedKpScale = placedHold ? h.placedHoldKpScale : 1;
          const placedKdScale = placedHold ? h.placedHoldKdScale : 1;
          let fx = h.forceKp * placedKpScale * (stick.x - pos.x) -
            h.forceKd * placedKdScale * vel.x;
          let fy = h.forceKp * placedKpScale * (stick.y - pos.y) -
            h.forceKd * placedKdScale * vel.y;
          const mag = Math.hypot(fx, fy);
          const shieldIntent = side === 'L' ? this.shieldForwardIntent(rawStick) : 0;
          const shoveScale = 1 + shieldIntent * (CFG.shield.shoveHandForceScale - 1);
          const shieldForceScale = side === 'L' && this.shield
            ? SHIELD_STYLES[this.shieldStyle].handForceScale : 1;
          const weaponForceScale = side === 'R' && this.weapon
            ? COMBAT_STYLES[this.combatStyle].handForceScale : 1;
          const magMax = h.maxForce * ms *
            this.part(side === 'L' ? 'handL' : 'handR').motorMult * shoveScale *
            shieldForceScale * weaponForceScale * (placedHold ? h.placedHoldForceScale : 1);
          if (mag > magMax) { fx *= magMax / mag; fy *= magMax / mag; }
          handB.applyForceToCenter(Vec2(fx, fy), true);
          fa.applyForceToCenter(Vec2(fx * 0.55, fy * 0.55), true);
          // The hand servo represents muscles spanning the shoulder, not an
          // external tractor beam attached to world space. Cancel its net
          // linear force through the torso/pelvis while preserving the real
          // internal torque and contact reaction through the articulated arm.
          // Shield shove owns its separate ground-driven impulse below.
          // Every weapon uses the same internal muscle reaction. The former
          // flail exemption turned the hand servo into an external pull that
          // dragged and toppled the whole fighter during a quick circle.
          const reactionX = fx * 1.55;
          const reactionY = fy * 1.55;
          this.torso().applyForceToCenter(Vec2(-reactionX * 0.42, -reactionY * 0.42), true);
          this.pelvis().applyForceToCenter(Vec2(-reactionX * 0.58, -reactionY * 0.58), true);
          forceImpulse += Math.min(mag, magMax) * dt;
        } else {
          const wMass = side === 'R' && this.weapon ? this.weapon.def.mass
            : side === 'L' && this.shield ? CFG.shield.mass : 0;
          const g = -CFG.physics.gravityY;
          handB.applyForceToCenter(Vec2(-h.holdDamp * vel.x, (handB.getMass() + wMass) * g - h.holdDamp * vel.y), true);
          const fv = fa.getLinearVelocity();
          fa.applyForceToCenter(Vec2(-h.holdDamp * 0.6 * fv.x, fa.getMass() * g - h.holdDamp * 0.6 * fv.y), true);
        }
      }
    }
    this.lastHandForce = forceImpulse / Math.max(dt, 1e-6);
    const activelyBracing = !this.dead && !!input.brace && !!this.shield;
    st.update(dt, this.dead ? 0 : this.lastHandForce, this.dead ? 0 : speedSqSum, activelyBracing);

    // --- weapon
    if (this.weapon && this.weapon.gripJoint) {
      const weaponAim = this.weaponAimTarget(input.right, dt, this.shapedHandAngle.R);
      const style = COMBAT_STYLES[this.combatStyle];
      const activeStyle = input.right ? style : {
        ...style,
        gripTorqueScale: style.gripTorqueScale * CFG.weapon.releaseGripTorqueScale,
        gripKpScale: style.gripKpScale * CFG.weapon.releaseGripKpScale,
        gripKdScale: style.gripKdScale * CFG.weapon.releaseGripKdScale,
      };
      // Releasing the pointer freezes the physical handle at its current
      // angle. Keep the weapon's mass-specific hold authority active so a
      // passive flail chain cannot drag the handle into an unintended crank.
      const activeHandleDamping = this.weapon.def.kind === 'flail'
        ? CFG.weapon.flailHandleAngularDamping
        : this.weapon.def.kind === 'dagger'
          ? CFG.weapon.daggerAngularDamping
          : CFG.weapon.angularDamping;
      const aimError = weaponAim === undefined ? Infinity : weaponAim - this.weapon.body.getAngle();
      const settledAim = Math.abs(this.weaponAimVelocity) < 0.05 && Math.abs(aimError) < 0.06;
      const settledAimDamping = this.weapon.def.kind === 'sword'
        ? CFG.weapon.heldSwordAimAngularDamping
        : CFG.weapon.heldAimAngularDamping;
      this.weapon.body.setAngularDamping(input.right
        ? settledAim
          ? Math.max(activeHandleDamping, settledAimDamping)
          : activeHandleDamping
        : this.weaponFollowThroughTimer > 0
          ? CFG.weapon.followThroughAngularDamping
        : CFG.weapon.releaseHandleAngularDamping);
      if (input.right) {
        this.weaponHasControlHistory = true;
        this.weapon.gripJoint.enableMotor(true);
        if (this.weaponGripLocked) this.weapon.gripJoint.enableLimit(false);
        this.weaponGripLocked = false;
      } else if (this.weaponFollowThroughTimer > 0) {
        this.weapon.gripJoint.enableLimit(false);
        this.weapon.gripJoint.enableMotor(false);
        this.weaponGripLocked = false;
      } else if (this.weaponHasControlHistory && !this.weaponGripLocked) {
        this.weapon.gripJoint.enableMotor(true);
        const heldGripAngle = this.weapon.gripJoint.getJointAngle();
        this.weapon.gripJoint.setLimits(
          heldGripAngle - CFG.weapon.releaseGripLockHalfAngle,
          heldGripAngle + CFG.weapon.releaseGripLockHalfAngle,
        );
        this.weapon.gripJoint.enableLimit(true);
        this.weaponGripLocked = true;
      }
      if (this.weaponFollowThroughTimer > 0) {
        this.weapon.gripJoint.setMaxMotorTorque(0);
      } else {
        updateGrip(this.weapon, Math.max(0.25, ms), weaponAim, {
          speed: activeStyle.gripSpeedScale,
          torque: activeStyle.gripTorqueScale,
          kp: activeStyle.gripKpScale,
          kd: activeStyle.gripKdScale,
        }, this.weaponAimVelocity);
      }
      this.lastTipSpeed = tipSpeed(this.weapon);
      if (this.lastTipSpeed > this.weapon.maxTipSpeedSeen) this.weapon.maxTipSpeedSeen = this.lastTipSpeed;
    }
    if (this.shield && this.shield.gripJoint) {
      const bracing = !!input.brace;
      const shieldStyle = SHIELD_STYLES[this.shieldStyle];
      const activeShieldStyle = input.left || bracing ? shieldStyle : {
        gripSpeedScale: 1,
        gripKpScale: 1,
        gripTorqueScale: 1,
        braceTorqueScale: 1,
      };
      updateShield(this.shield, Math.max(0.25, ms), bracing, {
        speed: activeShieldStyle.gripSpeedScale,
        kp: activeShieldStyle.gripKpScale,
        torque: activeShieldStyle.gripTorqueScale,
        braceTorque: activeShieldStyle.braceTorqueScale,
      });
      this.applyShieldShove(input.left, bracing, ms);
      if (bracing) {
        this.stamina.spend(CFG.shield.braceStaminaPerSec * shieldStyle.braceStaminaScale * dt);
      }
    }

    // --- bleed out accumulation
    let bleed = 0;
    this.parts.forEach(p => bleed += p.bleeding);
    if (bleed > 0 && !this.dead) {
      this.bloodPool = Math.max(0, this.bloodPool - bleed * 0.004 * dt);
      if (this.bloodPool <= 0) this.die('bled out');
    }
  }

  private finishGait(): void {
    this.poseRecoveryStart.clear();
    for (const joint of this.joints) this.poseRecoveryStart.set(joint.name, joint.currentTarget);
    this.poseRecoveryTimer = CFG.locomotion.poseRecoveryDuration;
    this.stepPhase = 'idle';
    this.stepCooldown = CFG.locomotion.stepCooldown;
    this.stepDir = 0;
    this.combatReplant = false;
    this.combatReplantTimer = Math.max(this.combatReplantTimer, 0.55);
    this.continuousStep = false;
    this.stepEntryVelocityX = 0;
    this.pelvisTargetVelocityX = 0;
    this.settlingGait = false;
    this.brakingForReversal = false;
    this.reversalRecoveryTimer = 0;
    this.needsClosingStep = false;
    this.moveWasHeld = false;
    this.captureFootAnchors();
    if (this.attachFootRail('L')) this.queueFootPlant('L');
    if (this.attachFootRail('R')) this.queueFootPlant('R');
  }

  private shapeHandCommand(
    side: 'L' | 'R', raw: Vec2 | null, dt: number,
    gesture: FighterInput['rightGesture'] = null,
  ): Vec2 | null {
    if (!raw) {
      const equippedHand = side === 'R' ? !!this.weapon : !!this.shield;
      // Once the player has placed an equipped hand, releasing the pointer
      // means "hold here". Returning to an authored guard pose made the arm
      // and weapon move by themselves and was especially visible as a flail
      // handle crank while the passive chain settled.
      if (equippedHand && this.shapedHandTarget[side]) {
        return this.shapedHandTarget[side];
      }
      this.shapedHandTarget[side] = null;
      this.shapedHandAngle[side] = null;
      return null;
    }
    if (side === 'L' && this.shield) return this.shapeShieldCommand(raw, dt);
    const shoulder = this.shoulderWorld(side);
    const rawDx = raw.x - shoulder.x;
    const rawDy = raw.y - shoulder.y;
    const rawDistance = Math.hypot(rawDx, rawDy);
    const minReach = 0.18;
    const targetRadius = Math.max(minReach, Math.min(CFG.fighter.hand.reach, rawDistance));
    const localRawX = rawDx * this.facing;
    const wrappedRawAngle = rawDistance > 0.0001 ? Math.atan2(rawDy, localRawX) : 0;
    const current = this.shapedHandTarget[side] ?? this.handWorld(side).clone();
    const currentDx = (current.x - shoulder.x) * this.facing;
    const currentDy = current.y - shoulder.y;
    const currentRadius = Math.max(minReach, Math.min(
      CFG.fighter.hand.reach,
      Math.hypot(currentDx, currentDy),
    ));
    const currentAngle = this.shapedHandAngle[side] ?? Math.atan2(currentDy, currentDx);
    const controlScale = side === 'R' && this.weapon
      ? weaponControlSpeedScale(this.weapon.def.mass) * COMBAT_STYLES[this.combatStyle].handSpeedScale
      : 1;
    // Direct 360 control unwraps the absolute stick angle onto the branch
    // nearest the current hand path. Crossing +/-pi therefore continues
    // through the rear quadrant instead of reversing toward the front.
    let targetAngle = wrappedRawAngle + Math.round(
      (currentAngle - wrappedRawAngle) / (Math.PI * 2),
    ) * Math.PI * 2;
    if (side === 'R' && gesture) {
      if (gesture.id !== this.weaponGestureId) {
        this.weaponGestureId = gesture.id;
        this.weaponGestureBaseAngle = gesture.startAngle + Math.round(
          (currentAngle - gesture.startAngle) / (Math.PI * 2),
        ) * Math.PI * 2;
      }
      targetAngle = this.weaponGestureBaseAngle + gesture.travel;
    }
    const response = 1 - Math.exp(-CFG.locomotion.handTargetResponse * dt);
    const radialSpeed = CFG.locomotion.handTargetSpeed * controlScale;
    const radialDelta = Math.max(-radialSpeed * dt, Math.min(
      radialSpeed * dt,
      (targetRadius - currentRadius) * response,
    ));
    const overheadWeight = Math.max(0, Math.sin(currentAngle)) ** 2;
    const angularSpeed = CFG.locomotion.handTargetAngularSpeed * controlScale *
      (1 - (1 - CFG.locomotion.overheadAngularSpeedScale) * overheadWeight);
    const angularDelta = Math.max(-angularSpeed * dt, Math.min(
      angularSpeed * dt,
      (targetAngle - currentAngle) * response,
    ));
    const shapedRadius = currentRadius + radialDelta;
    const shapedAngle = currentAngle + angularDelta;
    const shaped = Vec2(
      shoulder.x + Math.cos(shapedAngle) * shapedRadius * this.facing,
      shoulder.y + Math.sin(shapedAngle) * shapedRadius,
    );
    this.shapedHandTarget[side] = shaped;
    this.shapedHandAngle[side] = shapedAngle;
    if (side === 'R') this.rebaseWeaponArmTurns();
    return shaped;
  }

  /**
   * Keep direct 360-degree control continuous without letting Box2D's
   * numerical joint angles grow forever. Rotations that differ by a complete
   * turn are the same physical pose, so rebasing the whole right-arm chain
   * and weapon by the same multiple of 2pi is visually and mechanically
   * lossless. It also prevents an invisible multi-turn shoulder error from
   * making a held weapon shake or try to crank backwards.
   */
  private rebaseWeaponArmTurns(): void {
    const handAngle = this.shapedHandAngle.R;
    if (handAngle === null || Math.abs(handAngle) < Math.PI * 2) return;
    const fullTurn = Math.PI * 2;
    const turnShift = Math.trunc(handAngle / fullTurn) * fullTurn;
    if (turnShift === 0) return;

    for (const partName of ['upperArmR', 'forearmR', 'handR'] as const) {
      const body = this.part(partName).body;
      body.setTransform(body.getPosition(), body.getAngle() - turnShift);
    }
    if (this.weapon) {
      for (const body of this.weapon.bodies) {
        body.setTransform(body.getPosition(), body.getAngle() - turnShift);
      }
    }

    this.shapedHandAngle.R = handAngle - turnShift;
    if (this.weaponAimAngle !== null) this.weaponAimAngle -= turnShift;
    if (this.weaponPointerAngle !== null) this.weaponPointerAngle -= turnShift;
    this.weaponGestureBaseAngle -= turnShift;
    if (this.weaponFollowThroughTarget !== null) this.weaponFollowThroughTarget -= turnShift;
    const shoulder = this.joints.find(joint => joint.name === 'shoulderR');
    if (shoulder) shoulder.currentTarget -= turnShift;
  }

  private shapeShieldCommand(raw: Vec2, dt: number): Vec2 {
    const current = this.shapedHandTarget.L ?? this.handWorld('L').clone();
    const response = 1 - Math.exp(-CFG.locomotion.handTargetResponse * dt);
    const maxAxisDelta = CFG.shield.controlAxisSpeed * SHIELD_STYLES[this.shieldStyle].axisSpeedScale *
      shieldControlSpeedScale(this.shield?.mass ?? CFG.shield.mass) * dt;
    const moveAxis = (value: number, target: number): number => value + Math.max(
      -maxAxisDelta,
      Math.min(maxAxisDelta, (target - value) * response),
    );
    const shaped = Vec2(moveAxis(current.x, raw.x), moveAxis(current.y, raw.y));
    this.shapedHandTarget.L = shaped;
    this.shapedHandAngle.L = null;
    return shaped;
  }

  /** Resolve the selected fighting prototype while locomotion and the physical
   * arm rig remain identical for an honest A/B/C comparison. */
  private weaponAimTarget(
    raw: Vec2 | null, dt: number, directLocalAngle: number | null,
  ): number | undefined {
    if (!this.weapon) return undefined;
    const previousPointerAngle = this.weaponPointerAngle;
    const shoulder = this.shoulderWorld('R');
    const edged = this.weapon.def.kind === 'dagger' || this.weapon.def.kind === 'sword';
    // Weapon and arm share one target. This removes the independent powered
    // wrist circle (the old crank-arm feel) while retaining full unwrapped
    // turns recorded by the pointer event stream.
    const directWorldAngle = raw && directLocalAngle !== null
      ? this.facing > 0 ? directLocalAngle : Math.PI - directLocalAngle
      : null;
    const result = directWorldAngle !== null ? {
      desiredWorldAngle: directWorldAngle,
      targetAngle: directWorldAngle,
      pointerAngle: directWorldAngle,
    } : resolveCombatAim(
      this.combatStyle,
      this.facing,
      shoulder,
      raw,
      this.shapedHandTarget.R,
      this.weapon.body.getAngle(),
      { targetAngle: this.weaponAimAngle, pointerAngle: this.weaponPointerAngle },
      edged,
    );
    if (raw && result.pointerAngle !== null) {
      if (previousPointerAngle === null) {
        this.weaponAimVelocity = 0;
        this.weaponAimVelocityHold = 0;
        this.weaponPointerSampleAge = this.age;
      } else {
        const delta = Math.atan2(
          Math.sin(result.pointerAngle - previousPointerAngle),
          Math.cos(result.pointerAngle - previousPointerAngle),
        );
        // Ignore sub-quarter-degree target jitter. Treating tiny active-ragdoll
        // shoulder corrections as deliberate pointer speed kept a nominally
        // held blade's motor near 12 rad/s even though its angle looked fixed.
        if (Math.abs(delta) > 0.003) {
          const sampleDuration = Math.max(dt, this.age - this.weaponPointerSampleAge);
          const measuredVelocity = Math.max(-CFG.weapon.worldAngularSpeedCap,
            Math.min(CFG.weapon.worldAngularSpeedCap, delta / sampleDuration));
          this.weaponAimVelocity += (measuredVelocity - this.weaponAimVelocity) * 0.65;
          this.weaponAimVelocityHold = 0.045;
          this.weaponPointerSampleAge = this.age;
        } else {
          this.weaponAimVelocityHold = Math.max(0, this.weaponAimVelocityHold - dt);
          if (this.weaponAimVelocityHold <= 0) {
            this.weaponAimVelocity *= Math.exp(-18 * dt);
          }
        }
      }
    } else {
      this.weaponAimVelocity = 0;
      this.weaponAimVelocityHold = 0;
      this.weaponPointerSampleAge = this.age;
    }
    this.weaponAimAngle = result.targetAngle;
    this.weaponPointerAngle = result.pointerAngle;
    return result.desiredWorldAngle;
  }

  private shieldForwardIntent(target: Vec2 | null): number {
    if (!this.shield || !target) return 0;
    const shoulder = this.shoulderWorld('L');
    const forwardReach = (target.x - shoulder.x) * this.facing;
    const span = Math.max(0.01, CFG.fighter.hand.reach - CFG.shield.shoveForwardThreshold);
    return Math.max(0, Math.min(1,
      (forwardReach - CFG.shield.shoveForwardThreshold) / span));
  }

  /** Turn a deliberate forward shield command into one bounded physical
   * contact impulse. The hand still has to bring the real shield fixture into
   * the opponent first; this only supplies the short whole-body drive that a
   * passive revolute grip cannot express on its own. */
  private applyShieldShove(target: Vec2 | null, brace: boolean, motorScale: number): void {
    if (!this.shield || this.shieldShoveCooldown > 0 || motorScale <= 0) return;
    const intent = this.shieldForwardIntent(target);
    if (intent <= 0.05) return;

    let edge = this.shield.body.getContactList() as any;
    while (edge) {
      const contact = edge.contact;
      if (contact?.isTouching?.()) {
        const fixtureA = contact.getFixtureA?.();
        const fixtureB = contact.getFixtureB?.();
        const otherFixture = fixtureA?.getBody?.() === this.shield.body ? fixtureB : fixtureA;
        const otherData = otherFixture?.getUserData?.() as any;
        if (otherData?.kind === 'part' && otherData.fighterId !== this.id) {
          const braceScale = brace ? CFG.shield.shoveBraceScale : 1;
          const profile = SHIELD_STYLES[this.shieldStyle];
          const impulse = CFG.shield.shoveImpulse * intent * braceScale * motorScale *
            profile.shoveImpulseScale;
          const direction = Vec2(this.facing * impulse, 0);
          const struckBody = otherFixture.getBody() as Body;
          let opponentPelvis: Body | null = null;
          const opponentBodies = new Set<Body>();
          let body = this.world.getBodyList();
          while (body) {
            for (let fixture = body.getFixtureList(); fixture; fixture = fixture.getNext()) {
              const data = fixture.getUserData() as any;
              if (data?.kind === 'part' && data.fighterId === otherData.fighterId) {
                opponentBodies.add(body);
                if (data.part === 'pelvis') opponentPelvis = body;
              }
            }
            body = body.getNext();
          }
          if (opponentPelvis === struckBody || !opponentPelvis) {
            struckBody.applyLinearImpulse(direction, struckBody.getWorldCenter(), true);
          } else {
            // Drive the full articulated mass together so planted feet and
            // balance motors cannot absorb the bash by folding one limb. A
            // small local share retains a readable contact reaction.
            const totalMass = [...opponentBodies].reduce((sum, opponentBody) =>
              sum + opponentBody.getMass(), 0);
            for (const opponentBody of opponentBodies) {
              const share = totalMass > 0 ? opponentBody.getMass() / totalMass : 0;
              opponentBody.applyLinearImpulse(Vec2(direction.x * 0.88 * share, 0),
                opponentBody.getWorldCenter(), true);
            }
            struckBody.applyLinearImpulse(Vec2(direction.x * 0.12, 0), struckBody.getWorldCenter(), true);
          }
          this.pelvis().applyLinearImpulse(Vec2(-direction.x * 0.12, 0),
            this.pelvis().getWorldCenter(), true);
          this.shieldShoveCooldown = CFG.shield.shoveCooldown * profile.shoveCooldownScale;
          this.shieldShoveCount++;
          this.lastShieldShoveImpulse = impulse;
          this.stamina.spend(CFG.shield.shoveStamina * intent * braceScale * profile.shoveStaminaScale);
          return;
        }
      }
      edge = edge.next;
    }
  }

  /** Remove solver-created idle hand spikes after constraints have resolved. */
  postStep(): void {
    const cap = this.stepPhase === 'idle' ? CFG.fighter.hand.idleSpeedCap : 0.9;
    const capBodySpeed = (body: Body, speedCap: number): void => {
      const v = body.getLinearVelocity();
      const speed = v.length();
      if (speed <= speedCap) return;
      const scale = speedCap / speed;
      body.setLinearVelocity(Vec2(v.x * scale, v.y * scale));
    };
    for (const side of ['L', 'R'] as const) {
      const stick = side === 'L' ? this.lastInput.left : this.lastInput.right;
      if (stick) continue;
      const hand = this.part(side === 'L' ? 'handL' : 'handR').body;
      capBodySpeed(hand, cap);
    }
    if (this.shield && !this.lastInput.left && this.stepPhase === 'idle') {
      capBodySpeed(this.shield.body, CFG.fighter.hand.idleSpeedCap);
      const omega = this.shield.body.getAngularVelocity();
      const angularCap = 0.45;
      if (Math.abs(omega) > angularCap) {
        this.shield.body.setAngularVelocity(Math.sign(omega) * angularCap);
      }
    }
    if (this.weapon) {
      // The powered handle is controlled for every weapon. Only the passive
      // downstream flail links and ball remain free to keep rotating.
      if (!this.lastInput.right && this.weaponFollowThroughTimer <= 0 && this.stepPhase === 'idle') {
        capBodySpeed(this.weapon.body, 0.10);
      }
      const weaponCap = this.lastInput.right || this.weaponFollowThroughTimer > 0
        ? CFG.weapon.worldAngularSpeedCap * weaponControlSpeedScale(this.weapon.def.mass)
        : CFG.weapon.idleWorldAngularSpeedCap;
      const omega = this.weapon.body.getAngularVelocity();
      if (Math.abs(omega) > weaponCap) {
        this.weapon.body.setAngularVelocity(Math.sign(omega) * weaponCap);
      }
    }
  }

  private defaultGuardTarget(side: 'L' | 'R'): Vec2 {
    // neutral guard: weapon hand forward and slightly raised, off hand in front of chest
    const s = this.shoulderWorld(side);
    const f = this.facing;
    return side === 'R'
      ? Vec2(s.x + 0.34 * f, s.y + 0.02)
      : Vec2(s.x + 0.30 * f, s.y - 0.12);
  }

  private applyFacingJointLimits(): void {
    const elbowLimits: [number, number] = this.facing === 1 ? [-0.08, 2.65] : [-2.65, 0.08];
    const kneeLimits: [number, number] = this.facing === 1 ? [-2.4, 0.04] : [-0.04, 2.4];
    for (const joint of this.joints) {
      if (joint.name.startsWith('elbow')) joint.joint.setLimits(elbowLimits[0], elbowLimits[1]);
      if (joint.name.startsWith('knee')) joint.joint.setLimits(kneeLimits[0], kneeLimits[1]);
    }
  }

  /** Turn the fighter to face a world x position (mirror stance targets). */
  faceToward(x: number): void {
    const dir: Facing = x >= this.pelvis().getPosition().x ? 1 : -1;
    if (dir === this.facing) return;
    this.facing = dir;
    for (const j of this.joints) {
      if (j.name.startsWith('shoulder') || j.name.startsWith('elbow') || j.name.startsWith('hip') ||
          j.name.startsWith('knee') ||
          j.name.startsWith('ankle')) {
        j.stanceTarget = -j.stanceTarget;
      }
    }
    this.applyFacingJointLimits();
  }

  /** Rough stability check used by AI/autotest. */
  torsoAngle(): number { return this.torso().getAngle(); }
  handCommandDiagnostics(side: 'L' | 'R'): Vec2 | null {
    return this.shapedHandTarget[side]?.clone() ?? null;
  }
  shieldShoveDiagnostics(): { style: ShieldStyleId; count: number; lastImpulse: number; cooldown: number } {
    return {
      style: this.shieldStyle,
      count: this.shieldShoveCount,
      lastImpulse: this.lastShieldShoveImpulse,
      cooldown: this.shieldShoveCooldown,
    };
  }
  jointTargetDiagnostics(name: string): number | null {
    return this.joints.find(j => j.name === name)?.currentTarget ?? null;
  }
  pelvisTargetDiagnostics(): number { return this.pelvisStepTargetX; }
  pelvisTargetVelocityDiagnostics(): number { return this.pelvisTargetVelocityX; }

  stepPlacementDiagnostics(): { length: number; supportX: number; targetX: number; direction: number } {
    return {
      length: Math.abs(this.swingTargetX - this.supportAnchorX),
      supportX: this.supportAnchorX,
      targetX: this.swingTargetX,
      direction: this.stepDir,
    };
  }
  consumeFootPlantEvents(): FootPlantEvent[] {
    if (this.pendingFootPlants.length === 0) return [];
    const events = this.pendingFootPlants;
    this.pendingFootPlants = [];
    return events;
  }
  gaitDiagnostics(): { phase: string; support: 'L' | 'R'; swing: 'L' | 'R'; direction: number; progress: number; blockedDirection: number; combatReplant: boolean; timer: number; rails: { L: boolean; R: boolean } } {
    return {
      phase: this.stepPhase,
      support: this.supportSide,
      swing: this.swingSide,
      direction: this.stepDir,
      progress: this.stepPhase === 'idle' ? 0 : Math.min(1, this.stepTimer / CFG.locomotion.stepDuration),
      blockedDirection: this.blockedMoveDir,
      combatReplant: this.combatReplant,
      timer: this.stepTimer,
      rails: { L: !!this.footRail.L, R: !!this.footRail.R },
    };
  }
  /** Browser-live motion telemetry. Used only by the opt-in QA surface; all
   * values come from resolved physical bodies after the world step. */
  motionDiagnostics(): Record<string, unknown> {
    const body = (name: PartName) => {
      const b = this.part(name).body;
      const p = b.getPosition();
      const v = b.getLinearVelocity();
      return { x: p.x, y: p.y, angle: b.getAngle(), vx: v.x, vy: v.y, omega: b.getAngularVelocity() };
    };
    const command = (side: 'L' | 'R') => {
      const target = this.shapedHandTarget[side];
      return target ? { x: target.x, y: target.y } : null;
    };
    const weaponTip = this.weapon
      ? this.weapon.tipBody.getWorldPoint(this.weapon.tipLocal)
      : null;
    const weaponAxis = this.weapon
      ? this.weapon.tipBody.getWorldVector(Vec2(1, 0))
      : null;
    return {
      standing: this.isStanding(),
      gait: this.gaitDiagnostics(),
      pelvis: body('pelvis'),
      torso: body('torso'),
      head: body('head'),
      thighL: body('thighL'),
      thighR: body('thighR'),
      shinL: body('shinL'),
      shinR: body('shinR'),
      footL: body('footL'),
      footR: body('footR'),
      handL: body('handL'),
      handR: body('handR'),
      commandL: command('L'),
      commandR: command('R'),
      handForce: this.lastHandForce,
      tipSpeed: this.lastTipSpeed,
      weapon: this.weapon ? {
        mass: this.weapon.def.mass,
        controlSpeedScale: weaponControlSpeedScale(this.weapon.def.mass),
        angle: this.weapon.body.getAngle(),
        omega: this.weapon.body.getAngularVelocity(),
        gripAngle: this.weapon.gripJoint?.getJointAngle?.() ?? 0,
        gripSpeed: this.weapon.gripJoint?.getJointSpeed?.() ?? 0,
        aimTarget: this.weaponAimAngle,
        aimVelocity: this.weaponAimVelocity,
        gestureTravel: this.weaponGestureTravel,
        followThroughTarget: this.weaponFollowThroughTarget,
        pointerAngle: this.weaponPointerAngle,
        tip: weaponTip ? { x: weaponTip.x, y: weaponTip.y } : null,
        axis: weaponAxis ? { x: weaponAxis.x, y: weaponAxis.y } : null,
      } : null,
      shield: this.shield ? {
        mass: this.shield.mass,
        controlSpeedScale: shieldControlSpeedScale(this.shield.mass),
        angle: this.shield.body.getAngle(),
        omega: this.shield.body.getAngularVelocity(),
      } : null,
      pelvisTargetX: this.pelvisStepTargetX,
      pelvisTargetVelocityX: this.pelvisTargetVelocityX,
      stepPlacement: this.stepPlacementDiagnostics(),
      swingIK: {
        blend: this.activeSwingIKBlend,
        requested: this.activeSwingIKRequested ? {
          x: this.activeSwingIKRequested.x,
          y: this.activeSwingIKRequested.y,
        } : null,
        projected: this.activeSwingIKTarget ? {
          x: this.activeSwingIKTarget.x,
          y: this.activeSwingIKTarget.y,
        } : null,
        solve: this.activeSwingIKDebug,
      },
      joints: Object.fromEntries(this.joints.map(j => [j.name, {
        angle: j.joint.getJointAngle(),
        speed: j.joint.getJointSpeed(),
        target: j.currentTarget,
      }])),
    };
  }
  isStanding(): boolean {
    return !this.dead && !this.stamina.collapsed && Math.abs(this.torsoAngle()) < 1.05 &&
      this.pelvis().getPosition().y > 0.52;
  }
}
