// Physical stab embedding and extraction.
// A sufficiently axial piercing impact drives the blade through a bounded
// insertion rail, then creates a real weld between the blade and struck body.
// The weld only releases after a sustained, forceful pull back along the blade
// axis; ordinary swings remain constrained by the victim.
import { Body, PrismaticJoint, Vec2, WeldJoint, World } from 'planck';
import { CFG } from '../config';
import { DamageEvent, FighterInput } from '../types';
import { WeaponInstance } from './Weapons';

interface PendingPenetration {
  event: DamageEvent;
  weapon: WeaponInstance;
  targetBody: Body;
  material: string;
  axis: Vec2;
}

export interface EmbeddedPenetration {
  attackerId: number;
  defenderId: number;
  weapon: WeaponInstance;
  targetBody: Body;
  joint: PrismaticJoint | WeldJoint;
  stage: 'inserting' | 'embedded';
  targetLocalPoint: Vec2;
  insertionDepth: number;
  insertedDepth: number;
  insertionTime: number;
  embeddedTime: number;
  pullTime: number;
  defenderEscapeTime: number;
  maxPullForce: number;
  lastAxialForce: number;
  lastPullDistance: number;
  lastDefenderMove: number;
}

export interface PenetrationDiagnostics {
  attackerId: number;
  defenderId: number;
  stage: 'inserting' | 'embedded';
  insertionDepth: number;
  insertedDepth: number;
  insertionTime: number;
  embeddedTime: number;
  pullTime: number;
  defenderEscapeTime: number;
  maxPullForce: number;
  axialForce: number;
  pullDistance: number;
  defenderMove: number;
}

export interface PenetrationFeedback {
  attackerId: number;
  defenderId: number;
  x: number;
  y: number;
  force: number;
}

function setWeaponEmbedded(weapon: WeaponInstance, embedded: boolean): void {
  for (const body of weapon.bodies) {
    for (let fixture = body.getFixtureList(); fixture; fixture = fixture.getNext()) {
      const data: any = fixture.getUserData();
      if (data?.kind === 'weaponSurface') {
        data.embedded = embedded;
        // Once a valid axial stab is accepted, the blade must be able to pass
        // through the struck fixture instead of being held outside by contact
        // resolution. The insertion joint below bounds that travel.
        fixture.setSensor(embedded);
      }
    }
  }
}

export class PenetrationSystem {
  private pending: PendingPenetration[] = [];
  private embedded = new Map<string, EmbeddedPenetration>();
  onEmbed: (event: PenetrationFeedback) => void = () => {};
  onExtract: (event: PenetrationFeedback) => void = () => {};

  clear(): void {
    this.pending.length = 0;
    this.embedded.clear();
  }

  count(): number { return this.embedded.size; }
  isEmbedded(instanceId: string): boolean { return this.embedded.has(instanceId); }
  insertingCount(): number {
    return [...this.embedded.values()].filter(record => record.stage === 'inserting').length;
  }
  lockedCount(): number {
    return [...this.embedded.values()].filter(record => record.stage === 'embedded').length;
  }
  maxInsertedDepth(): number {
    return Math.max(0, ...[...this.embedded.values()].map(record => record.insertedDepth));
  }
  diagnostics(): PenetrationDiagnostics[] {
    return [...this.embedded.values()].map(record => ({
      attackerId: record.attackerId,
      defenderId: record.defenderId,
      stage: record.stage,
      insertionDepth: record.insertionDepth,
      insertedDepth: record.insertedDepth,
      insertionTime: record.insertionTime,
      embeddedTime: record.embeddedTime,
      pullTime: record.pullTime,
      defenderEscapeTime: record.defenderEscapeTime,
      maxPullForce: record.maxPullForce,
      axialForce: record.lastAxialForce,
      pullDistance: record.lastPullDistance,
      defenderMove: record.lastDefenderMove,
    }));
  }

  queue(event: DamageEvent, weapon: WeaponInstance, targetBody: Body, material = 'flesh'): boolean {
    if (event.type !== 'pierce' || weapon.def.kind === 'flail' || weapon.def.kind === 'mace') return false;
    if (this.embedded.has(weapon.instanceId) || this.pending.some(p => p.weapon.instanceId === weapon.instanceId)) return false;
    if (event.energy < CFG.penetration.minEnergy ||
        (event.impactSpeed ?? event.relativeSpeed ?? 0) < CFG.penetration.minSpeed) return false;
    if (!['flesh', 'cloth', 'padded'].includes(material)) return false;
    // Small extremities should take the hit but never become a hard weld that
    // disables both fighters because a blade grazed a fingertip or shoe.
    if (['handL', 'handR', 'footL', 'footR'].includes(event.part)) return false;

    const axis = weapon.tipBody.getWorldVector(Vec2(1, 0));
    // Penetration is determined by how the blade actually moved, not by a
    // polygon edge normal that can point sideways at shoulders and curved
    // body corners. The contact normal is only a fallback for synthetic or
    // stationary impact events without a valid relative-velocity direction.
    const hasVelocityDirection = Math.hypot(event.dirX ?? 0, event.dirY ?? 0) > 0.0001;
    const direction = hasVelocityDirection
      ? Vec2(event.dirX ?? 0, event.dirY ?? 0)
      : Vec2(event.normalX ?? 0, event.normalY ?? 0);
    const directionLength = direction.length();
    const alignment = directionLength > 0.0001
      ? (axis.x * direction.x + axis.y * direction.y) / directionLength
      : -1;
    if (alignment < CFG.penetration.minAxialAlignment) return false;

    this.pending.push({ event, weapon, targetBody, material, axis: axis.clone() });
    return true;
  }

  /** Create queued joints after World.step(), when Planck is no longer locked. */
  flush(world: World): void {
    for (const request of this.pending.splice(0)) {
      if (this.embedded.has(request.weapon.instanceId)) continue;
      const point = Vec2(request.event.x, request.event.y);
      const bladeLength = request.weapon.def.length - request.weapon.def.bladeStart;
      const insertionDepth = Math.max(CFG.penetration.insertionDepthMin,
        Math.min(CFG.penetration.insertionDepthMax,
          bladeLength * CFG.penetration.insertionBladeFraction));
      const joint = world.createJoint(PrismaticJoint({
        collideConnected: false,
        enableLimit: true,
        lowerTranslation: 0,
        upperTranslation: insertionDepth,
        enableMotor: true,
        motorSpeed: CFG.penetration.insertionSpeed,
        maxMotorForce: CFG.penetration.insertionForce,
      }, request.targetBody, request.weapon.tipBody, point, request.axis)) as PrismaticJoint;
      const record: EmbeddedPenetration = {
        attackerId: request.event.attackerId,
        defenderId: request.event.defenderId,
        weapon: request.weapon,
        targetBody: request.targetBody,
        joint,
        stage: 'inserting',
        targetLocalPoint: request.targetBody.getLocalPoint(point),
        insertionDepth,
        insertedDepth: 0,
        insertionTime: 0,
        embeddedTime: 0,
        pullTime: 0,
        defenderEscapeTime: 0,
        maxPullForce: 0,
        lastAxialForce: 0,
        lastPullDistance: 0,
        lastDefenderMove: 0,
      };
      this.embedded.set(request.weapon.instanceId, record);
      setWeaponEmbedded(request.weapon, true);
      this.onEmbed({
        attackerId: record.attackerId,
        defenderId: record.defenderId,
        x: point.x,
        y: point.y,
        force: 0,
      });
    }
  }

  /** Evaluate extraction after a physics step so joint reaction force is real. */
  update(world: World, dt: number, inputFor: (fighterId: number) => FighterInput | null): void {
    const releases: EmbeddedPenetration[] = [];
    for (const record of this.embedded.values()) {
      record.embeddedTime += dt;
      if (record.stage === 'inserting') {
        const insertion = record.joint as PrismaticJoint;
        record.insertionTime += dt;
        record.insertedDepth = Math.max(record.insertedDepth,
          Math.max(0, insertion.getJointTranslation()));
        const reachedDepth = record.insertedDepth >=
          record.insertionDepth * CFG.penetration.insertionLockRatio;
        if (reachedDepth || record.insertionTime >= CFG.penetration.insertionMaxSec) {
          const woundPoint = record.targetBody.getWorldPoint(record.targetLocalPoint);
          world.destroyJoint(insertion);
          record.joint = world.createJoint(WeldJoint(
            { collideConnected: false }, record.targetBody, record.weapon.tipBody, woundPoint,
          )) as WeldJoint;
          record.stage = 'embedded';
        }
        continue;
      }
      const attackerInput = inputFor(record.attackerId);
      const defenderInput = inputFor(record.defenderId);
      const target = attackerInput?.right;
      const anchor = record.joint.getAnchorB();
      const axis = record.weapon.tipBody.getWorldVector(Vec2(1, 0));
      const reaction = record.joint.getReactionForce(1 / Math.max(dt, 1e-6));
      const axialForce = Math.abs(reaction.x * axis.x + reaction.y * axis.y);
      record.maxPullForce = Math.max(record.maxPullForce, axialForce);
      const pullDistance = target
        ? (target.x - anchor.x) * axis.x + (target.y - anchor.y) * axis.y
        : 0;
      record.lastAxialForce = axialForce;
      record.lastPullDistance = pullDistance;
      const pullingOut = !!target && pullDistance <= -CFG.penetration.pullDistance &&
        axialForce >= CFG.penetration.minPullForce;
      record.pullTime = pullingOut
        ? record.pullTime + dt
        : Math.max(0, record.pullTime - dt * 2);

      // The old lock could only be released by the attacker's weapon input,
      // leaving the impaled player without agency. A defender who deliberately
      // moves away along the blade axis now builds a separate breakaway timer.
      // With no retreat input the weld remains intact, so a clean stab can
      // still hold a passive opponent on the blade.
      const defenderMove = defenderInput?.move || defenderInput?.step || 0;
      record.lastDefenderMove = defenderMove;
      const retreatingAlongBlade = Math.abs(defenderMove) > 0.01 &&
        defenderMove * axis.x >= 0.18;
      const defenderBreakingAway = retreatingAlongBlade &&
        axialForce >= CFG.penetration.defenderEscapeForce;
      record.defenderEscapeTime = defenderBreakingAway
        ? record.defenderEscapeTime + dt
        : Math.max(0, record.defenderEscapeTime - dt * 1.5);
      const deadlockTimeout = record.embeddedTime >= CFG.penetration.maxEmbeddedSec;
      if (record.pullTime >= CFG.penetration.pullHoldSec ||
          record.defenderEscapeTime >= CFG.penetration.defenderEscapeHoldSec || deadlockTimeout) {
        releases.push(record);
      }
    }

    for (const record of releases) {
      const anchor = record.joint.getAnchorB();
      const axis = record.weapon.tipBody.getWorldVector(Vec2(1, 0));
      world.destroyJoint(record.joint);
      this.embedded.delete(record.weapon.instanceId);
      setWeaponEmbedded(record.weapon, false);
      record.weapon.tipBody.applyLinearImpulse(
        Vec2(-axis.x * CFG.penetration.releaseImpulse, -axis.y * CFG.penetration.releaseImpulse),
        record.weapon.tipBody.getWorldCenter(), true,
      );
      this.onExtract({
        attackerId: record.attackerId,
        defenderId: record.defenderId,
        x: anchor.x,
        y: anchor.y,
        force: record.maxPullForce,
      });
    }
  }
}
