// Continuous reference curves for one physical walking step.
// A foot remains planted for the first 7% and last 10% of its swing step.
// Across two alternating steps that gives each foot roughly 58.5% stance and
// 41.5% swing,
// matching the broad timing of a human walk without keyframing rigid bodies.

export interface GaitPose {
  swingHip: number;
  supportHip: number;
  swingKnee: number;
  supportKnee: number;
  swingAnkle: number;
  supportAnkle: number;
  footProgress: number;
  footLift: number;
  pelvisProgress: number;
  pelvisLift: number;
  torsoLean: number;
  pelvisRock: number;
  thoraxCounterRock: number;
  armCounterSwing: number;
  armElbowFlex: number;
}

export interface GaitTrunkTargets {
  pelvis: number;
  thorax: number;
  head: number;
  spine: number;
  neck: number;
}

export interface GaitArmJointOffsets {
  shoulderL: number;
  shoulderR: number;
  elbowL: number;
  elbowR: number;
}

export const TOE_OFF_PHASE = 0.07;
export const HEEL_STRIKE_PHASE = 0.90;

export function clamp01(value: number): number {
  return Math.max(0, Math.min(1, value));
}

export function smootherstep(value: number): number {
  const x = clamp01(value);
  return x * x * x * (x * (x * 6 - 15) + 10);
}

/** Bound a nominal heel-to-heel step before the physical foot-placement
 * controller applies it. Velocity adaptation is introduced behind this pure
 * helper so its balance response can be regression-tested independently. */
export function velocityAwareStepLength(
  nominal: number, directionalPelvisSpeed: number, velocityGain: number,
  minimum: number, maximum: number,
): number {
  const speed = Number.isFinite(directionalPelvisSpeed) ? directionalPelvisSpeed : 0;
  const gain = Number.isFinite(velocityGain) ? Math.max(0, velocityGain) : 0;
  const requested = nominal + speed * gain;
  return Math.max(minimum, Math.min(maximum, requested));
}

type PhaseKey = readonly [phase: number, value: number];

/** Smooth, zero-slope joins between biomechanical phase landmarks. Keeping
 * the values positive here makes the flexion profile readable; the side-view
 * rig applies its negative anatomical knee direction below. */
function phaseProfile(phase: number, keys: readonly PhaseKey[]): number {
  const t = clamp01(phase);
  for (let i = 1; i < keys.length; i++) {
    const [endPhase, endValue] = keys[i];
    if (t <= endPhase) {
      const [startPhase, startValue] = keys[i - 1];
      const u = smootherstep((t - startPhase) / Math.max(1e-6, endPhase - startPhase));
      return startValue + (endValue - startValue) * u;
    }
  }
  return keys[keys.length - 1][1];
}

// The planted knee first yields under load, extends through mid-stance, then
// starts the next double-support period nearly straight. Once that leg becomes
// the outgoing swing leg it flexes decisively before toe-off and reaches its
// clearance peak in early/mid swing. This replaces the old single sine bulge,
// which was most crouched at mid-stance and rigid during push-off.
const SUPPORT_KNEE_FLEXION: readonly PhaseKey[] = [
  [0.00, 0.080],
  [0.18, 0.200],
  [0.55, 0.055],
  [0.78, 0.045],
  [1.00, 0.180],
];
const SWING_KNEE_FLEXION: readonly PhaseKey[] = [
  [0.00, 0.180],
  [TOE_OFF_PHASE, 0.480],
  [0.45, 0.780],
  [0.72, 0.380],
  [1.00, 0.080],
];

/** Forward centre-of-mass progression with a small step-frequency velocity
 * ripple. Its derivative is 1 - r*cos(2*pi*t), so momentum never drops to
 * zero and both sides of a foot swap meet at the same positive speed. */
export function continuousPelvisProgress(value: number, ripple = 0.08): number {
  const t = clamp01(value);
  const r = Math.max(0, Math.min(0.45, ripple));
  return t - r / (Math.PI * 2) * Math.sin(Math.PI * 2 * t);
}

/** Side-view projection of the pelvis/thorax counter-rotation that accompanies
 * human gait. Alternating the swing side preserves the end pose exactly at a
 * foot swap while the head remains much calmer than the trunk. */
export function gaitTrunkTargets(pose: GaitPose, swingSide: 'L' | 'R'): GaitTrunkTargets {
  const sidePhase = swingSide === 'R' ? 1 : -1;
  const pelvis = pose.torsoLean * 0.35 + pose.pelvisRock * sidePhase;
  const thorax = pose.torsoLean + pose.thoraxCounterRock * sidePhase;
  const head = pose.torsoLean * 0.12;
  return {
    pelvis,
    thorax,
    head,
    spine: thorax - pelvis,
    neck: head - thorax,
  };
}

/** Phase-locked arm swing with asymmetric elbow flexion. The arm travelling
 * forward shortens slightly while the trailing arm extends, matching the
 * human tendency to reduce distal inertia without breaking continuity when
 * the leg roles swap. Offsets are mirrored by anatomical facing. */
export function gaitArmJointOffsets(
  pose: GaitPose, swingSide: 'L' | 'R', facing: -1 | 1,
): GaitArmJointOffsets {
  const shoulderL = swingSide === 'L' ? pose.armCounterSwing : -pose.armCounterSwing;
  const shoulderR = -shoulderL;
  const forwardL = clamp01((shoulderL * facing / 0.19 + 1) * 0.5) * 2 - 1;
  const forwardR = -forwardL;
  const elbowBias = 0.055;
  return {
    shoulderL,
    shoulderR,
    elbowL: (pose.armElbowFlex + elbowBias * forwardL) * facing,
    elbowR: (pose.armElbowFlex + elbowBias * forwardR) * facing,
  };
}

export function gaitPose(phase: number, direction: -1 | 1, stepHeight: number): GaitPose {
  const t = clamp01(phase);
  const swingT = clamp01((t - TOE_OFF_PHASE) / (HEEL_STRIKE_PHASE - TOE_OFF_PHASE));
  const swingU = smootherstep(swingT);
  const bodyU = smootherstep(t);
  const hipAmplitude = 0.58;
  const guardedArmAmplitude = 0.15;
  const swingArc = Math.pow(Math.sin(Math.PI * swingT), 1.15);
  // A readable sagittal foot rocker: the trailing foot leaves toe-down, the
  // airborne foot dorsiflexes, and the heel arrives with the toe raised. The
  // old support foot performs the inverse curve, so both angles join exactly
  // when the leg roles swap.
  const swingFootAngle = (-0.18 + 0.42 * smootherstep(swingT)) * direction;
  const supportLoading = smootherstep(t / 0.32);
  // Heel rise belongs to terminal double support, once the opposite foot can
  // accept body weight. Asking for it during single support left the box solver
  // no physical way to lift the heel without toppling the whole fighter.
  const supportPushOff = smootherstep((t - 0.84) / 0.16);
  const supportFootAngle = (0.24 * (1 - supportLoading) - 0.18 * supportPushOff) * direction;

  return {
    // These endpoints are deliberately symmetric. After the feet swap, the
    // old support target exactly equals the new swing start (and vice versa).
    swingHip: (-hipAmplitude + 2 * hipAmplitude * swingU) * direction,
    supportHip: (hipAmplitude - 2 * hipAmplitude * bodyU) * direction,
    swingKnee: -phaseProfile(t, SWING_KNEE_FLEXION),
    supportKnee: -phaseProfile(t, SUPPORT_KNEE_FLEXION),
    swingAnkle: swingFootAngle,
    supportAnkle: supportFootAngle,
    footProgress: swingU,
    footLift: stepHeight * swingArc,
    // Healthy gait redirects horizontal momentum during double support; it
    // does not stop the body before every heel strike. Keep a gentle speed
    // ripple while preserving positive, equal velocity across step boundaries.
    pelvisProgress: continuousPelvisProgress(t),
    // The centre of mass is lowest in double support and highest near
    // mid-stance. The small amplitude keeps the armored silhouette grounded.
    pelvisLift: 0.018 * Math.sin(Math.PI * t),
    torsoLean: -0.055 * direction * Math.sin(Math.PI * t),
    // The real motion is predominantly transverse. In this side-view rig a
    // restrained projected rock prevents the pelvis, thorax, and head from
    // reading as one rigid armor column. The two endpoints are antisymmetric;
    // gaitTrunkTargets() combines that with the alternating swing side.
    pelvisRock: (0.032 - 0.064 * bodyU) * direction,
    thoraxCounterRock: (-0.026 + 0.052 * bodyU) * direction,
    // Same-side arm travels opposite its leg. Swapping the swing/support roles
    // at the next step makes the endpoint join exactly, producing a complete
    // 1.32 Hz arm cycle at the normal 0.38 s step duration.
    armCounterSwing: (guardedArmAmplitude - 2 * guardedArmAmplitude * bodyU) * direction,
    armElbowFlex: 0.075 * Math.pow(Math.sin(Math.PI * t), 2),
  };
}
