// Assets: bitmap art loading + manifest. Node-safe at import time: the module
// never touches DOM/fetch at import; Assets.load() must be called (browser only).
// If loading fails (offline, file://, missing files) every field stays null and
// the renderer falls back to greybox shapes.

export interface SpriteRect { x: number; y: number; w: number; h: number }

export interface Atlas {
  img: CanvasImageSource;
  rects: Record<string, SpriteRect>;
}

export interface ArenaArt {
  img: HTMLImageElement;
  horizon: number; // fraction of image height where ground starts
}

interface ArenaEntry { image: string; horizon: number }

interface Manifest {
  arenas: Record<string, ArenaEntry>;
  fighterAtlas: string;
  armorFighterAtlases?: Record<string, string>;
  unarmoredFighterAtlas?: string;
  unarmoredFighterCoarseAtlas?: string;
  enemyFighterAtlases?: Record<string, string>;
  weaponsAtlas: string;
  shield?: string;
  flailParts?: { handle: string; link: string; ball: string };
}

interface AtlasJson {
  keyedImage: string;
  rects: Record<string, SpriteRect>;
  removeLightNeutralBackdrop?: boolean;
}

export type ArenaId = 'bramble' | 'copper' | 'rime' | 'ember' | 'chunky';

export function arenaArtId(realm: string): string {
  return realm in { bramble: true, copper: true, rime: true, ember: true, chunky: true } ? realm : 'bramble';
}

export class Assets {
  fighter: Atlas | null = null;
  armorFighters: Record<string, Atlas> = {};
  unarmoredFighter: Atlas | null = null;
  unarmoredFighterCoarse: Atlas | null = null;
  enemyFighters: Record<string, Atlas> = {};
  weapons: Atlas | null = null;
  shield: HTMLImageElement | null = null;
  flail: { handle: HTMLImageElement; link: HTMLImageElement; ball: HTMLImageElement } | null = null;
  arenas: Record<string, ArenaArt> = {};
  ready = false;

  static async load(baseUrl: string): Promise<Assets> {
    const a = new Assets();
    if (typeof document === 'undefined' || typeof fetch === 'undefined') return a;
    const url = (p: string) => new URL(p, baseUrl).toString();
    const getJson = async <T>(p: string): Promise<T | null> => {
      try {
        const r = await fetch(url(p));
        if (!r.ok) return null;
        return (await r.json()) as T;
      } catch { return null; }
    };
    const getImg = (p: string): Promise<HTMLImageElement | null> =>
      new Promise(resolve => {
        try {
          const img = new Image();
          img.onload = () => resolve(img);
          img.onerror = () => resolve(null);
          img.src = url(p);
        } catch { resolve(null); }
      });
    const removeLightNeutralBackdrop = (img: HTMLImageElement): HTMLCanvasElement => {
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth || img.width;
      canvas.height = img.naturalHeight || img.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return canvas;
      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(img, 0, 0);
      const pixels = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = pixels.data;
      for (let i = 0; i < data.length; i += 4) {
        const r = data[i], g = data[i + 1], b = data[i + 2];
        const hi = Math.max(r, g, b), lo = Math.min(r, g, b);
        // The generated sheet contains an opaque neutral checkerboard. Skin,
        // leather, hair, and outlines all have materially higher chroma or
        // lower luminance, so this removes the plate without erasing the art.
        if (lo >= 218 && hi - lo <= 12) data[i + 3] = 0;
      }
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.putImageData(pixels, 0, 0);
      return canvas;
    };
    const loadAtlas = async (dir: string, jsonName: string): Promise<Atlas | null> => {
      const j = await getJson<AtlasJson>(`${dir}/${jsonName}`);
      if (!j) return null;
      const img = await getImg(`${dir}/${j.keyedImage}`);
      if (!img) return null;
      return { img: j.removeLightNeutralBackdrop ? removeLightNeutralBackdrop(img) : img, rects: j.rects };
    };

    const manifest = await getJson<Manifest>('manifest.json');
    if (!manifest) return a;

    const [fighter, unarmoredFighter, unarmoredFighterCoarse, weapons, shield, flailHandle, flailLink, flailBall] = await Promise.all([
      loadAtlas('sprites', manifest.fighterAtlas),
      manifest.unarmoredFighterAtlas ? loadAtlas('sprites', manifest.unarmoredFighterAtlas) : Promise.resolve(null),
      manifest.unarmoredFighterCoarseAtlas ? loadAtlas('sprites', manifest.unarmoredFighterCoarseAtlas) : Promise.resolve(null),
      loadAtlas('sprites', manifest.weaponsAtlas),
      manifest.shield ? getImg(`sprites/${manifest.shield}`) : Promise.resolve(null),
      manifest.flailParts ? getImg(`sprites/${manifest.flailParts.handle}`) : Promise.resolve(null),
      manifest.flailParts ? getImg(`sprites/${manifest.flailParts.link}`) : Promise.resolve(null),
      manifest.flailParts ? getImg(`sprites/${manifest.flailParts.ball}`) : Promise.resolve(null),
    ]);
    a.fighter = fighter;
    a.unarmoredFighter = unarmoredFighter;
    a.unarmoredFighterCoarse = unarmoredFighterCoarse;
    a.weapons = weapons;
    a.shield = shield;
    if (flailHandle && flailLink && flailBall) {
      a.flail = { handle: flailHandle, link: flailLink, ball: flailBall };
    }

    const armorAtlases = await Promise.all(
      Object.entries(manifest.armorFighterAtlases ?? {}).map(async ([material, jsonName]) =>
        [material, await loadAtlas('sprites', jsonName)] as const),
    );
    for (const [material, atlas] of armorAtlases) {
      if (atlas) a.armorFighters[material] = atlas;
    }

    const enemyAtlases = await Promise.all(
      Object.entries(manifest.enemyFighterAtlases ?? {}).map(async ([appearance, jsonName]) =>
        [appearance, await loadAtlas('sprites', jsonName)] as const),
    );
    for (const [appearance, atlas] of enemyAtlases) {
      if (atlas) a.enemyFighters[appearance] = atlas;
    }

    await Promise.all(Object.entries(manifest.arenas).map(async ([id, e]) => {
      const img = await getImg(`bg/${e.image}`);
      if (img) a.arenas[id] = { img, horizon: e.horizon };
    }));

    a.ready = !!(a.fighter || a.weapons || a.flail || Object.keys(a.arenas).length);
    return a;
  }
}
