/** The combat grammar belongs to the equipped weapon, never to a global mode. */
export function combatStyleForWeapon(weaponId: string): CombatStyleId {
  if (weaponId === 'sword') return 'classic';
  if (weaponId === 'flail') return 'momentum';
  if (weaponId === 'mace') return 'committed';
  return 'guided';
}

export interface CombatAimState {
  targetAngle: number | null;
  pointerAngle: number | null;
}

export interface CombatAimResult extends CombatAimState {
  desiredWorldAngle: number | undefined;
}

export function normalizeCombatStyle(value: unknown): CombatStyleId {
  return value === 'classic' || value === 'momentum' || value === 'guided' || value === 'committed'
    ? value
    : 'guided';
}

export function emptyCombatAimState(): CombatAimState {
  return { targetAngle: null, pointerAngle: null };
}

/** Resolve every weapon through one direct absolute-360 command. Weapon mass
 * and physical construction own the differences; no weapon gets a separate
 * gesture multiplier, authored path, angle lanes, or release mode. */
export function resolveCombatAim(
  _style: CombatStyleId,
  facing: 1 | -1,
  shoulder: Vec2,
  rawTarget: Vec2 | null,
  shapedTarget: Vec2 | null,
  bodyAngle: number,
  previous: CombatAimState,
  _isEdged: boolean,
): CombatAimResult {
  if (!rawTarget) {
    const heldAngle = previous.pointerAngle !== null
      ? bodyAngle
      : previous.targetAngle ?? bodyAngle;
    return { desiredWorldAngle: heldAngle, targetAngle: heldAngle, pointerAngle: null };
  }

  const pointerAngle = Math.atan2(rawTarget.y - shoulder.y, rawTarget.x - shoulder.x);
  const base = previous.targetAngle ?? bodyAngle;
  const targetAngle = pointerAngle + Math.round((base - pointerAngle) / (Math.PI * 2)) * Math.PI * 2;
  return { desiredWorldAngle: targetAngle, targetAngle, pointerAngle };
}
