// Stamina: tracks drain from physical work, regen after calm, collapse/recover.
import { CFG } from '../config';

export class Stamina {
  max: number;
  value: number;
  collapsed = false;
  private calmTimer = 0;
  private s = CFG.stamina;

  constructor(equipmentMassKg: number) {
    const penalty = this.s.equipMassPenalty * Math.max(0, equipmentMassKg - this.s.comfortMass);
    this.max = Math.max(40, this.s.base - penalty);
    this.value = this.max;
  }

  /**
   * Per-step update.
   * @param handForce    average magnitude of hand-control forces this step (newtons)
   * @param handSpeedSq  sum of squared hand velocities this step ((m/s)^2)
   * @param activeExertion true for a held brace or another deliberate effort
   *                       whose cost is applied separately but must stop regen
   */
  update(dt: number, handForce: number, handSpeedSq: number, activeExertion = false): void {
    const rate = handForce * this.s.drainPerNewton + handSpeedSq * this.s.drainHandSpeedSq;
    if (this.collapsed) {
      // Collapse is a forced recovery state: we are already at rock bottom,
      // passive twitching/gravity should not stall recovery. Always regen.
      this.calmTimer = 0;
      this.value = Math.min(this.max, this.value + this.s.regenPerSec * dt);
    } else if (rate > this.s.calmRateThreshold || activeExertion) {
      this.calmTimer = 0;
      this.value = Math.max(this.s.collapseAt, this.value - rate * dt);
    } else {
      this.calmTimer += dt;
      if (this.calmTimer >= this.s.regenDelay) {
        this.value = Math.min(this.max, this.value + this.s.regenPerSec * dt);
      }
    }
    if (!this.collapsed && this.value <= this.s.collapseAt + 0.001) this.collapsed = true;
    if (this.collapsed && this.value >= this.s.recoverAt) this.collapsed = false;
  }

  spend(amount: number): void {
    if (this.collapsed || amount <= 0) return;
    this.value = Math.max(this.s.collapseAt, this.value - amount);
    if (this.value <= this.s.collapseAt + 0.001) this.collapsed = true;
  }

  /** 1 = full power, scales down near empty. */
  motorScale(): number {
    if (this.collapsed) return this.s.collapseMotorScale;
    const t = this.value / this.max;
    // smoothstep between 0 and 0.28
    const x = Math.min(1, Math.max(0, t / 0.28));
    const ss = x * x * (3 - 2 * x);
    return Math.max(this.s.collapseMotorScale, ss);
  }

  fraction(): number { return this.value / this.max; }
}
