// Desktop-first player input with touch/gamepad fallbacks.
// Mouse/right stick owns the weapon hand; WASD owns the shield hand.
// Space is duration-sensitive: hold to walk forward, tap to step backward.
// On touch only, horizontal shield-ring travel also owns locomotion.
import { Vec2 } from 'planck';
import { CFG } from '../config';
import { FighterInput } from '../types';
import { Fighter } from '../physics/Fighter';

interface Stick {
  active: boolean;
  id: number;
  originX: number;
  originY: number;
  x: number;
  y: number;
}

export const SPACE_HOLD_MS = 80;
export const SPACE_TAP_BACK_MS = 760;
export const TOUCH_RING_RADIUS = 56;
export const MOUSE_WEAPON_RADIUS = 92;
export const TOUCH_SHIELD_WALK_THRESHOLD = 0.30;
export const TOUCH_SHIELD_WALK_VERTICAL_RATIO = 0.55;

export interface ControlsDiagnostics {
  mouseWeapon: {
    active: boolean;
    x: number;
    y: number;
    magnitude: number;
    angle: number | null;
    travel: number;
    gestureId: number | null;
    pending: boolean;
  };
}

/** Keep the single click marker entirely inside the game surface. */
export function mouseAimDotPosition(
  clientX: number, clientY: number, width: number, height: number, radius = 9,
): { x: number; y: number } {
  return {
    x: Math.max(radius, Math.min(width - radius, clientX)),
    y: Math.max(radius, Math.min(height - radius, clientY)),
  };
}

/** Circular virtual-stick mapping. Unlike per-axis clamping, diagonal input
 * cannot push the knob outside its ring. Screen-down y becomes world-up y. */
export function joystickVector(dx: number, dy: number, radius = TOUCH_RING_RADIUS): { x: number; y: number } {
  const distance = Math.hypot(dx, dy);
  if (distance < 0.001 || radius <= 0) return { x: 0, y: 0 };
  const magnitude = Math.min(1, distance / radius);
  return { x: dx / distance * magnitude, y: -dy / distance * magnitude };
}

/** Desktop weapon aim is a hidden relative stick anchored at mouse-down. This
 * keeps the whole 360-degree range available even when the fighter is near a
 * screen edge; only the white cursor dot is rendered. */
export function mouseWeaponVector(originX: number, originY: number, clientX: number, clientY: number): { x: number; y: number } {
  return joystickVector(clientX - originX, clientY - originY, MOUSE_WEAPON_RADIUS);
}

export function accumulatePointerAngle(
  previousAngle: number, travel: number, nextAngle: number,
): { previousAngle: number; travel: number } {
  return {
    previousAngle: nextAngle,
    travel: travel + Math.atan2(
      Math.sin(nextAngle - previousAngle),
      Math.cos(nextAngle - previousAngle),
    ),
  };
}

export function resolveSpaceMove(
  nowMs: number, isDown: boolean, downAtMs: number, backwardUntilMs: number, facing: 1 | -1,
): number {
  if (isDown && nowMs - downAtMs >= SPACE_HOLD_MS) return facing;
  if (!isDown && nowMs < backwardUntilMs) return -facing;
  return 0;
}

export function resolveFacingKeyMove(backward: boolean, forward: boolean, facing: 1 | -1): number {
  return ((forward ? 1 : 0) - (backward ? 1 : 0)) * facing;
}

/** Mobile locomotion follows deliberate horizontal shield travel. Raw touch x
 * is already a world-screen direction: right walks right and left walks left,
 * including after the fighter turns. Mostly vertical guard moves stay planted. */
export function resolveMobileShieldMove(active: boolean, x: number, y: number): number {
  if (!active) return 0;
  const horizontal = Math.abs(x);
  if (horizontal < TOUCH_SHIELD_WALK_THRESHOLD) return 0;
  if (horizontal < Math.abs(y) * TOUCH_SHIELD_WALK_VERTICAL_RATIO) return 0;
  return x > 0 ? 1 : -1;
}

export class Controls {
  private keys = new Set<string>();
  private stickL: Stick = { active: false, id: -1, originX: 0, originY: 0, x: 0, y: 0 };
  private stickR: Stick = { active: false, id: -1, originX: 0, originY: 0, x: 0, y: 0 };
  private stepQueued: -1 | 0 | 1 = 0;
  private mouseSword = {
    active: false, id: -1, originX: 0, originY: 0, vector: Vec2(0, 0),
    gestureId: 0, startAngle: null as number | null,
    previousAngle: null as number | null, travel: 0,
  };
  private pendingMouseSword: {
    gestureId: number;
    startAngle: number;
    travel: number;
    vector: Vec2;
    until: number;
  } | null = null;
  private spaceDown = false;
  private spaceDownAt = -Infinity;
  private spaceBackwardUntil = -Infinity;
  private clientToWorld: ((x: number, y: number) => Vec2) | null = null;
  enabled = true;
  canvas: HTMLCanvasElement | null = null;

  private handleKeyDown = (e: KeyboardEvent): void => {
    if (!this.enabled) return;
    const k = e.key.toLowerCase();
    if (e.code === 'Space' || e.key === ' ') {
      e.preventDefault();
      if (!this.spaceDown) {
        this.spaceDown = true;
        this.spaceDownAt = performance.now();
        this.spaceBackwardUntil = -Infinity;
      }
      return;
    }
    if (k === 'z') this.stepQueued = -1;
    if (k === 'x') this.stepQueued = 1;
    if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) e.preventDefault();
    this.keys.add(k);
  };

  private handleKeyUp = (e: KeyboardEvent): void => {
    if (e.code === 'Space' || e.key === ' ') {
      const now = performance.now();
      if (this.spaceDown && now - this.spaceDownAt < SPACE_HOLD_MS) {
        this.spaceBackwardUntil = now + SPACE_TAP_BACK_MS;
      }
      this.spaceDown = false;
      e.preventDefault();
      return;
    }
    this.keys.delete(e.key.toLowerCase());
  };

  private handleBlur = (): void => {
    this.keys.clear();
    this.spaceDown = false;
    this.spaceBackwardUntil = -Infinity;
    this.mouseSword.active = false;
    this.mouseSword.id = -1;
    this.mouseSword.startAngle = null;
    this.mouseSword.previousAngle = null;
    this.mouseSword.travel = 0;
    this.pendingMouseSword = null;
    this.resetTouchStickUi(this.stickL, true);
    this.resetTouchStickUi(this.stickR, false);
    this.hideMouseAimDot();
  };

  private handlePointerDown = (e: PointerEvent): void => this.onPointerDown(e);
  private handlePointerMove = (e: PointerEvent): void => this.onPointerMove(e);
  private handlePointerUp = (e: PointerEvent): void => this.onPointerUp(e);
  private handlePointerLeave = (e: PointerEvent): void => this.onPointerLeave(e);

  attach(canvas: HTMLCanvasElement, clientToWorld: (x: number, y: number) => Vec2): void {
    this.detach();
    this.canvas = canvas;
    this.clientToWorld = clientToWorld;
    window.addEventListener('keydown', this.handleKeyDown);
    window.addEventListener('keyup', this.handleKeyUp);
    window.addEventListener('blur', this.handleBlur);
    canvas.addEventListener('pointerdown', this.handlePointerDown);
    canvas.addEventListener('pointermove', this.handlePointerMove);
    canvas.addEventListener('pointerup', this.handlePointerUp);
    canvas.addEventListener('pointercancel', this.handlePointerUp);
    canvas.addEventListener('pointerleave', this.handlePointerLeave);
    canvas.style.touchAction = 'none';
  }

  detach(): void {
    window.removeEventListener('keydown', this.handleKeyDown);
    window.removeEventListener('keyup', this.handleKeyUp);
    window.removeEventListener('blur', this.handleBlur);
    if (this.canvas) {
      this.canvas.removeEventListener('pointerdown', this.handlePointerDown);
      this.canvas.removeEventListener('pointermove', this.handlePointerMove);
      this.canvas.removeEventListener('pointerup', this.handlePointerUp);
      this.canvas.removeEventListener('pointercancel', this.handlePointerUp);
      this.canvas.removeEventListener('pointerleave', this.handlePointerLeave);
    }
    this.canvas = null;
    this.clientToWorld = null;
    this.mouseSword.active = false;
    this.stickL.active = false;
    this.stickR.active = false;
    this.handleBlur();
    this.hideMouseAimDot();
  }

  private rect(): DOMRect { return this.canvas!.getBoundingClientRect(); }
  private isLeftHalf(e: PointerEvent): boolean {
    const r = this.rect();
    return (e.clientX - r.left) < r.width / 2;
  }

  private touchRingCenter(left: boolean): { x: number; y: number } | null {
    const ring = document.getElementById(left ? 'touchStickL' : 'touchStickR');
    if (!ring) return null;
    const r = ring.getBoundingClientRect();
    if (r.width <= 0 || r.height <= 0) return null;
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  }

  private updateTouchStickUi(stick: Stick, left: boolean): void {
    const ring = document.getElementById(left ? 'touchStickL' : 'touchStickR');
    const knob = ring?.querySelector<HTMLElement>('.touchStickKnob');
    if (!ring || !knob) return;
    ring.classList.toggle('active', stick.active);
    const travel = 25;
    knob.style.transform = `translate(calc(-50% + ${stick.x * travel}px), calc(-50% + ${-stick.y * travel}px))`;
  }

  private resetTouchStickUi(stick: Stick, left: boolean): void {
    stick.active = false;
    stick.id = -1;
    stick.x = 0;
    stick.y = 0;
    this.updateTouchStickUi(stick, left);
  }

  private onPointerDown(e: PointerEvent): void {
    if (!this.enabled) return;
    e.preventDefault();
    // Pointer capture can be rejected for synthetic QA events and for a real
    // pointer that the browser has already cancelled. Weapon control must
    // still start; capture only extends an otherwise valid drag off-canvas.
    try { this.canvas?.setPointerCapture?.(e.pointerId); } catch { /* keep local control active */ }
    if (e.pointerType === 'mouse') {
      this.mouseSword.active = true;
      this.mouseSword.id = e.pointerId;
      this.mouseSword.originX = e.clientX;
      this.mouseSword.originY = e.clientY;
      this.mouseSword.vector.setZero();
      this.mouseSword.gestureId++;
      this.mouseSword.startAngle = null;
      this.mouseSword.previousAngle = null;
      this.mouseSword.travel = 0;
      this.pendingMouseSword = null;
      this.trackMouseWeapon(e);
      return;
    }
    const left = this.isLeftHalf(e);
    const s = left ? this.stickL : this.stickR;

    if (!s.active) {
      s.active = true; s.id = e.pointerId;
      const center = this.touchRingCenter(left);
      s.originX = center?.x ?? e.clientX;
      s.originY = center?.y ?? e.clientY;
      const v = joystickVector(e.clientX - s.originX, e.clientY - s.originY);
      s.x = v.x; s.y = v.y;
      this.updateTouchStickUi(s, left);
    }
  }

  private onPointerMove(e: PointerEvent): void {
    if (e.pointerType === 'mouse') {
      if (this.mouseSword.active && this.mouseSword.id === e.pointerId) this.trackMouseWeapon(e);
      return;
    }
    const s = e.pointerId === this.stickL.id ? this.stickL : e.pointerId === this.stickR.id ? this.stickR : null;
    if (!s || !s.active) return;
    const v = joystickVector(e.clientX - s.originX, e.clientY - s.originY);
    s.x = v.x;
    s.y = v.y;
    this.updateTouchStickUi(s, s === this.stickL);
  }

  private onPointerUp(e: PointerEvent): void {
    if (e.pointerType === 'mouse') {
      if (this.mouseSword.id === e.pointerId) {
        if (this.mouseSword.startAngle !== null) {
          this.pendingMouseSword = {
            gestureId: this.mouseSword.gestureId,
            startAngle: this.mouseSword.startAngle,
            travel: this.mouseSword.travel,
            vector: this.mouseSword.vector.clone(),
            // Preserve the final raw pointer sample briefly so a quick circle
            // completed between render frames still reaches the physics loop.
            until: performance.now() + 850,
          };
        }
        this.mouseSword.active = false;
        this.mouseSword.id = -1;
        this.mouseSword.vector.setZero();
        this.hideMouseAimDot();
      }
      return;
    }
    for (const [s, left] of [[this.stickL, true], [this.stickR, false]] as const) {
      if (s.active && s.id === e.pointerId) {
        this.resetTouchStickUi(s, left);
      }
    }
  }

  private onPointerLeave(e: PointerEvent): void {
    if (e.pointerType !== 'mouse') return;
    // Pointer capture deliberately keeps a drag alive beyond the canvas edge,
    // so a full circular weapon gesture cannot be cancelled by the viewport.
    if (this.canvas?.hasPointerCapture?.(e.pointerId)) return;
    this.mouseSword.active = false;
    this.mouseSword.id = -1;
    this.mouseSword.vector.setZero();
    this.hideMouseAimDot();
  }

  private trackMouseWeapon(e: PointerEvent): void {
    if (!this.enabled) return;
    const vector = mouseWeaponVector(
      this.mouseSword.originX, this.mouseSword.originY, e.clientX, e.clientY,
    );
    this.mouseSword.vector = Vec2(vector.x, vector.y);
    if (this.mouseSword.vector.length() >= CFG.fighter.hand.deadZone) {
      const wrappedAngle = Math.atan2(vector.y, vector.x);
      if (this.mouseSword.startAngle === null || this.mouseSword.previousAngle === null) {
        this.mouseSword.startAngle = wrappedAngle;
        this.mouseSword.previousAngle = wrappedAngle;
        this.mouseSword.travel = 0;
      } else {
        const accumulated = accumulatePointerAngle(
          this.mouseSword.previousAngle, this.mouseSword.travel, wrappedAngle,
        );
        this.mouseSword.travel = accumulated.travel;
        this.mouseSword.previousAngle = accumulated.previousAngle;
      }
    }
    this.placeMouseAimDot(e.clientX, e.clientY);
  }

  private placeMouseAimDot(clientX: number, clientY: number): void {
    if (!this.canvas) return;
    const r = this.rect();
    const dot = document.getElementById('mouseAimDot');
    if (!dot) return;
    const p = mouseAimDotPosition(clientX - r.left, clientY - r.top, r.width, r.height);
    dot.style.left = `${p.x}px`;
    dot.style.top = `${p.y}px`;
    dot.classList.add('active');
    this.canvas.classList.add('mouseAiming');
  }

  private hideMouseAimDot(): void {
    document.getElementById('mouseAimDot')?.classList.remove('active');
    this.canvas?.classList.remove('mouseAiming');
  }

  private keyboardVec(left: boolean): Vec2 {
    let x = 0, y = 0;
    if (left) {
      if (this.keys.has('a')) x -= 1;
      if (this.keys.has('d')) x += 1;
      if (this.keys.has('w')) y += 1;
      if (this.keys.has('s')) y -= 1;
    } else {
      if (this.keys.has('arrowleft')) x -= 1;
      if (this.keys.has('arrowright')) x += 1;
      if (this.keys.has('arrowup')) y += 1;
      if (this.keys.has('arrowdown')) y -= 1;
    }
    const m = Math.hypot(x, y);
    // Preserve independent WASD axes for the shield. W+D must reach a real
    // rectangular corner rather than being normalized back onto a circle.
    if (left) return Vec2(x, y);
    return m > 0 ? Vec2(x / m, y / m) : Vec2(0, 0);
  }

  private gamepadVec(idxAxes: [number, number]): Vec2 | null {
    const gps = navigator.getGamepads?.() ?? [];
    const gp = gps[0];
    if (!gp) return null;
    const x = gp.axes[idxAxes[0]] ?? 0;
    const y = -(gp.axes[idxAxes[1]] ?? 0);
    const dz = 0.2;
    if (Math.abs(x) < dz && Math.abs(y) < dz) return Vec2(0, 0);
    return Vec2(Math.max(-1, Math.min(1, x)), Math.max(-1, Math.min(1, y)));
  }

  /** Produce the fighter input packet for this frame. */
  poll(player: Fighter, enabled: boolean): FighterInput {
    const now = performance.now();
    const spaceMove = resolveSpaceMove(now, this.spaceDown, this.spaceDownAt, this.spaceBackwardUntil, player.facing);
    // Q/E are explicit hold controls for desktop players who want sustained
    // backward/forward travel. They remain facing-relative when a fighter
    // turns, unlike the old world-axis fallback.
    const legacyMove = resolveFacingKeyMove(this.keys.has('q'), this.keys.has('e'), player.facing);
    const touchMove = resolveMobileShieldMove(this.stickL.active, this.stickL.x, this.stickL.y);
    const move = spaceMove || legacyMove || touchMove;
    const out: FighterInput = { left: null, right: null, step: 0, move, brace: this.keys.has('shift') };
    if (!enabled) { this.stepQueued = 0; return out; }
    if (this.pendingMouseSword && now > this.pendingMouseSword.until) {
      this.pendingMouseSword = null;
    }
    const mouseGesture = this.mouseSword.active && this.mouseSword.startAngle !== null
      ? {
        id: this.mouseSword.gestureId,
        startAngle: this.mouseSword.startAngle,
        travel: this.mouseSword.travel,
        active: true,
        vector: this.mouseSword.vector,
      }
      : this.pendingMouseSword
        ? {
          id: this.pendingMouseSword.gestureId,
          startAngle: this.pendingMouseSword.startAngle,
          travel: this.pendingMouseSword.travel,
          active: false,
          vector: this.pendingMouseSword.vector,
        }
        : null;

    const gpL = this.gamepadVec([0, 1]);
    const gpR = this.gamepadVec([2, 3]);
    if (gpL || gpR) {
      const gp = navigator.getGamepads?.()[0];
      if (gp?.buttons?.[4]?.pressed) this.stepQueued = -1;
      if (gp?.buttons?.[5]?.pressed) this.stepQueued = 1;
    }

    const zones = (side: 'L' | 'R'): Vec2 | null => {
      if (side === 'R' && mouseGesture &&
          mouseGesture.vector.length() >= CFG.fighter.hand.deadZone) {
        return player.stickToWorld('R', mouseGesture.vector);
      }
      const stick = side === 'L' ? this.stickL : this.stickR;
      const kb = this.keyboardVec(side === 'L');
      const gp = side === 'L' ? gpL : gpR;
      let u: Vec2 | null = null;
      if (stick.active && (Math.abs(stick.x) > 0.04 || Math.abs(stick.y) > 0.04)) u = Vec2(stick.x, stick.y);
      else if (kb.lengthSquared() > 0.001) u = kb;
      else if (gp && gp.lengthSquared() > 0.001) u = gp;
      if (!u) return null;
      const dz = CFG.fighter.hand.deadZone;
      if (u.length() < dz) return null;
      return side === 'L' ? player.shieldToWorld(u) : player.stickToWorld(side, u);
    };

    out.left = zones('L');
    out.right = zones('R');
    out.rightGesture = mouseGesture ? {
      id: mouseGesture.id,
      startAngle: mouseGesture.startAngle,
      travel: mouseGesture.travel,
      active: mouseGesture.active,
    } : null;
    out.step = this.stepQueued;
    this.stepQueued = 0;
    return out;
  }

  diagnostics(): ControlsDiagnostics {
    const x = this.mouseSword.vector.x;
    const y = this.mouseSword.vector.y;
    const magnitude = Math.hypot(x, y);
    return {
      mouseWeapon: {
        active: this.mouseSword.active,
        x,
        y,
        magnitude,
        angle: magnitude >= CFG.fighter.hand.deadZone ? Math.atan2(y, x) : null,
        travel: this.mouseSword.travel,
        gestureId: this.mouseSword.startAngle === null ? null : this.mouseSword.gestureId,
        pending: !!this.pendingMouseSword,
      },
    };
  }
}
