// In-browser automated verification. Runs a scripted scenario against the real
// Game instance, asserts physical behavior, and reports PASS/FAIL lines into
// #testlog (readable via get_text) and into document.title.
import { Vec2 } from 'planck';
import { Game } from '../core/Game';
import { FighterInput, IDLE_INPUT } from '../types';

interface Check { name: string; pass: boolean; detail: string }

export function runAutoTest(game: Game, log: (line: string) => void): void {
  const checks: Check[] = [];
  const input: FighterInput = { ...IDLE_INPUT };
  game.overridePlayerInput = input;

  let phase = 0;
  let phaseT = 0;
  let maxTip = 0;
  let startX = 0;
  let startHand: Vec2 | null = null;
  let torsoTissueBefore = 0;
  let done = false;

  const finish = () => {
    done = true;
    const passed = checks.filter(c => c.pass).length;
    const total = checks.length;
    log('----------------------------------------');
    for (const c of checks) log(`${c.pass ? 'PASS' : 'FAIL'}  ${c.name} :: ${c.detail}`);
    log('----------------------------------------');
    log(`RESULT ${passed}/${total} PASSED`);
    document.title = `IB-AUTOTEST ${passed}/${total}`;
  };

  const origStep = game.step.bind(game);
  game.step = (dt: number) => {
    origStep(dt);
    if (done || game.state !== 'fight') return;
    phaseT += dt;
    const P = game.fighters[0];
    const F = game.fighters[1];
    maxTip = Math.max(maxTip, P.lastTipSpeed);

    switch (phase) {
      case 0: // spawn + settle
        if (phaseT > 2.0) {
          const y = P.pelvis().getPosition().y;
          const ang = Math.abs(P.torsoAngle());
          checks.push({
            name: 'fighter stands stable after 2 s',
            pass: y > 0.85 && y < 1.2 && ang < 0.35,
            detail: `pelvisY=${y.toFixed(2)} torsoAngle=${ang.toFixed(2)}`,
          });
          startHand = P.shoulderWorld('R').clone();
          startHand.x += 0.45; startHand.y -= 0.05;
          input.right = startHand;
          phase = 1; phaseT = 0;
        }
        break;
      case 1: // hand reach
        if (phaseT > 1.5) {
          const h = P.handWorld('R');
          const d = Math.hypot(h.x - startHand!.x, h.y - startHand!.y);
          checks.push({
            name: 'hand tracks target within 0.22 m',
            pass: d < 0.22,
            detail: `dist=${d.toFixed(3)}`,
          });
          phase = 2; phaseT = 0;
        }
        break;
      case 2: // circular swing builds tip speed
        {
          const s = P.shoulderWorld('R');
          const a = phaseT * 10;
          input.right = Vec2(s.x + Math.cos(a) * 0.5, s.y + Math.sin(a) * 0.5);
          if (phaseT > 2.2) {
            checks.push({
              name: 'swing produces tip speed > 4 m/s',
              pass: maxTip > 4,
              detail: `maxTip=${maxTip.toFixed(2)} (weapon=${P.weapon?.def.id})`,
            });
            input.right = null;
            startX = P.pelvis().getPosition().x;
            phase = 3; phaseT = 0;
          }
        }
        break;
      case 3: // step right
        input.step = 1;
        phase = 4; phaseT = 0;
        break;
      case 4:
        if (phaseT > 1.2) {
          const dx = P.pelvis().getPosition().x - startX;
          checks.push({
            name: 'double-tap step moves pelvis > 0.1 m',
            pass: dx > 0.1,
            detail: `dx=${dx.toFixed(3)}`,
          });
          phase = 5; phaseT = 0;
          // begin flailing to drain stamina
        }
        break;
      case 5: // drain stamina to collapse
        {
          const s = P.shoulderWorld('R');
          const a = phaseT * 14;
          input.right = Vec2(s.x + Math.cos(a) * 0.55, s.y + Math.sin(a) * 0.55);
          if (P.stamina.collapsed) {
            checks.push({
              name: 'stamina depletion causes collapse',
              pass: true,
              detail: `after ${phaseT.toFixed(1)}s of flailing, stamina=${P.stamina.value.toFixed(1)}`,
            });
            input.right = null;
            phase = 6; phaseT = 0;
          } else if (phaseT > 25) {
            checks.push({
              name: 'stamina depletion causes collapse',
              pass: false,
              detail: `no collapse after 25s, stamina=${P.stamina.value.toFixed(1)}`,
            });
            input.right = null;
            phase = 6; phaseT = 0;
          }
        }
        break;
      case 6: // recover
        if (!P.stamina.collapsed) {
          checks.push({
            name: 'fighter recovers from collapse',
            pass: true,
            detail: `recovered after ${phaseT.toFixed(1)}s, stamina=${P.stamina.value.toFixed(1)}`,
          });
          phase = 7; phaseT = 0;
          torsoTissueBefore = F.part('torso').tissue;
        } else if (phaseT > 8) {
          checks.push({
            name: 'fighter recovers from collapse',
            pass: false,
            detail: 'still collapsed after 8s',
          });
          phase = 7; phaseT = 0;
          torsoTissueBefore = F.part('torso').tissue;
        }
        break;
      case 7: // walk up and stab the (disabled-AI) foe in the torso
        {
          const t = F.torso().getPosition();
          const myX = P.pelvis().getPosition().x;
          const dist = Math.abs(t.x - myX);
          if (dist > 1.0) {
            if (phaseT % 0.9 < 0.05) input.step = P.facing; else input.step = 0;
          } else {
            input.step = 0;
            // thrust directly at foe torso
            input.right = Vec2(t.x, t.y + 0.05);
          }
          if (phaseT > 14) {
            const dmg = game.lastDamageEvents.filter(e => e.defenderId === 1);
            const torsoNow = F.part('torso').tissue;
            const headNow = F.part('head').tissue;
            const any = dmg.length > 0;
            checks.push({
              name: 'weapon contact deals damage',
              pass: any && (torsoNow < torsoTissueBefore || headNow < F.part('head').tissueMax || dmg.some(e => e.damage > 1)),
              detail: `events=${dmg.length} maxDmg=${any ? Math.max(...dmg.map(e => e.damage)).toFixed(1) : '0'} torso=${torsoNow.toFixed(1)}/${torsoTissueBefore}`,
            });
            // final: kill check via repeated stabbing is slow; assert AI-dummy death separately
            phase = 8; phaseT = 0;
          }
        }
        break;
      case 8: // physics sanity
        {
          let nan = false;
          for (let b = game.world.getBodyList(); b; b = b.getNext()) {
            const p = b.getPosition();
            if (!isFinite(p.x) || !isFinite(p.y)) nan = true;
          }
          checks.push({ name: 'no NaN/exploded bodies', pass: !nan, detail: nan ? 'NaN found' : 'all finite' });
          log('INFO  foe vitality=' + F.vitality().toFixed(1) + ' dead=' + F.dead);
          finish();
        }
        break;
    }
  };

  // start a duel with AI disabled so the scenario is deterministic
  game.startFight('training');
  game.disableAI = true;
  log('AUTOTEST START — deterministic scripted scenario vs training dummy');
}
