// WebAudio: procedural original sounds. Impulse-mapped impacts, UI ticks, stingers.
// No audio assets — every sound is synthesized at runtime (license-clean by construction).
export class AudioBus {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private volume = 0.5;
  private noiseBuf: AudioBuffer | null = null;
  private ambienceStop: (() => void) | null = null;
  ambienceKind: string | null = null; // exposed for QA/debug
  footstepCount = 0;
  lastFootstepIntensity = 0;
  enabled = true;

  setVolume(v: number): void {
    this.volume = Math.max(0, Math.min(1, v));
    if (this.master) this.master.gain.value = this.volume;
  }

  /** Current master gain, or null if the context has not been created yet (QA instrumentation). */
  get masterGain(): number | null {
    return this.master ? this.master.gain.value : null;
  }

  // ------------------------------------------------------------ ambience
  /** Looping arena ambience bed through the master gain (10d volume applies). */
  startAmbience(kind: 'wind' | 'rain' | 'crowd' | 'windrain'): void {
    if (this.ambienceKind === kind) return;
    this.stopAmbience();
    const ctx = this.ensure(); if (!ctx || !this.master) return;
    if (!this.noiseBuf) {
      const len = ctx.sampleRate * 2;
      this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
      const d = this.noiseBuf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    }
    const stops: OscillatorNode[] = [];
    const sources: AudioBufferSourceNode[] = [];
    const outs: GainNode[] = [];
    const bed = (build: (src: AudioBufferSourceNode, out: GainNode) => void, base: number): void => {
      const src = ctx.createBufferSource();
      src.buffer = this.noiseBuf; src.loop = true;
      const out = ctx.createGain();
      out.gain.value = base;
      build(src, out);
      out.connect(this.master!);
      src.start();
      sources.push(src);
      outs.push(out);
    };
    const lfo = (rate: number, depth: number, param: AudioParam): void => {
      const o = ctx.createOscillator();
      o.frequency.value = rate;
      const g = ctx.createGain();
      g.gain.value = depth;
      o.connect(g); g.connect(param);
      o.start();
      stops.push(o);
    };
    const wind = (base: number): void => bed((src, out) => {
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass'; f.frequency.value = 420; f.Q.value = 0.8;
      src.connect(f); f.connect(out);
      lfo(0.09 + Math.random() * 0.05, 210, f.frequency); // slow gusts
      lfo(0.31, 0.35 * base, out.gain);                    // swell
    }, base);
    const rain = (base: number): void => bed((src, out) => {
      const f = ctx.createBiquadFilter();
      f.type = 'highpass'; f.frequency.value = 1600;
      src.connect(f); f.connect(out);
      lfo(0.5, 0.12 * base, out.gain); // patter wobble
    }, base);
    if (kind === 'wind') wind(0.055);
    else if (kind === 'rain') rain(0.05);
    else if (kind === 'windrain') { wind(0.05); rain(0.045); }
    else if (kind === 'crowd') bed((src, out) => {
      const f = ctx.createBiquadFilter();
      f.type = 'bandpass'; f.frequency.value = 380; f.Q.value = 0.6; // murmur band
      src.connect(f); f.connect(out);
      lfo(0.17, 0.4 * 0.05, out.gain);  // crowd swell
      lfo(0.07, 90, f.frequency);       // murmur drift
    }, 0.05);
    this.ambienceKind = kind;
    this.ambienceStop = () => {
      for (const s of sources) { try { s.stop(); } catch { /* already stopped */ } s.disconnect(); }
      for (const o of stops) { try { o.stop(); } catch { /* already stopped */ } o.disconnect(); }
      for (const g of outs) g.disconnect(); // orphans the filter chain for GC
    };
  }

  stopAmbience(): void {
    this.ambienceStop?.();
    this.ambienceStop = null;
    this.ambienceKind = null;
  }

  private ensure(): AudioContext | null {
    if (!this.enabled) return null;
    if (!this.ctx) {
      try {
        this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
        this.master = this.ctx.createGain();
        this.master.gain.value = this.volume;
        this.master.connect(this.ctx.destination);
      } catch { this.enabled = false; }
    }
    if (this.ctx?.state === 'suspended') this.ctx.resume();
    return this.ctx;
  }

  private destination(ctx: AudioContext, pan: number): AudioNode {
    if (!this.master) throw new Error('audio master unavailable');
    if (typeof ctx.createStereoPanner !== 'function') return this.master;
    const panner = ctx.createStereoPanner();
    panner.pan.value = Math.max(-0.8, Math.min(0.8, pan));
    panner.connect(this.master);
    return panner;
  }

  /** Layered clean-room impact: transient crack, body thump and material ring. */
  impact(impulse: number, kind: 'flesh' | 'metal' | 'wood' = 'flesh', pan = 0): void {
    const ctx = this.ensure(); if (!ctx || !this.master) return;
    const strength = Math.max(0, Math.min(1, impulse / 60));
    if (strength < 0.04) return;
    const out = this.destination(ctx, pan);
    const now = ctx.currentTime;

    // Broad transient: short for metal, wetter and longer for flesh.
    const dur = (kind === 'flesh' ? 0.10 : 0.055) + strength * 0.13;
    const bufferSize = Math.floor(ctx.sampleRate * dur);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      const decay = 1 - i / bufferSize;
      const grit = Math.random() * 2 - 1;
      data[i] = grit * Math.pow(decay, kind === 'flesh' ? 1.5 : 3.2);
    }
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = kind === 'metal' ? 'highpass' : 'bandpass';
    filter.frequency.value = kind === 'metal' ? 1700 : kind === 'wood' ? 680 : 230;
    filter.Q.value = kind === 'flesh' ? 0.7 : 1.2;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.10 + strength * 0.48, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + dur);
    src.connect(filter); filter.connect(gain); gain.connect(out);
    src.start();

    // Low body impact gives even armored contacts readable weight.
    const thump = ctx.createOscillator();
    thump.type = 'sine';
    thump.frequency.setValueAtTime(kind === 'metal' ? 105 : kind === 'wood' ? 82 : 64, now);
    thump.frequency.exponentialRampToValueAtTime(38, now + 0.12 + strength * 0.06);
    const thumpGain = ctx.createGain();
    thumpGain.gain.setValueAtTime(0.035 + strength * 0.20, now);
    thumpGain.gain.exponentialRampToValueAtTime(0.001, now + 0.14 + strength * 0.08);
    thump.connect(thumpGain); thumpGain.connect(out);
    thump.start(now); thump.stop(now + 0.24);

    if (kind === 'metal') {
      // Two inharmonic partials read as steel rather than a gamey square beep.
      [760 + Math.random() * 160, 1280 + Math.random() * 260].forEach((frequency, i) => {
        const ring = ctx.createOscillator();
        ring.type = i === 0 ? 'triangle' : 'sine';
        ring.frequency.value = frequency;
        const ringGain = ctx.createGain();
        ringGain.gain.setValueAtTime(strength * (i === 0 ? 0.13 : 0.07), now);
        ringGain.gain.exponentialRampToValueAtTime(0.001, now + 0.10 + i * 0.08);
        ring.connect(ringGain); ringGain.connect(out);
        ring.start(now); ring.stop(now + 0.2);
      });
    } else if (kind === 'wood') {
      const crack = ctx.createOscillator();
      crack.type = 'triangle';
      crack.frequency.setValueAtTime(190 + Math.random() * 70, now);
      crack.frequency.exponentialRampToValueAtTime(95, now + 0.07);
      const crackGain = ctx.createGain();
      crackGain.gain.setValueAtTime(strength * 0.11, now);
      crackGain.gain.exponentialRampToValueAtTime(0.001, now + 0.09);
      crack.connect(crackGain); crackGain.connect(out);
      crack.start(now); crack.stop(now + 0.1);
    }
  }

  /** Short randomized steel-link cluster for articulated flail motion/contacts. */
  chain(strength: number, pan = 0): void {
    const ctx = this.ensure(); if (!ctx || !this.master) return;
    const amount = Math.max(0, Math.min(1, strength / 45));
    if (amount < 0.08) return;
    const out = this.destination(ctx, pan);
    for (let i = 0; i < 4; i++) {
      const t = ctx.currentTime + i * 0.018 + Math.random() * 0.012;
      const osc = ctx.createOscillator();
      osc.type = 'triangle';
      osc.frequency.value = 1050 + Math.random() * 1700;
      const gain = ctx.createGain();
      gain.gain.setValueAtTime(0.015 + amount * 0.045, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.035 + Math.random() * 0.025);
      osc.connect(gain); gain.connect(out);
      osc.start(t); osc.stop(t + 0.07);
    }
  }

  /** Original layered armored foot plant: earth/leather transient, body weight
   * and a restrained plate rattle. Driven by resolved heel-strike velocity. */
  footstep(intensity: number, pan = 0): void {
    const amount = Math.max(0.2, Math.min(1, intensity));
    this.footstepCount++;
    this.lastFootstepIntensity = amount;
    const ctx = this.ensure(); if (!ctx || !this.master) return;
    const out = this.destination(ctx, pan);
    const now = ctx.currentTime;

    const duration = 0.055 + amount * 0.045;
    const buffer = ctx.createBuffer(1, Math.ceil(ctx.sampleRate * duration), ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) {
      const decay = 1 - i / data.length;
      data[i] = (Math.random() * 2 - 1) * decay * decay;
    }
    const grit = ctx.createBufferSource();
    grit.buffer = buffer;
    const gritFilter = ctx.createBiquadFilter();
    gritFilter.type = 'bandpass';
    gritFilter.frequency.value = 310 + Math.random() * 100;
    gritFilter.Q.value = 0.75;
    const gritGain = ctx.createGain();
    gritGain.gain.setValueAtTime(0.025 + amount * 0.075, now);
    gritGain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    grit.connect(gritFilter); gritFilter.connect(gritGain); gritGain.connect(out);
    grit.start(now);

    const weight = ctx.createOscillator();
    weight.type = 'sine';
    weight.frequency.setValueAtTime(78 + amount * 14, now);
    weight.frequency.exponentialRampToValueAtTime(43, now + 0.105);
    const weightGain = ctx.createGain();
    weightGain.gain.setValueAtTime(0.025 + amount * 0.075, now);
    weightGain.gain.exponentialRampToValueAtTime(0.001, now + 0.115);
    weight.connect(weightGain); weightGain.connect(out);
    weight.start(now); weight.stop(now + 0.12);

    const plate = ctx.createOscillator();
    plate.type = 'triangle';
    plate.frequency.value = 620 + Math.random() * 260;
    const plateGain = ctx.createGain();
    plateGain.gain.setValueAtTime(0.007 + amount * 0.018, now + 0.008);
    plateGain.gain.exponentialRampToValueAtTime(0.001, now + 0.065);
    plate.connect(plateGain); plateGain.connect(out);
    plate.start(now + 0.008); plate.stop(now + 0.07);
  }

  grunt(strength: number): void {
    const ctx = this.ensure(); if (!ctx || !this.master || strength < 0.04) return;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(112 - strength * 28, now);
    osc.frequency.exponentialRampToValueAtTime(62, now + 0.16);
    const sub = ctx.createOscillator();
    sub.type = 'triangle';
    sub.frequency.setValueAtTime(73 - strength * 10, now);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.03 + strength * 0.10, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.20);
    const subGain = ctx.createGain();
    subGain.gain.setValueAtTime(0.012 + strength * 0.04, now);
    subGain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 430;
    osc.connect(filter); filter.connect(gain); gain.connect(this.master);
    sub.connect(subGain); subGain.connect(this.master);
    osc.start(); sub.start();
    osc.stop(now + 0.22); sub.stop(now + 0.20);
  }

  ui(): void {
    const ctx = this.ensure(); if (!ctx || !this.master) return;
    const osc = ctx.createOscillator();
    osc.type = 'square'; osc.frequency.value = 340;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.06, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.06);
    osc.connect(g); g.connect(this.master);
    osc.start(); osc.stop(ctx.currentTime + 0.07);
  }

  sting(win: boolean): void {
    const ctx = this.ensure(); if (!ctx) return;
    const master = this.master; if (!master) return;
    const notes = win ? [220, 330, 440] : [220, 174, 130];
    notes.forEach((f, i) => {
      const osc = ctx.createOscillator();
      osc.type = 'triangle'; osc.frequency.value = f;
      const g = ctx.createGain();
      const t = ctx.currentTime + i * 0.14;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(0.18, t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
      osc.connect(g); g.connect(master);
      osc.start(t); osc.stop(t + 0.4);
    });
  }
}
