// HUD bindings for combat bars + names.
import { Fighter } from '../physics/Fighter';

const LOW_STAMINA_FRAC = 0.28;
const CRITICAL_VITALITY_FRAC = 0.25;

export function clampHudFraction(value: number): number {
  return Number.isFinite(value) ? Math.max(0, Math.min(1, value)) : 0;
}

export function vitalityBand(value: number): 'healthy' | 'hurt' | 'critical' {
  const fraction = clampHudFraction(value);
  return fraction <= CRITICAL_VITALITY_FRAC ? 'critical' : fraction <= 0.55 ? 'hurt' : 'healthy';
}

export class Hud {
  private el = (id: string) => document.getElementById(id)!;

  show(v: boolean): void { this.el('hud').classList.toggle('hidden', !v); }

  update(a: Fighter, b: Fighter, labelA: string, labelB: string): void {
    this.updateBar('vitL', 'vitBarL', 'vitValueL', a.vitality() / 100, true);
    this.updateBar('vitR', 'vitBarR', 'vitValueR', b.vitality() / 100, true);
    this.updateBar('staL', 'staBarL', 'staValueL', a.stamina.fraction(), false);
    this.updateBar('staR', 'staBarR', 'staValueR', b.stamina.fraction(), false);
    this.el('nameL').textContent = labelA;
    this.el('nameR').textContent = labelB;
    this.el('wpnL').textContent = `WEAPON · ${a.weapon?.def.name ?? 'UNARMED'}`;
    this.el('wpnR').textContent = `WEAPON · ${b.weapon?.def.name ?? 'UNARMED'}`;
    this.staminaWarn(a, 'staBarL', 'warnL');
    this.staminaWarn(b, 'staBarR', 'warnR');
  }

  private updateBar(fillId: string, barId: string, valueId: string, raw: number, vitality: boolean): void {
    const fraction = clampHudFraction(raw);
    const percent = Math.round(fraction * 100);
    this.el(fillId).style.transform = `scaleX(${fraction})`;
    this.el(valueId).textContent = `${percent}%`;
    const bar = this.el(barId);
    bar.setAttribute('aria-valuenow', String(percent));
    if (vitality) bar.dataset.band = vitalityBand(fraction);
  }

  private staminaWarn(f: Fighter, barId: string, warnId: string): void {
    const collapsed = f.stamina.collapsed;
    const low = !collapsed && f.stamina.fraction() < LOW_STAMINA_FRAC;
    const bar = this.el(barId);
    bar.classList.toggle('low', low);
    bar.classList.toggle('collapsed', collapsed);
    const warn = this.el(warnId);
    warn.textContent = collapsed ? 'EXHAUSTED' : low ? 'LOW STAMINA' : '';
    warn.classList.toggle('show', collapsed || low);
  }
}
